import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures
const sessions: Record<string, { userId: string; role: string }> = {};
const users = [
  { id: "1", username: "admin", password: "password123", role: "administrator" },
  { id: "2", username: "nurse", password: "nursepass", role: "nurse" },
  { id: "3", username: "doctor", password: "docpass", role: "doctor" }
];

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate a mock token
  const token = `token-${Math.random().toString(36).substring(2, 15)}`;
  sessions[token] = { userId: user.id, role: user.role };

  return res.json({ token });
});

// Middleware to verify token and attach user info
const authenticate = (req: Request, res: Response, next: Function) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token || !sessions[token]) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  // Attach user info to request
  (req as any).user = sessions[token];
  next();
};

// Role-based authorization middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    const user = (req as any).user;
    if (!user || !roles.includes(user.role)) {
      return res.status(403).json({ error: "Forbidden" });
    }
    next();
  };
};

// Get authenticated user info
router.get("/me", authenticate, (req: Request, res: Response) => {
  const user = (req as any).user;
  const userData = users.find(u => u.id === user.userId);

  if (!userData) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({
    id: user.userId,
    username: userData.username,
    role: user.role
  });
});

// Logout endpoint
router.post("/logout", authenticate, (req: Request, res: Response) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (token) {
    delete sessions[token];
  }

  return res.json({ message: "Logged out successfully" });
});

// Example protected route for administrators
router.get("/admin", authenticate, authorize(["administrator"]), (req: Request, res: Response) => {
  return res.json({ message: "Admin access granted" });
});

