import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBytes = Buffer.from(expectedSignature, "base64url");
    const actualBytes = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBytes, actualBytes);
  } catch {
    return false;
  }
}

function getRoleFromToken(token: string): string | null {
  if (!isValidToken(token)) return null;

  try {
    const payload = token.split(".")[1];
    const decodedPayload = Buffer.from(payload, "base64url").toString();
    const parsed = JSON.parse(decodedPayload);
    return parsed.role || null;
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST /beds endpoint
  if (!(req.method === "POST" && req.path === "/beds")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const role = getRoleFromToken(token);

  if (!role) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Allow only medical staff to update bed statuses
  if (role !== "medical_staff") {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const JWT_SECRET = process.env.JWT_SECRET;

// Helper to check if a token is valid and not expired
function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  try {
    const expectedSignature = createHmac("sha256", JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");

    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

// Helper to parse JWT payload
function parsePayload(payload: string): any {
  try {
    return JSON.parse(Buffer.from(payload, "base64url").toString("utf-8"));
  } catch {
    return null;
  }
}

// Helper to check if token is expired
function isExpired(payload: any): boolean {
  if (!payload || !payload.exp) return true;
  return Date.now() >= payload.exp * 1000;
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests with a token in Authorization header
  if (req.method !== "POST" || !req.headers.authorization) {
    return next();
  }

  const authHeader = req.headers.authorization;
  const token = authHeader.startsWith("Bearer ") ? authHeader.substring(7) : authHeader;

  if (!token) {
    return res.status(401).json({ error: "Missing token" });
  }

  if (!isValidToken(token)) {
    return res.status(401).json({ error: "Invalid or expired token" });
  }

  const payload = parsePayload(token.split(".")[1]);
  if (!payload || isExpired(payload)) {
    return res.status(401).json({ error: "Invalid or expired token" });
  }

  // Token is valid and not expired
  next();
}

