import { useEffect, useState } from "react";

interface BedAvailability {
  totalBeds: number;
  availableBeds: number;
  occupiedBeds: number;
  wardName: string;
}

export function Dashboard() {
  const [bedData, setBedData] = useState<BedAvailability[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchBedData = async () => {
      try {
        const response = await fetch('/api/beds');
        if (!response.ok) {
          throw new Error('Failed to fetch bed data');
        }
        const data = await response.json();
        setBedData(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchBedData();
  }, []);

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (bedData.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No bed data available</div>;
  }

  const totalBeds = bedData.reduce((sum, ward) => sum + ward.totalBeds, 0);
  const availableBeds = bedData.reduce((sum, ward) => sum + ward.availableBeds, 0);
  const occupiedBeds = totalBeds - availableBeds;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Hospital Bed Availability Dashboard</h1>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', marginBottom: '30px' }}>
        <div style={{ backgroundColor: '#f0f8ff', borderRadius: '8px', padding: '15px', textAlign: 'center' }}>
          <h2>Total Beds</h2>
          <p style={{ fontSize: '2em', fontWeight: 'bold' }}>{totalBeds}</p>
        </div>

        <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
          <div style={{ flex: '1', minWidth: '150px', backgroundColor: '#e8f5e9', borderRadius: '8px', padding: '15px', textAlign: 'center' }}>
            <h2>Available Beds</h2>
            <p style={{ fontSize: '2em', fontWeight: 'bold', color: '#2e7d32' }}>{availableBeds}</p>
          </div>

          <div style={{ flex: '1', minWidth: '150px', backgroundColor: '#ffebee', borderRadius: '8px', padding: '15px', textAlign: 'center' }}>
            <h2>Occupied Beds</h2>
            <p style={{ fontSize: '2em', fontWeight: 'bold', color: '#c62828' }}>{occupiedBeds}</p>
          </div>
        </div>
      </div>

      <h2 style={{ textAlign: 'center' }}>Ward Availability</h2>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {bedData.map((ward) => (
          <div key={ward.wardName} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
            <h3>{ward.wardName}</h3>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Total Beds: {ward.totalBeds}</span>
              <span>Available: {ward.availableBeds}</span>
              <span>Occupied: {ward.occupiedBeds}</span>
            </div>
          </div>
        ))}
      </div>

      <div style={{ marginTop: '30px', textAlign: 'center' }}>
        <button 
          style={{ 
            backgroundColor: '#1976d2', 
            color: 'white', 
            border: 'none', 
            borderRadius: '4px', 
            padding: '10px 20px', 
            fontSize: '1rem', 
            cursor: 'pointer' 
          }}
          onClick={() => window.location.href = '/beds'}
        >
          Manage Beds
        </button>
      </div>
    </div>
  );
}

