];

// Get all trains
router.get("/trains", (req: Request, res: Response) => {
  res.json(trains);
});

// Get a specific train by ID
router.get("/trains/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const train = trains.find(t => t.id === id);

  if (!train) {
    return res.status(404).json({ error: "Train not found" });
  }

  res.json(train);
});

// Create a new train
router.post("/trains", (req: Request, res: Response) => {
  const { name, route, departureTime, arrivalTime, totalSeats } = req.body;

  if (!name || !route || !departureTime || !arrivalTime || !totalSeats) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newTrain = {
    id: trains.length > 0 ? Math.max(...trains.map(t => t.id)) + 1 : 1,
    name,
    route,
    departureTime,
    arrivalTime,
    totalSeats,
    availableSeats: totalSeats
  };

  trains.push(newTrain);
  res.status(201).json(newTrain);
});

// Update a train
router.put("/trains/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const trainIndex = trains.findIndex(t => t.id === id);

  if (trainIndex === -1) {
    return res.status(404).json({ error: "Train not found" });
  }

  const { name, route, departureTime, arrivalTime, totalSeats, availableSeats } = req.body;

  trains[trainIndex] = {
    ...trains[trainIndex],
    name: name || trains[trainIndex].name,
    route: route || trains[trainIndex].route,
    departureTime: departureTime || trains[trainIndex].departureTime,
    arrivalTime: arrivalTime || trains[trainIndex].arrivalTime,
    totalSeats: totalSeats || trains[trainIndex].totalSeats,
    availableSeats: availableSeats !== undefined ? availableSeats : trains[trainIndex].availableSeats
  };

  res.json(trains[trainIndex]);
});

// Delete a train
router.delete("/trains/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const trainIndex = trains.findIndex(t => t.id === id);

  if (trainIndex === -1) {
    return res.status(404).json({ error: "Train not found" });
  }

  trains.splice(trainIndex, 1);
  res.json({ message: "Train deleted successfully" });
});

