import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function verifyTokenSignature(token: string): boolean {
  if (!JWT_SECRET) return false;

  const [header, payload, signature] = token.split(".");
  if (!header || !payload || !signature) return false;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const actualSignature = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    return timingSafeEqual(actualSignature, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  if (!JWT_SECRET) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Check if authorization header exists
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify token signature
  if (!verifyTokenSignature(token)) {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // Token is valid, proceed
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using scrypt
  const salt = randomBytes(16).toString("hex");
  const key = scryptSync(req.body.password, salt, 32);
  const hashedPassword = key.toString("hex");

  // Replace the password with the hashed version
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST /admin routes
  if (!(req.method === "POST" && req.path.startsWith("/admin"))) {
    next();
    return;
  }

  // Check if user has staff role
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (userRole !== "staff") {
    res.status(403).json({ error: "Access denied. Staff role required." });
    return;
  }

  next();
}

