// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  customers: [
    { id: "1", name: "John Doe", service: "Haircut", status: "waiting", timestamp: new Date().toISOString() },
    { id: "2", name: "Jane Smith", service: "Beard Trim", status: "completed", timestamp: new Date().toISOString() }
  ],

  getAllCustomers: (): Promise<any[]> => {
    return Promise.resolve(mockDatabase.customers);
  },

  getCustomerById: (id: string): Promise<any | null> => {
    const customer = mockDatabase.customers.find(c => c.id === id);
    return Promise.resolve(customer || null);
  },

  createCustomer: (customerData: any): Promise<any> => {
    const newCustomer = {
      id: (mockDatabase.customers.length + 1).toString(),
      ...customerData,
      timestamp: new Date().toISOString()
    };
    mockDatabase.customers.push(newCustomer);
    return Promise.resolve(newCustomer);
  },

  updateCustomer: (id: string, updateData: any): Promise<any | null> => {
    const customerIndex = mockDatabase.customers.findIndex(c => c.id === id);
    if (customerIndex === -1) return Promise.resolve(null);

    const updatedCustomer = {
      ...mockDatabase.customers[customerIndex],
      ...updateData
    };

    mockDatabase.customers[customerIndex] = updatedCustomer;
    return Promise.resolve(updatedCustomer);
  },

  deleteCustomer: (id: string): Promise<boolean> => {
    const initialLength = mockDatabase.customers.length;
    mockDatabase.customers = mockDatabase.customers.filter(c => c.id !== id);
    return Promise.resolve(mockDatabase.customers.length < initialLength);
  }
};

