});

// GET /queue/:id - Get a specific customer by ID
router.get("/queue/:id", async (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const customer = await mockDatabase.getCustomerById(id);

    if (!customer) {
      return res.status(404).json({ error: "Customer not found" });
    }

    res.json(customer);
  } catch (error) {
    res.status(500).json({ error: "Failed to retrieve customer" });
  }
});

// POST /queue - Add a new customer to queue
router.post("/queue", async (req: Request, res: Response) => {
  try {
    const { name, service } = req.body;

    if (!name || !service) {
      return res.status(400).json({ error: "Name and service are required" });
