// Mock user database - in a real app this would be a proper database
const users = [
  { id: 1, username: "admin", password: "admin123", role: "admin" },
  { id: 2, username: "staff1", password: "staff123", role: "staff" },
  { id: 3, username: "staff2", password: "staff456", role: "staff" }
];

// Mock session store - in a real app this would be a proper session store
const sessions = new Map<string, { userId: number; role: string; expires: Date }>();

// Middleware to verify token
const authenticateToken = (req: Request, res: Response, next: Function) => {
  const authHeader = req.headers["authorization"];
  const token = authHeader && authHeader.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "Access token required" });
  }

  const session = sessions.get(token);
  if (!session || new Date() > session.expires) {
    return res.status(403).json({ error: "Invalid or expired token" });
  }

  // Add user info to request object
  (req as any).user = { id: session.userId, role: session.role };
  next();
};

// Role-based authorization middleware
const authorizeRoles = (...roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    const user = (req as any).user;
    if (!user || !roles.includes(user.role)) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }
    next();
  };
};

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password required" });
  }

  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate a mock token
  const token = `token-${Math.random().toString(36).substring(2, 15)}`;

  // Store session (in a real app, this would be in a database)
  const expires = new Date();
  expires.setHours(expires.getHours() + 1); // Token expires in 1 hour
  sessions.set(token, { userId: user.id, role: user.role, expires });

  res.json({ token, user: { id: user.id, role: user.role } });
});

// Get current user info
router.get("/me", authenticateToken, (req: Request, res: Response) => {
  const user = (req as any).user;
  res.json({ id: user.id, role: user.role });
});

// Logout endpoint
router.post("/logout", authenticateToken, (req: Request, res: Response) => {
  const authHeader = req.headers["authorization"];
  const token = authHeader && authHeader.split(" ")[1];

  if (token) {
    sessions.delete(token);
  }

  res.json({ message: "Logged out successfully" });
});

// Admin-only endpoint example
router.get("/admin", authenticateToken, authorizeRoles("admin"), (req: Request, res: Response) => {
  res.json({ message: "Admin access granted" });
});

