import { useEffect, useState } from "react";

interface Customer {
  id: number;
  name: string;
  serviceType: string;
  status: "waiting" | "in-progress" | "completed";
}

export function CustomerListPage() {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCustomers();
  }, []);

  const fetchCustomers = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/customers");
      if (!response.ok) {
        throw new Error(`Failed to fetch customers: ${response.status}`);
      }
      const data = await response.json();
      setCustomers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const updateCustomerStatus = async (id: number, status: Customer["status"]) => {
    try {
      const response = await fetch(`/api/customers/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update customer: ${response.status}`);
      }

      // Refresh the customer list after updating
      await fetchCustomers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (customers.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No customers in the queue.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Customer Queue</h1>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "15px",
        }}
      >
        {customers.map((customer) => (
          <div
            key={customer.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              backgroundColor: "#f9f9f9",
            }}
          >
            <div>
              <h3 style={{ margin: "0 0 5px 0" }}>{customer.name}</h3>
              <p style={{ margin: "0 0 5px 0", color: "#666" }}>
                Service: {customer.serviceType}
              </p>
              <p style={{ margin: "0", color: "#666" }}>
                Status: {customer.status}
              </p>
            </div>
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: "5px",
              }}
            >
              <button
                onClick={() =>
                  updateCustomerStatus(customer.id, "in-progress")
                }
                disabled={customer.status === "in-progress" || customer.status === "completed"}
                style={{
                  padding: "5px 10px",
                  backgroundColor: "#007bff",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  cursor: "pointer",
                }}
              >
                Start
              </button>
              <button
                onClick={() =>
                  updateCustomerStatus(customer.id, "completed")
                }
                disabled={customer.status === "completed"}
                style={{
                  padding: "5px 10px",
                  backgroundColor: "#28a745",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  cursor: "pointer",
                }}
              >
                Complete
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

