  const { location, status, seatNumber } = req.body;

  // Validate required fields
  if (!location || !status || !seatNumber) {
    return res.status(400).json({ error: "Location, status, and seatNumber are required" });
  }

  const newSeat = {
    id: nextId++,
    location,
    status,
    seatNumber
  };

  seats.push(newSeat);
  res.status(201).json(newSeat);
});

// PUT /seats/:id - Update a seat by ID
router.put("/seats/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const seatIndex = seats.findIndex(s => s.id === id);

  if (seatIndex === -1) {
    return res.status(404).json({ error: "Seat not found" });
  }

  const { location, status, seatNumber } = req.body;

  // Validate required fields
  if (!location || !status || !seatNumber) {
    return res.status(400).json({ error: "Location, status, and seatNumber are required" });
