  const id = Number(req.params.id);
  const seatIndex = seats.findIndex(s => s.id === id);

  if (seatIndex === -1) {
    return res.status(404).json({ error: "Seat not found" });
  }

  seats.splice(seatIndex, 1);
  res.json({ message: "Seat deleted successfully" });
});

