import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to booking-related routes
  if (!req.path.startsWith("/bookings") || (req.method !== "POST" && req.method !== "GET")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT properly
  // For this exercise, we'll just check if it has a valid format
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // In a real implementation, we would verify the signature here
  // This is a simplified version that just checks if the token exists
  // and has the right structure
  try {
    // Attempt to decode the payload (this is a simplified check)
    const payload = JSON.parse(Buffer.from(parts[1], "base64").toString());

    // Check if the user has student role
    if (payload.role !== "student") {
      res.status(403).json({ error: "Forbidden: Student role required" });
      return;
    }

    // If we get here, the user is authorized
    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

