import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
    // Skip validation for GET requests without body
    if (req.method === "GET" && !req.body) {
        return next();
    }

    // Only validate POST, PUT, PATCH requests
    if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
        return next();
    }

    // Validate request body for SQL injection patterns
    const sqlPatterns = ["';--", '";--', "';", '";', '--', '/*', '*/'];

    const validateBody = (obj: any): boolean => {
        if (typeof obj === 'string') {
            for (const pattern of sqlPatterns) {
                if (obj.includes(pattern)) {
                    return false;
                }
            }
            return true;
        }

        if (Array.isArray(obj)) {
            return obj.every(validateBody);
        }

        if (typeof obj === 'object' && obj !== null) {
            return Object.values(obj).every(validateBody);
        }

        return true;
    };

    // Check if body contains SQL injection patterns
    if (req.body && !validateBody(req.body)) {
        return res.status(400).json({ error: 'Invalid input data detected' });
    }

    next();
}

