import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { verify } from "jsonwebtoken";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    res.status(401).json({ error: "No token provided" });
    return;
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "JWT secret not configured" });
    return;
  }

  try {
    // Verify the token signature
    const payload = verify(token, secret);

    // If we get here, the token is valid
    (req as any).user = payload;
    next();
  } catch (error) {
    // Check if the error is due to invalid signature
    if (error instanceof Error && error.message.includes("invalid signature")) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // For any other error, treat as invalid token
    res.status(401).json({ error: "Invalid token" });
    return;
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests without body
  if (req.method === "GET" && !req.body) {
    return next();
  }

  // Validate Content-Type for requests with body
  if (req.body !== undefined && req.get("Content-Type") !== "application/json") {
    return res.status(400).json({ error: "Content-Type must be application/json" });
  }

  // Validate request body structure if present
  if (req.body !== undefined) {
    try {
      // Check if body is valid JSON
      const parsed = JSON.parse(JSON.stringify(req.body));

      // Basic validation - ensure no dangerous characters in string fields
      const validateString = (str: unknown): boolean => {
        if (typeof str !== "string") return false;
        // Check for common injection patterns
        return !/([<>'"\\])/.test(str);
      };

      const validateObject = (obj: any): boolean => {
        if (obj === null || typeof obj !== "object") return true;

        for (const [key, value] of Object.entries(obj)) {
          if (typeof value === "string" && !validateString(value)) {
            return false;
          }
          if (typeof value === "object" && !validateObject(value)) {
            return false;
          }
        }

        return true;
      };

      if (!validateObject(parsed)) {
        return res.status(400).json({ error: "Invalid input data" });
      }
    } catch (err) {
      return res.status(400).json({ error: "Invalid JSON in request body" });
    }
  }

  next();
}

