import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to task-related routes
  if (!req.path.startsWith("/tasks") || (req.method !== "POST" && req.method !== "PUT" && req.method !== "DELETE")) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  try {
    const [userId, role] = token.split(":");

    if (!userId || !role) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // For demo purposes, we'll just check if user has appropriate role
    // In a real implementation, you'd verify the token signature
    const validRoles = ["admin", "manager", "member"];

    if (!validRoles.includes(role)) {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    // Attach user info to request for downstream middleware/routes
    (req as any).user = { id: userId, role };

    // Allow access for valid roles
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to hash passwords during user registration or password updates
  // It should only process POST/PUT requests to specific routes related to user management

  // Only process POST/PUT requests to /users/register and /users/:id/password
  const isUserRegistration = req.method === "POST" && req.path === "/users/register";
  const isPasswordUpdate = req.method === "PUT" && req.path.match(/^\/users\/[^\/]+\/password$/);

  if (!isUserRegistration && !isPasswordUpdate) {
    next();
    return;
  }

  // If we're here, we're processing a password update
  if (!req.body || !req.body.password) {
    next();
    return;
  }

  // Hash the password
  const salt = randomBytes(16).toString("hex");
  const hashedPassword = scryptSync(req.body.password, salt, 64).toString("hex");

  // Replace the plain text password with the hashed one
  req.body.password = `${hashedPassword}:${salt}`;

  next();
}

import { useEffect, useState } from "react";

interface Task {
  id: number;
  title: string;
  description: string;
  deadline: string;
  status: "pending" | "in-progress" | "completed";
}

export function TaskListPage() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [filteredTasks, setFilteredTasks] = useState<Task[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | Task["status"]>("all");
  const [sortConfig, setSortConfig] = useState<{ key: keyof Task; direction: "asc" | "desc" } | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchTasks = async () => {
      try {
        const response = await fetch("/api/tasks");
        if (!response.ok) {
          throw new Error(`Failed to fetch tasks: ${response.status} ${response.statusText}`);
        }
        const tasksData = await response.json();
        setTasks(tasksData);
        setFilteredTasks(tasksData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchTasks();
  }, []);

  useEffect(() => {
    let result = [...tasks];

    // Apply search filter
    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      result = result.filter(
        task => 
          task.title.toLowerCase().includes(term) ||
          task.description.toLowerCase().includes(term)
      );
    }

    // Apply status filter
    if (statusFilter !== "all") {
      result = result.filter(task => task.status === statusFilter);
    }

    // Apply sorting
    if (sortConfig !== null) {
      result.sort((a, b) => {
        if (a[sortConfig.key] < b[sortConfig.key]) {
          return sortConfig.direction === "asc" ? -1 : 1;
        }
        if (a[sortConfig.key] > b[sortConfig.key]) {
          return sortConfig.direction === "asc" ? 1 : -1;
        }
        return 0;
      });
    }

    setFilteredTasks(result);
  }, [tasks, searchTerm, statusFilter, sortConfig]);

  const handleSort = (key: keyof Task) => {
    let direction: "asc" | "desc" = "asc";
    if (sortConfig && sortConfig.key === key && sortConfig.direction === "asc") {
      direction = "desc";
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: keyof Task) => {
    if (!sortConfig || sortConfig.key !== key) return " ↕️";
    return sortConfig.direction === "asc" ? " ↑" : " ↓";
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Task List</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search tasks..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value as "all" | Task["status"])}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Statuses</option>
          <option value="pending">Pending</option>
          <option value="in-progress">In Progress</option>
          <option value="completed">Completed</option>
        </select>
      </div>

      {filteredTasks.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>No tasks found.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ borderBottom: "2px solid #ccc" }}>
                <th style={{ padding: "10px", textAlign: "left", cursor: "pointer" }} onClick={() => handleSort("title")}>
                  Title{getSortIcon("title")}
                </th>
                <th style={{ padding: "10px", textAlign: "left", cursor: "pointer" }} onClick={() => handleSort("deadline")}>
                  Deadline{getSortIcon("deadline")}
                </th>
                <th style={{ padding: "10px", textAlign: "left", cursor: "pointer" }} onClick={() => handleSort("status")}>
                  Status{getSortIcon("status")}
                </th>
              </tr>
            </thead>
            <tbody>
              {filteredTasks.map(task => (
                <tr key={task.id} style={{ borderBottom: "1px solid #eee" }}>
                  <td style={{ padding: "10px" }}>
                    <div style={{ fontWeight: "bold" }}>{task.title}</div>
                    <div style={{ fontSize: "0.9em", color: "#666" }}>{task.description}</div>
                  </td>
                  <td style={{ padding: "10px" }}>
                    {new Date(task.deadline).toLocaleDateString()}
                  </td>
                  <td style={{ padding: "10px" }}>
                    <span style={{
                      backgroundColor: task.status === "completed" ? "#d4edda" : task.status === "in-progress" ? "#fff3cd" : "#f8d7da",
                      color: task.status === "completed" ? "#155724" : task.status === "in-progress" ? "#856404" : "#721c24",
                      padding: "4px 8px",
                      borderRadius: "4px",
                      fontSize: "0.9em"
                    }}>
                      {task.status.charAt(0).toUpperCase() + task.status.slice(1)}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

