import { useEffect, useState } from "react";

interface Booking {
  id: string;
  customerName: string;
  startDate: string;
  endDate: string;
  status: "active" | "completed" | "cancelled";
}

export function BookingList() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filterDate, setFilterDate] = useState("");
  const [filterStatus, setFilterStatus] = useState<"all" | "active" | "completed" | "cancelled">("all");

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      // In a real app, this would be an API call
      // const response = await fetch('/api/bookings');
      // const data = await response.json();

      // Mock data for demonstration
      const mockData: Booking[] = [
        {
          id: "1",
          customerName: "John Smith",
          startDate: "2023-06-15",
          endDate: "2023-06-17",
          status: "active"
        },
        {
          id: "2",
          customerName: "Jane Doe",
          startDate: "2023-06-10",
          endDate: "2023-06-12",
          status: "completed"
        },
        {
          id: "3",
          customerName: "Bob Johnson",
          startDate: "2023-06-05",
          endDate: "2023-06-08",
          status: "cancelled"
        }
      ];

      setBookings(mockData);
      setError(null);
    } catch (err) {
      setError("Failed to load bookings");
    } finally {
      setLoading(false);
    }
  };

  const filteredBookings = bookings.filter(booking => {
    const matchesDate = filterDate === "" || 
      booking.startDate.includes(filterDate) || 
      booking.endDate.includes(filterDate);
    const matchesStatus = filterStatus === "all" || booking.status === filterStatus;
    return matchesDate && matchesStatus;
  });

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Booking List</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="date"
          value={filterDate}
          onChange={(e) => setFilterDate(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value as any)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Statuses</option>
          <option value="active">Active</option>
          <option value="completed">Completed</option>
          <option value="cancelled">Cancelled</option>
        </select>
      </div>

      {filteredBookings.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>
          No bookings found.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredBookings.map(booking => (
            <div 
              key={booking.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: "#f9f9f9"
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px" }}>
                <strong>{booking.customerName}</strong>
                <span style={{ 
                  backgroundColor: 
                    booking.status === "active" ? "#d4edda" : 
                    booking.status === "completed" ? "#cce5ff" : 
                    "#f8d7da", 
                  color: 
                    booking.status === "active" ? "#155724" : 
                    booking.status === "completed" ? "#004085" : 
                    "#721c24", 
                  padding: "4px 8px", 
                  borderRadius: "4px" 
                }}>
                  {booking.status.charAt(0).toUpperCase() + booking.status.slice(1)}
                </span>
              </div>

              <div style={{ display: "flex", justifyContent: "space-between", fontSize: "14px" }}>
                <span>Start: {booking.startDate}</span>
                <span>End: {booking.endDate}</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

