  }

  const newId = babysitters.length > 0 ? Math.max(...babysitters.map(b => b.id)) + 1 : 1;
  const newBabysitter = {
    id: newId,
    name,
    email,
    phone,
    bio,
    availability: [],
    ratings: []
  };

  babysitters.push(newBabysitter);
  res.status(201).json(newBabysitter);
});

// Update a babysitter's profile
router.put("/babysitters/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const babysitterIndex = babysitters.findIndex(b => b.id === id);

  if (babysitterIndex === -1) {
    return res.status(404).json({ error: "Babysitter not found" });
  }

  const { name, email, phone, bio } = req.body;

  if (!name || !email || !phone || !bio) {
    return res.status(400).json({ error: "Name, email, phone, and bio are required" });
  }

  babysitters[babysitterIndex] = {
    ...babysitters[babysitterIndex],
    name,
    email,
    phone,
    bio
  };

  res.json(babysitters[babysitterIndex]);
});

// Delete a babysitter
router.delete("/babysitters/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const babysitterIndex = babysitters.findIndex(b => b.id === id);

  if (babysitterIndex === -1) {
    return res.status(404).json({ error: "Babysitter not found" });
  }

  babysitters.splice(babysitterIndex, 1);
  res.json({ message: "Babysitter deleted successfully" });
});

// Add availability for a babysitter
router.post("/babysitters/:id/availability", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const babysitter = findBabysitterById(id);

  if (!babysitter) {
    return res.status(404).json({ error: "Babysitter not found" });
  }

  const { day, startTime, endTime } = req.body;

  if (!day || !startTime || !endTime) {
    return res.status(400).json({ error: "Day, start time, and end time are required" });
  }

  babysitter.availability.push({ day, startTime, endTime });
  res.json(babysitter);
});

// Rate a babysitter
router.post("/babysitters/:id/ratings", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const babysitter = findBabysitterById(id);

  if (!babysitter) {
    return res.status(404).json({ error: "Babysitter not found" });
  }

  const { rating, comment } = req.body;

  if (typeof rating !== "number" || rating < 1 || rating > 5) {
    return res.status(400).json({ error: "Rating must be a number between 1 and 5" });
