import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock session storage - in a real app this would be a proper session store
const sessions: Record<string, { userId: string }> = {};

// Mock user database - in a real app this would be a proper database
const users = [
  { id: "1", email: "user@example.com", password: "password123" },
];

// Helper to generate a mock session ID
const generateSessionId = () => Math.random().toString(36).substring(2, 15);

/**
 * POST /login - Authenticate a user and create a session
 */
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Find user by email
  const user = users.find(u => u.email === email);

  if (!user || user.password !== password) {
    return res.status(401).json({ error: "Invalid email or password" });
  }

  // Create a session
  const sessionId = generateSessionId();
  sessions[sessionId] = { userId: user.id };

  // Set session cookie
  res.cookie("sessionId", sessionId, { httpOnly: true, secure: false });

  return res.status(200).json({ message: "Login successful" });
});

/**
 * GET /logout - End the current user session
 */
router.get("/logout", (req: Request, res: Response) => {
  const sessionId = req.cookies.sessionId;

  if (sessionId && sessions[sessionId]) {
    delete sessions[sessionId];
  }

  res.clearCookie("sessionId");
  return res.status(200).json({ message: "Logout successful" });
});

/**
 * GET /me - Get the currently authenticated user
 */
router.get("/me", (req: Request, res: Response) => {
  const sessionId = req.cookies.sessionId;

  if (!sessionId || !sessions[sessionId]) {
    return res.status(401).json({ error: "Not authenticated" });
  }

  const userId = sessions[sessionId].userId;
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.status(200).json({ id: user.id, email: user.email });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to /notes
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") || !req.path.startsWith("/notes")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT signature
  // For this example, we'll just check if it matches a known valid token format
  // In practice, you'd use a proper JWT library or manual verification

  // This is a simplified example - in reality, you'd want to properly verify
  // the JWT signature using HMAC-SHA256 with the secret
  try {
    // Mock verification - in a real implementation, you'd decode and verify the token
    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest();

    const actualSignature = Buffer.from(token.split(".")[2], "base64");

    if (actualSignature.length !== expectedSignature.length) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }

    // Use timingSafeEqual to prevent timing attacks
    if (!timingSafeEqual(expectedSignature, actualSignature)) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

