export const router = Router();

// Mock database functions - in a real app these would be imported from a database module
const mockWineExists = (id: number): boolean => {
  return id > 0 && id < 1000;
};

const mockUpdateStock = (wineId: number, adjustment: number): boolean => {
  // Simulate updating stock
  return true;
};

const mockGetWineStock = (wineId: number): number => {
  // Simulate getting current stock
  return 50;
};

// POST /wines/:id/stock-adjustment
router.post("/wines/:id/stock-adjustment", (req: Request, res: Response) => {
  const wineId = Number(req.params.id);
  const { adjustment } = req.body;

  if (isNaN(wineId) || !mockWineExists(wineId)) {
    return res.status(404).json({ error: "Wine not found" });
  }

  if (typeof adjustment !== "number") {
    return res.status(400).json({ error: "Adjustment must be a number" });
  }

  const success = mockUpdateStock(wineId, adjustment);

  if (!success) {
    return res.status(500).json({ error: "Failed to update stock" });
  }

  const newStock = mockGetWineStock(wineId);
  return res.status(200).json({
    wineId,
    adjustment,
    newStock
  });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: 1, username: "admin", password: "admin123", role: "manager" },
  { id: 2, username: "staff1", password: "staff123", role: "staff" },
];

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(
    (u) => u.username === username && u.password === password
  );

  if (!user) {
    return res
      .status(401)
      .json({ error: "Invalid username or password" });
  }

  // In a real app, we would generate a JWT token here
  return res.json({
    message: "Login successful",
    user: { id: user.id, username: user.username, role: user.role },
  });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  // In a real app, we would invalidate the JWT token or session
  return res.json({ message: "Logout successful" });
});

// Middleware to check role
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, we would decode the JWT token to get the user role
    // For now, we'll simulate it with a mock header
    const userRole = req.headers["x-user-role"] as string;

    if (!userRole || userRole !== requiredRole) {
      return res
        .status(403)
        .json({ error: "Insufficient permissions" });
    }

    next();
  };
};

