import { useEffect, useState } from "react";

interface InventoryItem {
  id: number;
  name: string;
  category: string;
  stockLevel: number;
  lowStockThreshold: number;
}

export function InventoryDashboard() {
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchInventory();
  }, []);

  const fetchInventory = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/inventory');
      if (!response.ok) {
        throw new Error('Failed to fetch inventory');
      }
      const data = await response.json();
      setInventory(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const getLowStockItems = () => {
    return inventory.filter(item => item.stockLevel <= item.lowStockThreshold);
  };

  const getOutOfStockItems = () => {
    return inventory.filter(item => item.stockLevel === 0);
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  const lowStockItems = getLowStockItems();
  const outOfStockItems = getOutOfStockItems();

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Inventory Dashboard</h1>

      <div style={{ marginBottom: '30px' }}>
        <h2>Low Stock Alerts</h2>
        {lowStockItems.length > 0 ? (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
            {lowStockItems.map(item => (
              <div key={item.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '10px', flex: '1 1 200px' }}>
                <strong>{item.name}</strong>
                <p>Current: {item.stockLevel}</p>
                <p>Threshold: {item.lowStockThreshold}</p>
              </div>
            ))}
          </div>
        ) : (
          <p>No items below threshold</p>
        )}
      </div>

      <div style={{ marginBottom: '30px' }}>
        <h2>Out of Stock Items</h2>
        {outOfStockItems.length > 0 ? (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
            {outOfStockItems.map(item => (
              <div key={item.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '10px', flex: '1 1 200px' }}>
                <strong>{item.name}</strong>
                <p>Currently out of stock</p>
              </div>
            ))}
          </div>
        ) : (
          <p>All items in stock</p>
        )}
      </div>

      <div>
        <h2>Current Stock Levels</h2>
        {inventory.length > 0 ? (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '2px solid #ccc' }}>
                <th style={{ textAlign: 'left', padding: '10px' }}>Item</th>
                <th style={{ textAlign: 'left', padding: '10px' }}>Category</th>
                <th style={{ textAlign: 'left', padding: '10px' }}>Stock Level</th>
              </tr>
            </thead>
            <tbody>
              {inventory.map(item => (
                <tr key={item.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '10px' }}>{item.name}</td>
                  <td style={{ padding: '10px' }}>{item.category}</td>
                  <td style={{ padding: '10px' }}>{item.stockLevel}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p>No inventory data available</p>
        )}
      </div>

      <div style={{ marginTop: '30px', textAlign: 'center' }}>
        <button 
          onClick={fetchInventory}
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            borderRadius: '4px', 
            padding: '10px 20px', 
            cursor: 'pointer' 
          }}
        >
          Refresh Inventory
        </button>
      </div>
    </div>
  );
}

