import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/admin", "/lab-tech"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  // Skip validation for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // For demonstration purposes, we'll check a mock role header
  // In a real implementation, this would come from a verified token
  const userRole = req.headers["x-user-role"] as string | undefined;

  // Define required roles for each path
  const roleRequirements: Record<string, string[]> = {
    "/admin": ["administrator"],
    "/lab-tech": ["lab-technician", "administrator"],
  };

  // Find the required roles for this path
  let requiredRoles: string[] = [];
  for (const [path, roles] of Object.entries(roleRequirements)) {
    if (req.path.startsWith(path)) {
      requiredRoles = roles;
      break;
    }
  }

  // If no role requirements found, allow access
  if (requiredRoles.length === 0) {
    next();
    return;
  }

  // Check if user has required role
  if (!userRole || !requiredRoles.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  // User has proper role, proceed
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password encryption for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using scrypt
  const salt = randomBytes(16).toString("hex");
  const key = scryptSync(req.body.password, salt, 32);
  const hashedPassword = key.toString("hex");

  // Replace the password with the hashed version
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const ACTIVE_SESSIONS = new Map<string, { expires: number }>();

function getSessionIdFromRequest(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }

  const token = authHeader.substring(7);
  return token;
}

function verifyTokenSignature(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const actualSignature = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(actualSignature, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const sessionId = getSessionIdFromRequest(req);

  if (!sessionId) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Verify token signature
  if (!verifyTokenSignature(sessionId)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Check if session exists and is valid
  const session = ACTIVE_SESSIONS.get(sessionId);
  if (!session || Date.now() > session.expires) {
    ACTIVE_SESSIONS.delete(sessionId);
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // Extend session timeout
  ACTIVE_SESSIONS.set(sessionId, {
    expires: Date.now() + SESSION_TIMEOUT
  });

  next();
}

