import { useEffect, useState } from "react";

interface Sample {
  id: string;
  name: string;
  description: string;
  status: string;
  createdAt: string;
  updatedAt: string;
}

interface SampleHistoryItem {
  id: string;
  sampleId: string;
  status: string;
  timestamp: string;
  notes?: string;
}

export function SampleDetailPage({ sampleId }: { sampleId: string }) {
  const [sample, setSample] = useState<Sample | null>(null);
  const [history, setHistory] = useState<SampleHistoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchSampleDetails() {
      try {
        const response = await fetch(`/api/samples/${sampleId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch sample: ${response.status}`);
        }
        const sampleData: Sample = await response.json();
        setSample(sampleData);

        const historyResponse = await fetch(`/api/samples/${sampleId}/history`);
        if (!historyResponse.ok) {
          throw new Error(`Failed to fetch history: ${historyResponse.status}`);
        }
        const historyData: SampleHistoryItem[] = await historyResponse.json();
        setHistory(historyData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchSampleDetails();
  }, [sampleId]);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!sample) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No sample found</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Sample Details</h1>

      <div style={{ backgroundColor: "#f5f5f5", borderRadius: "8px", padding: "16px", marginBottom: "20px" }}>
        <h2>{sample.name}</h2>
        <p><strong>Description:</strong> {sample.description}</p>
        <p><strong>Status:</strong> {sample.status}</p>
        <p><strong>Created:</strong> {new Date(sample.createdAt).toLocaleString()}</p>
        <p><strong>Last Updated:</strong> {new Date(sample.updatedAt).toLocaleString()}</p>
      </div>

      <h2>History</h2>
      {history.length === 0 ? (
        <p>No history available</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {history.map((item) => (
            <div key={item.id} style={{ border: "1px solid #ddd", borderRadius: "4px", padding: "12px" }}>
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <span><strong>Status:</strong> {item.status}</span>
                <span>{new Date(item.timestamp).toLocaleString()}</span>
              </div>
              {item.notes && (
                <p style={{ marginTop: "8px" }}><strong>Notes:</strong> {item.notes}</p>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

