import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: 1, username: "admin", password: "admin123", role: "staff" },
  { id: 2, username: "user1", password: "pass456", role: "regular" }
];

// User registration
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role: role || "regular"
  };

  users.push(newUser);
  return res.status(201).json(newUser);
});

// User login
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  return res.json({
    username: user.username,
    role: user.role
  });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    const token = req.headers.authorization;
    if (!token) {
      return res.status(401).json({ error: "Access denied" });
    }

    // In a real app, you'd decode the JWT here
    // For simplicity, we'll assume the token contains role info
    const user = users.find(u => u.username === token.split(" ")[1]);

    if (!user || user.role !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Staff-only route example
router.get("/staff", requireRole("staff"), (req: Request, res: Response) => {
  return res.json({ message: "Welcome, staff member!" });
});

// Regular user route example
router.get("/user", requireRole("regular"), (req: Request, res: Response) => {
  return res.json({ message: "Welcome, regular user!" });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  createBooking: (bookingData: any) => Promise.resolve({ id: 1, ...bookingData }),
  getBookingById: (id: number) => Promise.resolve({ id: 1, slotId: 1, userId: 123, date: "2023-05-15", startTime: "10:00", endTime: "11:00" }),
  updateBooking: (id: number, bookingData: any) => Promise.resolve({ id, ...bookingData }),
  deleteBooking: (id: number) => Promise.resolve(true),
  isSlotAvailable: (slotId: number, date: string, startTime: string, endTime: string) => Promise.resolve(true)
};

// Create a new booking
router.post("/bookings", async (req: Request, res: Response) => {
  try {
    const { slotId, userId, date, startTime, endTime } = req.body;

    // Validate required fields
    if (!slotId || !userId || !date || !startTime || !endTime) {
      return res.status(400).json({ error: "Missing required fields: slotId, userId, date, startTime, endTime" });
    }

    // Validate time format
    const timeRegex = /^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$/;
    if (!timeRegex.test(startTime) || !timeRegex.test(endTime)) {
      return res.status(400).json({ error: "Invalid time format. Use HH:MM" });
    }

    // Check slot availability
    const isAvailable = await mockDatabase.isSlotAvailable(slotId, date, startTime, endTime);
    if (!isAvailable) {
      return res.status(400).json({ error: "Slot is not available for the selected time" });
    }

    // Create booking
    const newBooking = await mockDatabase.createBooking(req.body);

    return res.status(201).json(newBooking);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// Get a booking by ID
router.get("/bookings/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = await mockDatabase.getBookingById(id);

    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    return res.json(booking);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// Update a booking
router.put("/bookings/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { slotId, userId, date, startTime, endTime } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    // Validate required fields
    if (!slotId || !userId || !date || !startTime || !endTime) {
      return res.status(400).json({ error: "Missing required fields: slotId, userId, date, startTime, endTime" });
    }

    // Validate time format
    const timeRegex = /^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$/;
    if (!timeRegex.test(startTime) || !timeRegex.test(endTime)) {
      return res.status(400).json({ error: "Invalid time format. Use HH:MM" });
    }

    // Check if booking exists
    const existingBooking = await mockDatabase.getBookingById(id);

    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

