import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function verifyTokenSignature(token: string): boolean {
  const [header, payload, signature] = token.split(".");

  if (!header || !payload || !signature) {
    return false;
  }

  const expectedSignature = createHmac("sha256", JWT_SECRET ?? "")
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to /bookings
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") || !req.path.startsWith("/bookings")) {
    return next();
  }

  if (!JWT_SECRET) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7);

  if (!token) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  if (!verifyTokenSignature(token)) {
    return res.status(401).json({ error: "Invalid token signature" });
  }

  try {
    const [header, payload] = token.split(".");
    const decodedPayload = Buffer.from(payload, "base64").toString();
    const { role } = JSON.parse(decodedPayload);

    if (role !== "admin" && role !== "staff") {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    // Attach role to request for downstream middleware/route handlers
    (req as any).role = role;

    return next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-POST/PUT/PATCH requests
  if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
    next();
    return;
  }

  // Skip validation for non-booking routes
  if (!req.path.startsWith('/bookings')) {
    next();
    return;
  }

  // Validate booking data
  const { groundId, name, email, phone } = req.body;

  // Validate groundId format (alphanumeric + hyphens)
  if (groundId && !/^[a-zA-Z0-9-]+$/.test(groundId)) {
    return res.status(400).json({ error: 'Invalid groundId format' });
  }

  // Validate name format (letters, spaces, hyphens, apostrophes)
  if (name && !/^[a-zA-Z\s\-'\\]+$/.test(name)) {
    return res.status(400).json({ error: 'Invalid name format' });
  }

  // Validate email format
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return res.status(400).json({ error: 'Invalid email format' });
  }

  // Validate phone format (numbers and optional + prefix)
  if (phone && !/^\+?[0-9\s\(\)-]+$/.test(phone)) {
    return res.status(400).json({ error: 'Invalid phone format' });
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

interface Session {
  userId: string;
  token: string;
  createdAt: number;
}

const activeSessions: Map<string, Session> = new Map();

function verifyTokenSignature(token: string, secret: string): boolean {
  const [header, payload, signature] = token.split(".");
  if (!header || !payload || !signature) return false;

  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");
    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "No token provided" });
  }

  const token = authHeader.substring(7);
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  if (!verifyTokenSignature(token, jwtSecret)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    return res.status(401).json({ error: "Invalid token format" });
  }

  try {
    const payload = JSON.parse(Buffer.from(parts[1], "base64url").toString());
    if (!payload.userId || !payload.exp) {
      return res.status(401).json({ error: "Invalid token payload" });
    }

    const now = Date.now();
    const expiration = payload.exp * 1000;
    if (now > expiration) {
      return res.status(401).json({ error: "Session expired" });
    }

    const existingSession = activeSessions.get(payload.userId);
    if (!existingSession) {
      return res.status(401).json({ error: "Session not found" });
    }

    if (existingSession.token !== token) {
      return res.status(401).json({ error: "Invalid token" });
    }

    // Update session timeout
    activeSessions.set(payload.userId, {
      ...existingSession,
      createdAt: now
    });

    next();
  } catch (err) {
    return res.status(401).json({ error: "Invalid token" });
  }
}

