export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockDatabase = {
  grounds: [
    { id: 1, name: "Main Field", capacity: 20, location: "Central Park" },
    { id: 2, name: "Secondary Field", capacity: 15, location: "Eastside" }
  ],

  getAllGrounds: (): Promise<any[]> => {
    return Promise.resolve(mockDatabase.grounds);
  },

  getGroundById: (id: number): Promise<any> => {
    const ground = mockDatabase.grounds.find(g => g.id === id);
    return Promise.resolve(ground);
  },

  createGround: (groundData: any): Promise<any> => {
    const newGround = {
      id: mockDatabase.grounds.length + 1,
      ...groundData
    };
    mockDatabase.grounds.push(newGround);
    return Promise.resolve(newGround);
  },

  updateGround: (id: number, groundData: any): Promise<any> => {
    const index = mockDatabase.grounds.findIndex(g => g.id === id);
    if (index !== -1) {
      mockDatabase.grounds[index] = { ...mockDatabase.grounds[index], ...groundData };
      return Promise.resolve(mockDatabase.grounds[index]);
    }
    return Promise.resolve(null);
  },

  deleteGround: (id: number): Promise<boolean> => {
    const initialLength = mockDatabase.grounds.length;
    mockDatabase.grounds = mockDatabase.grounds.filter(g => g.id !== id);
    return Promise.resolve(mockDatabase.grounds.length < initialLength);
  }
};

