// Mock invoice data storage
let invoices: any[] = [];
let nextId = 1;

// Helper function to validate invoice data
const validateInvoice = (invoice: any): string | null => {
  if (!invoice.customerName || typeof invoice.customerName !== 'string') {
    return 'Customer name is required and must be a string';
  }

  if (!invoice.invoiceNumber || typeof invoice.invoiceNumber !== 'string') {
    return 'Invoice number is required and must be a string';
  }

  if (!invoice.items || !Array.isArray(invoice.items) || invoice.items.length === 0) {
    return 'Items array is required and must not be empty';
  }

  for (const item of invoice.items) {
    if (!item.description || typeof item.description !== 'string') {
      return 'Each item must have a description';
    }

    if (typeof item.amount !== 'number' || item.amount <= 0) {
      return 'Each item must have a valid positive amount';
    }

    if (typeof item.gstRate !== 'number' || item.gstRate < 0 || item.gstRate > 100) {
      return 'Each item must have a valid GST rate between 0 and 100';
    }
  }

  return null;
};

// GET /invoices - List all invoices
router.get('/invoices', (req: Request, res: Response) => {
  res.json(invoices);
});

// GET /invoices/:id - Get a specific invoice by ID
router.get('/invoices/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid invoice ID' });
  }

  const invoice = invoices.find(inv => inv.id === id);

  if (!invoice) {
    return res.status(404).json({ error: 'Invoice not found' });
  }

  res.json(invoice);
});

// POST /invoices - Create a new invoice
router.post('/invoices', (req: Request, res: Response) => {
  const { customerName, invoiceNumber, items } = req.body;

  const validationError = validateInvoice({ customerName, invoiceNumber, items });

  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  // Calculate totals
  let subtotal = 0;
  let totalGst = 0;

  const processedItems = items.map((item: any) => {
    const itemAmount = item.amount;
    const gstAmount = (itemAmount * item.gstRate) / 100;
    subtotal += itemAmount;
    totalGst += gstAmount;

    return {
      ...item,
      gstAmount
    };
  });

  const total = subtotal + totalGst;

  const newInvoice = {
    id: nextId++,
    customerName,
    invoiceNumber,
    items: processedItems,
    subtotal,
    totalGst,
    total,
    createdAt: new Date().toISOString()
  };

  invoices.push(newInvoice);

  res.status(201).json(newInvoice);
});

// PUT /invoices/:id - Update an existing invoice
router.put('/invoices/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid invoice ID' });
  }

  const invoiceIndex = invoices.findIndex(inv => inv.id === id);

  if (invoiceIndex === -1) {
    return res.status(404).json({ error: 'Invoice not found' });
  }

  const { customerName, invoiceNumber, items } = req.body;

  const validationError = validateInvoice({ customerName, invoiceNumber, items });

  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  // Calculate totals
  let subtotal = 0;
  let totalGst = 0;

  const processedItems = items.map((item: any) => {
    const itemAmount = item.amount;
    const gstAmount = (itemAmount * item.gstRate) / 100;
    subtotal += itemAmount;
    totalGst += gstAmount;

    return {
      ...item,
      gstAmount
    };
  });

  const total = subtotal + totalGst;

  const updatedInvoice = {
    ...invoices[invoiceIndex],
    customerName,
    invoiceNumber,
    items: processedItems,
    subtotal,
    totalGst,
    total,
    updatedAt: new Date().toISOString()
  };

  invoices[invoiceIndex] = updatedInvoice;

  res.json(updatedInvoice);
});

// DELETE /invoices/:id - Delete an invoice
router.delete('/invoices/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid invoice ID' });
  }

  const invoiceIndex = invoices.findIndex(inv => inv.id === id);

  if (invoiceIndex === -1) {
    return res.status(404).json({ error: 'Invoice not found' });
  }

  invoices.splice(invoiceIndex, 1);

  res.json({ message: 'Invoice deleted successfully' });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock tax rates for different categories
const taxRates = {
  electronics: 0.18,
  clothing: 0.05,
  food: 0.02,
  books: 0.0,
  services: 0.18
};

// Mock business rules
const businessRules = {
  // Minimum taxable amount
  minTaxableAmount: 100,
  // Maximum tax rate
  maxTaxRate: 0.28
};

/**
 * Calculates GST for a product or service
 */
router.post("/calculate-gst", (req: Request, res: Response) => {
  try {
    const { category, amount } = req.body;

    // Validate input
    if (!category || typeof amount !== 'number' || amount < 0) {
      return res.status(400).json({
        error: "Invalid input: category and positive amount required"
      });
    }

    // Get tax rate for category
    const taxRate = taxRates[category as keyof typeof taxRates];

    if (taxRate === undefined) {
      return res.status(400).json({
        error: "Invalid category: unknown product/service category"
      });
    }

    // Apply business rules
    const finalTaxRate = Math.min(taxRate, businessRules.maxTaxRate);

    // Calculate GST
    const gst = amount * finalTaxRate;

    // Ensure minimum taxable amount
    const taxableAmount = Math.max(amount, businessRules.minTaxableAmount);

    // Return result
    return res.json({
      category,
      amount,
      taxRate: finalTaxRate,
      gst,
      taxableAmount
    });
  } catch (error) {
    return res.status(500).json({
      error: "Internal server error"
    });
  }
});

