import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes in milliseconds
const ACTIVE_SESSIONS = new Map<string, { expiresAt: number }>();

function getSessionIdFromRequest(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }

  const token = authHeader.substring(7);
  return token;
}

function verifyTokenSignature(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const actualSignature = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(actualSignature, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const sessionId = getSessionIdFromRequest(req);

  if (!sessionId) {
    res.status(401).json({ error: "Unauthorized: Missing session ID" });
    return;
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT secret not configured" });
    return;
  }

  if (!verifyTokenSignature(sessionId)) {
    res.status(401).json({ error: "Unauthorized: Invalid session token" });
    return;
  }

  // Check if session exists and is still valid
  const session = ACTIVE_SESSIONS.get(sessionId);
  if (!session || Date.now() > session.expiresAt) {
    ACTIVE_SESSIONS.delete(sessionId);
    res.status(401).json({ error: "Unauthorized: Session expired or invalid" });
    return;
  }

  // Extend session timeout
  session.expiresAt = Date.now() + SESSION_TIMEOUT;

  next();
}

import { useState, useEffect } from 'react';

interface InvoiceItem {
  id: string;
  description: string;
  quantity: number;
  price: number;
  gstRate: number;
}

interface CustomerDetails {
  name: string;
  address: string;
  gstNumber: string;
}

export function InvoiceForm() {
  const [customerDetails, setCustomerDetails] = useState<CustomerDetails>({
    name: '',
    address: '',
    gstNumber: '',
  });

  const [items, setItems] = useState<InvoiceItem[]>([
    {
      id: Date.now().toString(),
      description: '',
      quantity: 1,
      price: 0,
      gstRate: 0,
    },
  ]);

  const [totalAmount, setTotalAmount] = useState<number>(0);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    calculateTotal();
  }, [items]);

  const calculateTotal = () => {
    let total = 0;
    items.forEach(item => {
      const itemTotal = item.quantity * item.price;
      const gstAmount = (itemTotal * item.gstRate) / 100;
      total += itemTotal + gstAmount;
    });
    setTotalAmount(total);
  };

  const handleCustomerChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setCustomerDetails(prev => ({ ...prev, [name]: value }));
  };

  const handleItemChange = (id: string, field: keyof InvoiceItem, value: string | number) => {
    setItems(prev => 
      prev.map(item => 
        item.id === id ? { ...item, [field]: value } : item
      )
    );
  };

  const addItem = () => {
    setItems(prev => [
      ...prev,
      {
        id: Date.now().toString(),
        description: '',
        quantity: 1,
        price: 0,
        gstRate: 0,
      }
    ]);
  };

  const removeItem = (id: string) => {
    if (items.length <= 1) return;
    setItems(prev => prev.filter(item => item.id !== id));
