import { useEffect, useState } from "react";

interface Invoice {
  id: string;
  date: string;
  customer: string;
  totalAmount: number;
  status: "paid" | "pending" | "overdue";
}

export function InvoiceList() {
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchInvoices = async () => {
      try {
        const response = await fetch(`/api/invoices`);
        if (!response.ok) {
          throw new Error(`Failed to fetch invoices: ${response.status}`);
        }
        const data = await response.json();
        setInvoices(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchInvoices();
  }, []);

  const filteredInvoices = invoices.filter(invoice =>
    invoice.customer.toLowerCase().includes(searchTerm.toLowerCase()) ||
    invoice.id.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (filteredInvoices.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No invoices found.</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Invoice List</h1>
      <input
        type="text"
        placeholder="Search by customer or ID..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        style={{
          width: "100%",
          padding: "10px",
          marginBottom: "20px",
          borderRadius: "4px",
          border: "1px solid #ccc",
          boxSizing: "border-box"
        }}
      />
      <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
        {filteredInvoices.map((invoice) => (
          <div 
            key={invoice.id} 
            style={{
              border: "1px solid #ddd",
              borderRadius: "8px",
              padding: "15px",
              backgroundColor: "#f9f9f9"
            }}
          >
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px" }}>
              <span><strong>ID:</strong> {invoice.id}</span>
              <span><strong>Status:</strong> {invoice.status}</span>
            </div>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px" }}>
              <span><strong>Date:</strong> {invoice.date}</span>
              <span><strong>Customer:</strong> {invoice.customer}</span>
            </div>
            <div style={{ display: "flex", justifyContent: "space-between" }}>
              <span><strong>Total Amount:</strong> ${invoice.totalAmount.toFixed(2)}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

