export const router = Router();

// Mock database functions - in a real app these would be actual database calls
const mockDatabase = {
  createPatient: (patientData: any) => Promise.resolve({ id: 1, ...patientData }),
  getPatientById: (id: number) => Promise.resolve({ id: 1, name: "John Doe", age: 30 }),
  updatePatient: (id: number, patientData: any) => Promise.resolve({ id, ...patientData }),
  deletePatient: (id: number) => Promise.resolve(true)
};

// Create a new patient
router.post("/patients", async (req: Request, res: Response) => {
  try {
    const { name, age, email } = req.body;

    // Basic validation
    if (!name || !age || !email) {
      return res.status(400).json({ error: "Name, age, and email are required" });
    }

    const newPatient = await mockDatabase.createPatient({ name, age, email });
    return res.status(201).json(newPatient);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// Get all patients
router.get("/patients", async (req: Request, res: Response) => {
  try {
    // In a real implementation, this would fetch from a database
    return res.json([{
      id: 1,
      name: "John Doe",
      age: 30,
      email: "john@example.com"
    }]);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// Get a specific patient by ID
router.get("/patients/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid patient ID" });
    }

    const patient = await mockDatabase.getPatientById(id);

    if (!patient) {
      return res.status(404).json({ error: "Patient not found" });
    }

    return res.json(patient);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// Update a patient
router.put("/patients/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { name, age, email } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid patient ID" });
    }

    if (!name || !age || !email) {
      return res.status(400).json({ error: "Name, age, and email are required" });
    }

    const updatedPatient = await mockDatabase.updatePatient(id, { name, age, email });

    if (!updatedPatient) {
      return res.status(404).json({ error: "Patient not found" });
    }

    return res.json(updatedPatient);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// Delete a patient
router.delete("/patients/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid patient ID" });
    }

    const deleted = await mockDatabase.deletePatient(id);

    if (!deleted) {
      return res.status(404).json({ error: "Patient not found" });
    }

    return res.json({ message: "Patient deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

