  { id: 2, username: "nurse_johnson", password: "nursepass", role: "nurse" },
  { id: 3, username: "admin_user", password: "adminpass", role: "admin" }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate a mock session ID
  const sessionId = `session_${Date.now()}`;
  sessions.set(sessionId, { userId: user.id, role: user.role });

  return res.status(200).json({
    sessionId,
    user: { id: user.id, username: user.username, role: user.role }
  });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const { sessionId } = req.body;

  if (!sessionId) {
    return res.status(400).json({ error: "Session ID is required" });
  }

  if (!sessions.has(sessionId)) {
    return res.status(401).json({ error: "Invalid session" });
  }

  sessions.delete(sessionId);
  return res.status(200).json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: () => void) => {
  const { sessionId } = req.headers;

  if (!sessionId || typeof sessionId !== "string") {
    return res.status(401).json({ error: "Unauthorized: Session required" });
  }

  const session = sessions.get(sessionId);

  if (!session) {
    return res.status(401).json({ error: "Unauthorized: Invalid session" });
  }

  (req as any).user = session;
  next();
};

// Get current user info
router.get("/me", authenticate, (req: Request, res: Response) => {
  const user = (req as any).user;
  return res.status(200).json({
    id: user.userId,
    username: users.find(u => u.id === user.userId)?.username,
    role: user.role
  });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: () => void) => {
    const user = (req as any).user;

    if (!user || user.role !== requiredRole) {
      return res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    }

    next();
  };
};

// Admin-only endpoint example
router.get("/admin", authenticate, requireRole("admin"), (req: Request, res: Response) => {
  return res.status(200).json({ message: "Admin access granted" });
});

