import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Define role types
export type UserRole = "admin" | "nurse" | "doctor";

// Define the structure of a decoded token
interface DecodedToken {
  userId: string;
  role: UserRole;
}

// Middleware function for role-based access control
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/patients", "/appointments", "/medical-records"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  // Skip validation for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user is authenticated
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ message: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Validate token signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ message: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Simple token verification (in a real app, use a proper JWT library)
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ message: "Unauthorized: Invalid token format" });
      return;
    }

    // Decode payload (simplified for this example)
    const decodedPayload = Buffer.from(payload, "base64").toString("utf-8");
    const decoded: DecodedToken = JSON.parse(decodedPayload);

    // Verify signature
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64");

    const signatureBuffer = Buffer.from(signature, "base64");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ message: "Unauthorized: Invalid token signature" });
      return;
    }

    // Check role permissions
    const userRole: UserRole = decoded.role;
    const requiredRoles: Record<string, UserRole[]> = {
      "/patients": ["admin", "nurse", "doctor"],
      "/appointments": ["admin", "nurse", "doctor"],
      "/medical-records": ["admin", "doctor"]
    };

    const path = req.path;
    let allowedRoles: UserRole[] = [];

    // Determine required roles based on path
    for (const [route, roles] of Object.entries(requiredRoles)) {
      if (path.startsWith(route)) {
        allowedRoles = roles;
        break;
      }
    }

    // If no specific rules found, allow all roles
    if (allowedRoles.length === 0) {
      allowedRoles = ["admin", "nurse", "doctor"];
    }

    // Check if user has required role
    if (!allowedRoles.includes(userRole)) {
      res.status(403).json({ message: "Forbidden: Insufficient permissions" });
      return;
    }

    // If we reach here, user has proper permissions
    next();
  } catch (error) {
    res.status(401).json({ message: "Unauthorized: Invalid token" });
  }
}

