];

const findVisitById = (id: number) => {
  return mockVisits.find(visit => visit.id === id);
};

const createVisit = (visitData: Omit<Visit, 'id'>) => {
  const newVisit = {
    id: mockVisits.length > 0 ? Math.max(...mockVisits.map(v => v.id)) + 1 : 1,
    ...visitData
  };
  mockVisits.push(newVisit);
  return newVisit;
};

const updateVisit = (id: number, updateData: Partial<Visit>) => {
  const index = mockVisits.findIndex(visit => visit.id === id);
  if (index === -1) return null;

  mockVisits[index] = { ...mockVisits[index], ...updateData };
  return mockVisits[index];
};

const deleteVisit = (id: number) => {
  const index = mockVisits.findIndex(visit => visit.id === id);
  if (index === -1) return false;

  mockVisits.splice(index, 1);
  return true;
};

