import { useEffect, useState } from "react";

interface Visit {
  id: number;
  customerId: number;
  customerName: string;
  date: string;
  status: "planned" | "completed" | "cancelled";
  notes: string;
}

export function VisitList() {
  const [visits, setVisits] = useState<Visit[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");
  const [customerFilter, setCustomerFilter] = useState("");
  const [statusFilter, setStatusFilter] = useState("");

  useEffect(() => {
    fetchVisits();
  }, []);

  const fetchVisits = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/visits`);
      if (!response.ok) {
        throw new Error(`Failed to fetch visits: ${response.status}`);
      }
      const data = await response.json();
      setVisits(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const filteredVisits = visits.filter(visit => {
    const matchesDate = (
      (!dateFrom || visit.date >= dateFrom) &&
      (!dateTo || visit.date <= dateTo)
    );

    const matchesCustomer = 
      customerFilter === "" || 
      visit.customerName.toLowerCase().includes(customerFilter.toLowerCase());

    const matchesStatus = 
      statusFilter === "" || 
      visit.status === statusFilter;

    return matchesDate && matchesCustomer && matchesStatus;
  });

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Visit List</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Customer Name"
          value={customerFilter}
          onChange={(e) => setCustomerFilter(e.target.value)}
          style={{ width: "100%", padding: "8px" }}
        />

        <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
          <input
            type="date"
            value={dateFrom}
            onChange={(e) => setDateFrom(e.target.value)}
            style={{ flex: "1", minWidth: "120px", padding: "8px" }}
          />
          <input
            type="date"
            value={dateTo}
            onChange={(e) => setDateTo(e.target.value)}
            style={{ flex: "1", minWidth: "120px", padding: "8px" }}
          />

          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            style={{ flex: "1", minWidth: "120px", padding: "8px" }}
          >
            <option value="">All Statuses</option>
            <option value="planned">Planned</option>
            <option value="completed">Completed</option>
            <option value="cancelled">Cancelled</option>
          </select>
        </div>
      </div>

      {filteredVisits.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>
          No visits found.
        </div>
      ) : (
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", marginBottom: "20px" }}>
            <thead>
              <tr style={{ backgroundColor: "#f5f5f5" }}>
                <th style={{ border: "1px solid #ddd", padding: "12px", textAlign: "left" }}>Customer</th>
                <th style={{ border: "1px solid #ddd", padding: "12px", textAlign: "left" }}>Date</th>
                <th style={{ border: "1px solid #ddd", padding: "12px", textAlign: "left" }}>Status</th>
                <th style={{ border: "1px solid #ddd", padding: "12px", textAlign: "left" }}>Notes</th>
              </tr>
            </thead>
            <tbody>
              {filteredVisits.map((visit) => (
                <tr key={visit.id} style={{ borderBottom: "1px solid #ddd" }}>
                  <td style={{ border: "1px solid #ddd", padding: "12px" }}>{visit.customerName}</td>
                  <td style={{ border: "1px solid #ddd", padding: "12px" }}>{visit.date}</td>
                  <td style={{ border: "1px solid #ddd", padding: "12px" }}>{visit.status}</td>
                  <td style={{ border: "1px solid #ddd", padding: "12px" }}>{visit.notes}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

