import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const TOKEN_HEADER = "x-auth-token";

interface SessionData {
  userId: string;
  expiresAt: number;
}

function verifyToken(token: string): SessionData | null {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return null;
  }

  try {
    const [signature, payload] = token.split(".");
    if (!signature || !payload) {
      return null;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("hex");

    const signatureBuffer = Buffer.from(signature, "hex");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "hex");

    if (signatureBuffer.length !== expectedSignatureBuffer.length) {
      return null;
    }

    const isValid = timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
    if (!isValid) {
      return null;
    }

    const decodedPayload = Buffer.from(payload, "base64").toString("utf-8");
    const parsedPayload = JSON.parse(decodedPayload);

    return {
      userId: parsedPayload.userId,
      expiresAt: parsedPayload.expiresAt
    };
  } catch (err) {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests with auth token
  if (req.method !== "POST" || !req.header(TOKEN_HEADER)) {
    return next();
  }

  const token = req.header(TOKEN_HEADER);
  if (!token) {
    return res.status(401).json({ error: "Missing token" });
  }

  const sessionData = verifyToken(token);
  if (!sessionData) {
    return res.status(401).json({ error: "Invalid token" });
  }

  if (Date.now() > sessionData.expiresAt) {
    return res.status(401).json({ error: "Session expired" });
  }

  // Session is valid, proceed
  next();
}

