import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [] as Array<{ id: number; username: string; password: string }>;
let nextId = 1;

// Mock session storage
const sessions = new Map<string, { userId: number; username: string }>();

// User registration
router.post("/register", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: nextId++,
    username,
    password
  };

  users.push(newUser);

  return res.status(201).json({ id: newUser.id, username: newUser.username });
});

// User login
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = Math.random().toString(36).substring(2, 15);
  sessions.set(token, { userId: user.id, username: user.username });

  return res.json({ token, username: user.username });
});

// User logout
router.post("/logout", (req: Request, res: Response) => {
  const token = req.header("Authorization")?.replace("Bearer ", "");

  if (!token) {
    return res.status(400).json({ error: "No token provided" });
  }

  if (!sessions.has(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  sessions.delete(token);

  return res.json({ message: "Logged out successfully" });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "JWT secret not configured" });
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7);
  const expectedSignature = createHmac("sha256", secret)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest();

  const actualSignature = Buffer.from(token.split(".")[2], "base64");

  try {
    const isEqual = timingSafeEqual(expectedSignature, actualSignature);
    if (!isEqual) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using scrypt
  const salt = randomBytes(16).toString("hex");
  const key = scryptSync(req.body.password, salt, 32);
  const hashedPassword = key.toString("hex");

  // Replace the password with the hashed version
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

