import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to admin routes
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") || !req.path.startsWith("/admin")) {
    return next();
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const token = authHeader.substring(7);

  if (!process.env.JWT_SECRET) {
    return res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
  }

  const secret = Buffer.from(process.env.JWT_SECRET, "utf-8");

  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      return res.status(401).json({ error: "Unauthorized: Invalid token format" });
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    }

    // Decode payload (simplified for example)
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString("utf-8"));

    if (!decodedPayload.role || decodedPayload.role !== "admin") {
      return res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    }

    // If we get here, the user is authenticated and authorized
    next();
  } catch (err) {
    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

