import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

interface SessionData {
  userId: string;
  sessionId: string;
  createdAt: number;
}

function isValidToken(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

function getSessionFromToken(token: string): SessionData | null {
  try {
    const [, payload] = token.split(".");
    if (!payload) return null;
    const decodedPayload = Buffer.from(payload, "base64url").toString();
    return JSON.parse(decodedPayload);
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests with a body containing a token
  if (req.method !== "POST" || !req.body || !req.body.token) {
    return next();
  }

  const token = req.body.token;

  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  if (!isValidToken(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  const sessionData = getSessionFromToken(token);

  if (!sessionData) {
    return res.status(401).json({ error: "Invalid token format" });
  }

  const now = Date.now();
  if (now - sessionData.createdAt > SESSION_TIMEOUT) {
    return res.status(401).json({ error: "Session expired or invalid" });
  }

  // If we get here, the session is valid
  next();
}

