import { useState } from "react";

export function RoomAllocationForm() {
  const [formData, setFormData] = useState({
    fullName: "",
    studentId: "",
    email: "",
    phone: "",
    preferredRoomType: "",
    roommatePreference: "",
    documentation: null as File | null,
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });

    // Clear error when user starts typing
    if (errors[name]) {
      setErrors({
        ...errors,
        [name]: "",
      });
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFormData({
        ...formData,
        documentation: e.target.files[0],
      });
    }
  };

  const validate = () => {
    const newErrors: Record<string, string> = {};

    if (!formData.fullName.trim()) {
      newErrors.fullName = "Full name is required";
    }

    if (!formData.studentId.trim()) {
      newErrors.studentId = "Student ID is required";
    }

    if (!formData.email.trim()) {
      newErrors.email = "Email is required";
    } else if (!/^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/.test(formData.email)) {
      newErrors.email = "Invalid email format";
    }

    if (!formData.phone.trim()) {
      newErrors.phone = "Phone number is required";
    } else if (!/^\+?[1-9]\d{1,14}$/.test(formData.phone.replace(/[-\s()]/g, ""))) {
      newErrors.phone = "Invalid phone number";
    }

    if (!formData.preferredRoomType) {
      newErrors.preferredRoomType = "Room type preference is required";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) {
      return;
    }

    setIsSubmitting(true);

    try {
      // In a real app, this would be an API call
      // await fetch('/api/room-allocation', { method: 'POST', body: formData });

      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));

      setSubmitSuccess(true);

      // Reset form after successful submission
      setFormData({
        fullName: "",
        studentId: "",
        email: "",
        phone: "",
        preferredRoomType: "",
        roommatePreference: "",
        documentation: null,
      });
    } catch (error) {
      console.error("Submission error:", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div style={{
      maxWidth: "600px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    }}>
      <h1 style={{ textAlign: "center", marginBottom: "30px" }}>Hostel Room Allocation Form</h1>

      {submitSuccess ? (
        <div style={{
          backgroundColor: "#d4edda",
          color: "#155724",
          padding: "15px",
          borderRadius: "5px",
          textAlign: "center",
          marginBottom: "20px",
        }}>
          Your application has been submitted successfully!
        </div>
      ) : null}

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div>
          <label htmlFor="fullName" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>
            Full Name *
          </label>
          <input
            type="text"
            id="fullName"
            name="fullName"
            value={formData.fullName}
            onChange={handleChange}
            style={{
              width: "100%",
              padding: "10px",
              border: errors.fullName ? "1px solid #dc3545" : "1px solid #ccc",
              borderRadius: "4px",
            }}
          />
          {errors.fullName && (
            <span style={{ color: "#dc3545", fontSize: "14px" }}>{errors.fullName}</span>
          )}
        </div>

        <div>
          <label htmlFor="studentId" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>
            Student ID *
          </label>
          <input
            type="text"
            id="studentId"
            name="studentId"
            value={formData.studentId}
            onChange={handleChange}
            style={{
              width: "100%",
              padding: "10px",
              border: errors.studentId ? "1px solid #dc3545" : "1px solid #ccc",
              borderRadius: "4px",
            }}
          />
          {errors.studentId && (
            <span style={{ color: "#dc3545", fontSize: "14px" }}>{errors.studentId}</span>
          )}
        </div>

        <div>
          <label htmlFor="email" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>
            Email Address *
          </label>
          <input
            type="email"
            id="email"
            name="email"
            value={formData.email}
            onChange={handleChange}
            style={{
              width: "100%",
              padding: "10px",
              border: errors.email ? "1px solid #dc3545" : "1px solid #ccc",
              borderRadius: "4px",
            }}
          />
          {errors.email && (
            <span style={{ color: "#dc3545", fontSize: "14px" }}>{errors.email}</span>
          )}
        </div>

        <div>
          <label htmlFor="phone" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>
            Phone Number *
          </label>
          <input
            type="tel"
            id="phone"
            name="phone"
            value={formData.phone}
            onChange={handleChange}
            style={{
              width: "100%",
              padding: "10px",
              border: errors.phone ? "1px solid #dc3545" : "1px solid #ccc",
              borderRadius: "4px",
            }}
          />
          {errors.phone && (
            <span style={{ color: "#dc3545", fontSize: "14px" }}>{errors.phone}</span>
          )}
        </div>

        <div>
          <label htmlFor="preferredRoomType" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>
            Preferred Room Type *
          </label>
          <select
            id="preferredRoomType"
            name="preferredRoomType"
            value={formData.preferredRoomType}
            onChange={handleChange}
            style={{
              width: "100%",
              padding: "10px",
              border: errors.preferredRoomType ? "1px solid #dc3545" : "1px solid #ccc",
              borderRadius: "4px",
            }}
          >
            <option value="">Select room type</option>
            <option value="single">Single Room</option>
            <option value="double">Double Room</option>
            <option value="triple">Triple Room</option>
            <option value="quad">Quad Room</option>
          </select>
          {errors.preferredRoomType && (
            <span style={{ color: "#dc3545", fontSize: "14px" }}>{errors.preferredRoomType}</span>
          )}
        </div>

        <div>
          <label htmlFor="roommatePreference" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>
            Roommate Preference
          </label>
          <input
            type="text"
            id="roommatePreference"
            name="roommatePreference"
            value={formData.roommatePreference}
            onChange={handleChange}
            placeholder="Enter roommate preferences (optional)"
            style={{
              width: "100%",
              padding: "10px",
              border: "1px solid #ccc",
              borderRadius: "4px",
            }}
          />
        </div>

        <div>
          <label htmlFor="documentation" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>
            Documentation (Optional)
          </label>
          <input
            type="file"
            id="documentation"
            name="documentation"
            onChange={handleFileChange}
            accept=".pdf,.doc,.docx"
            style={{ width: "100%" }}
          />
          <small style={{ color: "#666" }}>
            Upload PDF, DOC, or DOCX files (max 5MB)
          </small>
        </div>

        <button
          type="submit"
          disabled={isSubmitting}
          style={{
            backgroundColor: "#007bff",
            color: "white",
            padding: "12px 20px",
            border: "none",
            borderRadius: "4px",
            cursor: isSubmitting ? "not-allowed" : "pointer",
            fontSize: "16px",
            fontWeight: "bold",
            marginTop: "10px",
          }}
        >
          {isSubmitting ? "Submitting..." : "Submit Application"}
        </button>
      </form>
    </div>
  );
}

