  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [capacityFilter, setCapacityFilter] = useState<number | "">("");
  const [amenityFilter, setAmenityFilter] = useState<string>("");
  const [locationFilter, setLocationFilter] = useState<string>("");

  useEffect(() => {
    const fetchRooms = async () => {
      try {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mock data
        const mockRooms: Room[] = [
          { id: 1, capacity: 2, amenities: ["WiFi", "AC"], location: "Block A" },
          { id: 2, capacity: 4, amenities: ["WiFi", "AC", "TV"], location: "Block B" },
          { id: 3, capacity: 6, amenities: ["WiFi"], location: "Block C" },
          { id: 4, capacity: 2, amenities: ["WiFi", "AC", "TV"], location: "Block A" },
          { id: 5, capacity: 8, amenities: ["WiFi", "AC", "TV", "Laundry"], location: "Block D" },
        ];

        setRooms(mockRooms);
        setFilteredRooms(mockRooms);
      } catch (err) {
        setError("Failed to load rooms");
      } finally {
        setLoading(false);
      }
    };

    fetchRooms();
  }, []);

  useEffect(() => {
    let result = rooms;

    if (capacityFilter !== "") {
      result = result.filter(room => room.capacity >= Number(capacityFilter));
    }

    if (amenityFilter) {
      result = result.filter(room => room.amenities.includes(amenityFilter));
    }

    if (locationFilter) {
      result = result.filter(room => room.location === locationFilter);
    }

    setFilteredRooms(result);
  }, [capacityFilter, amenityFilter, locationFilter, rooms]);

  const uniqueAmenities = Array.from(new Set(rooms.flatMap(room => room.amenities)));
  const uniqueLocations = Array.from(new Set(rooms.map(room => room.location)));

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
