      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
          <div style={{ flex: "1", minWidth: "200px" }}>
            <label htmlFor="capacity-filter" style={{ display: "block", marginBottom: "5px" }}>Capacity:</label>
            <select
              id="capacity-filter"
              value={capacityFilter}
              onChange={(e) => setCapacityFilter(e.target.value === "" ? "" : Number(e.target.value))}
              style={{ width: "100%", padding: "8px" }}
            >
              <option value="">All</option>
              <option value="2">2+</option>
              <option value="4">4+</option>
              <option value="6">6+</option>
              <option value="8">8+</option>
            </select>
          </div>

          <div style={{ flex: "1", minWidth: "200px" }}>
            <label htmlFor="amenity-filter" style={{ display: "block", marginBottom: "5px" }}>Amenity:</label>
            <select
              id="amenity-filter"
              value={amenityFilter}
              onChange={(e) => setAmenityFilter(e.target.value)}
              style={{ width: "100%", padding: "8px" }}
            >
              <option value="">All</option>
              {uniqueAmenities.map(amenity => (
                <option key={amenity} value={amenity}>{amenity}</option>
              ))}
            </select>
          </div>

          <div style={{ flex: "1", minWidth: "200px" }}>
            <label htmlFor="location-filter" style={{ display: "block", marginBottom: "5px" }}>Location:</label>
            <select
              id="location-filter"
              value={locationFilter}
              onChange={(e) => setLocationFilter(e.target.value)}
              style={{ width: "100%", padding: "8px" }}
            >
              <option value="">All</option>
              {uniqueLocations.map(location => (
                <option key={location} value={location}>{location}</option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {filteredRooms.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>No rooms found matching your criteria.</div>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))", gap: "20px" }}>
