import type { Request, Response, NextFunction } from "express";
import { createHash, scrypt, randomBytes, timingSafeEqual } from "node:crypto";

// This middleware handles password hashing for user registration
// It only processes POST requests to /register endpoint
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to the register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  const password = req.body.password;

  // Generate salt
  const salt = randomBytes(16).toString("hex");

  // Hash password with salt
  scrypt(password, salt, 64, (err, derivedKey) => {
    if (err) {
      next(err);
      return;
    }

    // Store hashed password with salt
    req.body.hashedPassword = derivedKey.toString("hex");
    req.body.salt = salt;

    next();
  });
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to subscription routes
  const isSubscriptionRoute = req.path.startsWith('/subscriptions');
  const isProtectedMethod = req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE';

  if (!isSubscriptionRoute || !isProtectedMethod) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  // Simple verification - in a real app, use a proper JWT library
  const [header, payload, signature] = token.split('.');
  if (!header || !payload || !signature) {
    res.status(401).json({ error: 'Invalid token format' });
    return;
  }

  try {
    // Decode base64url
    const decodedPayload = Buffer.from(payload, 'base64').toString('utf-8');
    const parsedPayload = JSON.parse(decodedPayload);

    // Check if token is expired
    if (parsedPayload.exp && Date.now() >= parsedPayload.exp * 1000) {
      res.status(401).json({ error: 'Token has expired' });
      return;
    }

    // Verify signature
    const expectedSignature = createHmac('sha256', secret)
      .update(`${header}.${payload}`)
      .digest('base64url');

    const expectedBuffer = Buffer.from(expectedSignature, 'base64url');
    const actualBuffer = Buffer.from(signature, 'base64url');

    if (expectedBuffer.length !== actualBuffer.length || 
        !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: 'Invalid token signature' });
      return;
    }

    // Token is valid, proceed
    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

