export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to /boards and /tasks routes
  const isProtectedRoute = (req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE') &&
    (req.path.startsWith('/boards') || req.path.startsWith('/tasks'));

  if (!isProtectedRoute) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT signature
  // For this implementation, we'll just check if it matches a basic format
  const expectedSignature = createHmac('sha256', secret)
    .update(token)
    .digest('hex');

