// Define role types and their numeric values
const roles = {
  member: 1,
  manager: 2,
  admin: 3,
};

// Type definition for user role
export type UserRole = keyof typeof roles;

// Helper to verify JWT signature
function verifyTokenSignature(token: string, secret: string): boolean {
  const [header, payload, signature] = token.split(".");
  if (!header || !payload || !signature) return false;

  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");
    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

// Middleware function
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE")) {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // Extract token from Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Verify token signature
  if (!verifyTokenSignature(token, jwtSecret)) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Decode token (simplified for example)
  const payload = token.split(".")[1];
  if (!payload) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const decodedPayload = Buffer.from(payload, "base64").toString();
  let userData;
  try {
    userData = JSON.parse(decodedPayload);
  } catch {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const userRole: UserRole = userData.role;
  if (!userRole || !(userRole in roles)) {
    res.status(401).json({ error: "Unauthorized" });
