  { id: 2, name: "Jane Smith", email: "jane@example.com", skills: ["cleaning", "gardening"], availability: "weekdays" }
];

const findVolunteerById = (id: number) => {
  return mockVolunteers.find(volunteer => volunteer.id === id);
};

const createVolunteer = (volunteerData: any) => {
  const newId = Math.max(...mockVolunteers.map(v => v.id)) + 1;
  const newVolunteer = { ...volunteerData, id: newId };
  mockVolunteers.push(newVolunteer);
  return newVolunteer;
};

const updateVolunteer = (id: number, updatedData: any) => {
  const index = mockVolunteers.findIndex(volunteer => volunteer.id === id);
  if (index !== -1) {
    mockVolunteers[index] = { ...mockVolunteers[index], ...updatedData };
    return mockVolunteers[index];
  }
  return null;
};

const deleteVolunteer = (id: number) => {
  const index = mockVolunteers.findIndex(volunteer => volunteer.id === id);
  if (index !== -1) {
    mockVolunteers.splice(index, 1);
    return true;
  }
  return false;
};

