        { id: 3, name: "Carol Davis", skills: ["teaching", "coding"], availability: "pending" },
        { id: 4, name: "David Wilson", skills: ["cooking", "cleaning"], availability: "available" },
      ];

      setVolunteers(mockData);
      setFilteredVolunteers(mockData);
    } catch (err) {
      setError("Failed to load volunteers");
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    const term = e.target.value.toLowerCase();
    setSearchTerm(term);

    if (!term) {
      setFilteredVolunteers(volunteers);
      return;
    }

    const filtered = volunteers.filter(volunteer => 
      volunteer.name.toLowerCase().includes(term) ||
      volunteer.skills.some(skill => skill.toLowerCase().includes(term)) ||
      volunteer.availability.toLowerCase().includes(term)
    );

    setFilteredVolunteers(filtered);
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Volunteer List</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search by name, skill, or availability..."
          value={searchTerm}
          onChange={handleSearch}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
      </div>

      {filteredVolunteers.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>
          No volunteers found.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredVolunteers.map(volunteer => (
            <div 
              key={volunteer.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: "#f9f9f9"
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                <div>
                  <h3 style={{ margin: "0 0 5px 0" }}>{volunteer.name}</h3>
                  <p style={{ margin: "0 0 5px 0" }}>
                    <strong>Skills:</strong> {volunteer.skills.join(", ")}
                  </p>
                  <p style={{ margin: "0 0 5px 0" }}>
                    <strong>Status:</strong> {volunteer.availability}
                  </p>
                </div>
                <span 
                  style={{ 
                    padding: "4px 8px", 
                    borderRadius: "4px", 
                    backgroundColor: 
                      volunteer.availability === "available" ? "#d4edda" : 
                      volunteer.availability === "unavailable" ? "#f8d7da" : 
                      "#fff3cd",
                    color: 
                      volunteer.availability === "available" ? "#155724" : 
                      volunteer.availability === "unavailable" ? "#721c24" : 
                      "#856404"
                  }}
                >
                  {volunteer.availability.charAt(0).toUpperCase() + volunteer.availability.slice(1)}
                </span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Event {
  id: number;
  title: string;
  date: string;
  time: string;
  location: string;
}

interface VolunteerAssignment {
  id: number;
  eventId: number;
  volunteerName: string;
}

export function EventManagementPage() {
  const [events, setEvents] = useState<Event[]>([]);
  const [assignments, setAssignments] = useState<VolunteerAssignment[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form state
  const [newEvent, setNewEvent] = useState({
    title: "",
    date: "",
    time: "",
    location: ""
  });

  const [newAssignment, setNewAssignment] = useState({
    eventId: "",
    volunteerName: ""
  });

  useEffect(() => {
    fetchEvents();
    fetchAssignments();
  }, []);

  const fetchEvents = async () => {
    try {
      const response = await fetch("/api/events");
      if (!response.ok) throw new Error("Failed to fetch events");
      const data = await response.json();
      setEvents(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const fetchAssignments = async () => {
    try {
      const response = await fetch("/api/assignments");
      if (!response.ok) throw new Error("Failed to fetch assignments");
      const data = await response.json();
      setAssignments(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleCreateEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/events", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newEvent)
      });
      if (!response.ok) throw new Error("Failed to create event");
      await fetchEvents();
      setNewEvent({ title: "", date: "", time: "", location: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleAssignVolunteer = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/assignments", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          eventId: Number(newAssignment.eventId),
          volunteerName: newAssignment.volunteerName
        })
      });
      if (!response.ok) throw new Error("Failed to assign volunteer");
      await fetchAssignments();
      setNewAssignment({ eventId: "", volunteerName: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Event Management</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Create New Event</h2>
        <form onSubmit={handleCreateEvent} style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          <input
            type="text"
            placeholder="Event Title"
            value={newEvent.title}
            onChange={(e) => setNewEvent({...newEvent, title: e.target.value})}
            style={{ width: "100%", padding: "8px" }}
          />
          <input
            type="date"
            value={newEvent.date}
            onChange={(e) => setNewEvent({...newEvent, date: e.target.value})}
            style={{ width: "100%", padding: "8px" }}
          />
          <input
            type="time"
            value={newEvent.time}
            onChange={(e) => setNewEvent({...newEvent, time: e.target.value})}
            style={{ width: "100%", padding: "8px" }}
          />
          <input
            type="text"
            placeholder="Location"
            value={newEvent.location}
            onChange={(e) => setNewEvent({...newEvent, location: e.target.value})}
            style={{ width: "100%", padding: "8px" }}
          />
          <button type="submit" style={{ padding: "10px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px" }}>
            Create Event
          </button>
        </form>
      </div>

      <div style={{ marginBottom: "30px" }}>
        <h2>Assign Volunteer</h2>
        <form onSubmit={handleAssignVolunteer} style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          <select
            value={newAssignment.eventId}
            onChange={(e) => setNewAssignment({...newAssignment, eventId: e.target.value})}
            style={{ width: "100%", padding: "8px" }}
          >
            <option value="">Select Event</option>
            {events.map(event => (
              <option key={event.id} value={event.id}>{event.title}</option>
            ))}
          </select>
          <input
            type="text"
            placeholder="Volunteer Name"
            value={newAssignment.volunteerName}
            onChange={(e) => setNewAssignment({...newAssignment, volunteerName: e.target.value})}
            style={{ width: "100%", padding: "8px" }}
          />
          <button type="submit" style={{ padding: "10px", backgroundColor: "#28a745", color: "white", border: "none", borderRadius: "4px" }}>
            Assign Volunteer
          </button>
        </form>
      </div>

      <div>
        <h2>Upcoming Events</h2>
        {events.length === 0 ? (
          <p style={{ textAlign: "center", fontStyle: "italic" }}>No events scheduled yet.</p>
        ) : (
          <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
            {events.map(event => (
              <div key={event.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", width: "250px" }}>
                <h3>{event.title}</h3>
                <p><strong>Date:</strong> {event.date}</p>
                <p><strong>Time:</strong> {event.time}</p>
                <p><strong>Location:</strong> {event.location}</p>
                <h4>Volunteers Assigned</h4>
                <ul>
                  {assignments
                    .filter(a => a.eventId === event.id)
                    .map(assignment => (
                      <li key={assignment.id}>{assignment.volunteerName}</li>
                    ))}
                </ul>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

