        </ul>
      </div>

      <div style={{ marginBottom: "20px", padding: "15px", borderRadius: "8px", border: "1px solid #ddd" }}>
        <h2>Event History</h2>
        {volunteer.events.length === 0 ? (
          <p>No events recorded</p>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
