import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: 1, email: "customer@example.com", password: "password123", role: "customer" },
  { id: 2, email: "staff@example.com", password: "staffpass", role: "staff" }
];

// User registration
router.post("/register", (req: Request, res: Response) => {
  const { email, password, role } = req.body;

  if (!email || !password || !role) {
    return res.status(400).json({ error: "Email, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.email === email);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    email,
    password,
    role
  };

  users.push(newUser);
  return res.status(201).json(newUser);
});

// User login
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Find user
  const user = users.find(u => u.email === email && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Return user info (in a real app, this would include a JWT token)
  return res.json({
    email: user.email,
    role: user.role
  });
});

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real implementation, this would check the JWT token
    // For now, we'll simulate with a mock user
    const user = users[0]; // Mock current user
    if (!user || !roles.includes(user.role)) {
      return res.status(403).json({ error: "Access denied" });
    }
    next();
  };
};

// Protected route for customers
router.get("/customer/dashboard", authorize(["customer"]), (req: Request, res: Response) => {
  return res.json({ message: "Customer dashboard accessed successfully" });
});

// Protected route for staff
router.get("/staff/dashboard", authorize(["staff"]), (req: Request, res: Response) => {
  return res.json({ message: "Staff dashboard accessed successfully" });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockCreateBooking = (bookingData: any) => {
  return {
    id: Math.floor(Math.random() * 1000),
    ...bookingData,
    status: 'confirmed'
  };
};

const mockGetBookingById = (id: number) => {
  return id > 0 ? { id, service: 'cleaning', date: '2023-05-15', status: 'confirmed' } : null;
};

const mockUpdateBooking = (id: number, updateData: any) => {
  return id > 0 ? { id, ...updateData, status: 'updated' } : null;
};

const mockCancelBooking = (id: number) => {
  return id > 0 ? { id, status: 'cancelled' } : null;
};

// Create a new booking
router.post('/', (req: Request, res: Response) => {
  const { service, date } = req.body;

  if (!service || !date) {
    return res.status(400).json({ error: 'Service and date are required' });
  }

  const newBooking = mockCreateBooking({ service, date });
  return res.status(201).json(newBooking);
});

// Get a booking by ID
router.get('/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid booking ID' });
  }

  const booking = mockGetBookingById(id);

  if (!booking) {
    return res.status(404).json({ error: 'Booking not found' });
  }

  return res.json(booking);
});

// Update a booking
router.put('/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { service, date } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid booking ID' });
  }

  if (!service || !date) {
    return res.status(400).json({ error: 'Service and date are required' });
  }

  const updatedBooking = mockUpdateBooking(id, { service, date });

  if (!updatedBooking) {
    return res.status(404).json({ error: 'Booking not found' });
  }

  return res.json(updatedBooking);
});

// Cancel a booking
router.delete('/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid booking ID' });
  }

  const cancelledBooking = mockCancelBooking(id);

  if (!cancelledBooking) {
    return res.status(404).json({ error: 'Booking not found' });
  }

  return res.json(cancelledBooking);
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock payment processing - in a real app this would integrate with a payment gateway
const processPayment = async (amount: number, cardDetails: any): Promise<boolean> => {
  // Simulate payment processing delay
  await new Promise(resolve => setTimeout(resolve, 100));
  // Mock successful payment
  return true;
};

// Handle payment processing for a booking
router.post("/process", async (req: Request, res: Response) => {
  try {
    const { amount, cardDetails } = req.body;

    // Validate required fields
    if (!amount || !cardDetails) {
      return res.status(400).json({ error: "Amount and card details are required" });
    }

    // Validate amount is a positive number
    if (typeof amount !== "number" || amount <= 0) {
      return res.status(400).json({ error: "Invalid amount" });
    }

    // Process the payment
    const paymentSuccess = await processPayment(amount, cardDetails);

    if (paymentSuccess) {
      return res.status(200).json({ 
        success: true, 
        message: "Payment processed successfully" 
      });
    } else {
      return res.status(400).json({ 
        success: false, 
        message: "Payment failed" 
      });
    }
  } catch (error) {
    return res.status(500).json({ 
      success: false, 
      message: "Internal server error" 
    });
