              borderRadius: "8px",
              padding: "15px",
              backgroundColor: "#f9f9f9",
            }}
          >
            <div style={{ marginBottom: "10px" }}>
              <strong>Date:</strong> {booking.date}
            </div>
            <div style={{ marginBottom: "10px" }}>
              <strong>Time:</strong> {booking.time}
            </div>
            <div style={{ marginBottom: "10px" }}>
              <strong>Service:</strong> {booking.service}
            </div>
            <div style={{ marginBottom: "10px" }}>
              <strong>Status:</strong> {booking.status}
