export const router = Router();

// Mock book data structure
interface Book {
  id: number;
  title: string;
  author: string;
  isbn?: string;
  pages?: number;
}

// In-memory storage for demonstration purposes
let books: Book[] = [
  { id: 1, title: "1984", author: "George Orwell", isbn: "978-0-452-28423-4", pages: 328 },
  { id: 2, title: "To Kill a Mockingbird", author: "Harper Lee", isbn: "978-0-06-112008-4", pages: 281 }
];

let nextId = 3;

// Get all books
router.get("/", (req: Request, res: Response) => {
  res.json(books);
});

// Get a book by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid book ID" });
  }

  const book = books.find(b => b.id === id);

  if (!book) {
    return res.status(404).json({ error: "Book not found" });
  }

  res.json(book);
});

// Create a new book
router.post("/", (req: Request, res: Response) => {
  const { title, author, isbn, pages } = req.body;

  // Basic validation
  if (!title || !author) {
    return res.status(400).json({ error: "Title and author are required" });
  }

  const newBook: Book = {
    id: nextId++,
    title,
    author,
    isbn,
    pages
  };

  books.push(newBook);

  res.status(201).json(newBook);
});

// Update a book
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid book ID" });
  }

  const bookIndex = books.findIndex(b => b.id === id);

  if (bookIndex === -1) {
    return res.status(404).json({ error: "Book not found" });
  }

  const { title, author, isbn, pages } = req.body;

  // Basic validation
  if (!title || !author) {
    return res.status(400).json({ error: "Title and author are required" });
  }

  books[bookIndex] = {
    id,
    title,
    author,
    isbn,
    pages
  };

  res.json(books[bookIndex]);
});

// Delete a book
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid book ID" });
  }

  const bookIndex = books.findIndex(b => b.id === id);

  if (bookIndex === -1) {
    return res.status(404).json({ error: "Book not found" });
  }

  books.splice(bookIndex, 1);

  res.json({ message: "Book deleted successfully" });
});

