// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  products: [
    { id: 1, name: "Pencil", price: 1.5, stock: 100 },
    { id: 2, name: "Notebook", price: 3.0, stock: 50 },
    { id: 3, name: "Eraser", price: 0.5, stock: 200 }
  ],

  getAllProducts(): Promise<any[]> {
    return Promise.resolve(this.products);
  },

  getProductById(id: number): Promise<any> {
    const product = this.products.find(p => p.id === id);
    return Promise.resolve(product);
  },

  createProduct(productData: any): Promise<any> {
    const newProduct = {
      id: this.products.length + 1,
      ...productData
    };
    this.products.push(newProduct);
    return Promise.resolve(newProduct);
  },

  updateProduct(id: number, productData: any): Promise<any> {
    const index = this.products.findIndex(p => p.id === id);
    if (index === -1) return Promise.reject({ status: 404 });

    this.products[index] = { ...this.products[index], ...productData };
    return Promise.resolve(this.products[index]);
  },

  deleteProduct(id: number): Promise<void> {
    const index = this.products.findIndex(p => p.id === id);
    if (index === -1) return Promise.reject({ status: 404 });

    this.products.splice(index, 1);
    return Promise.resolve();
  }
};

