import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidRole(role: string): boolean {
  return role === "admin" || role === "staff";
}

function verifyToken(token: string): { role: string } | null {
  if (!JWT_SECRET) {
    return null;
  }

  try {
    const [header, payload, signature] = token.split(".");

    if (!header || !payload || !signature) {
      return null;
    }

    // Verify signature
    const expectedSignature = createHmac("sha256", JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return null;
    }

    // Decode payload
    const decodedPayload = Buffer.from(payload, "base64url").toString("utf-8");
    const parsedPayload = JSON.parse(decodedPayload);

    if (!isValidRole(parsedPayload.role)) {
      return null;
    }

    return { role: parsedPayload.role };
  } catch (err) {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check access control for specific routes and methods
  const protectedPaths = ["/billing", "/reports"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath || (req.method !== "POST" && req.method !== "GET")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const decodedToken = verifyToken(token);

  if (!decodedToken) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Check if user has required role
  if (decodedToken.role !== "admin" && decodedToken.role !== "staff") {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  // Attach role to request for downstream middleware/routes
  (req as any).userRole = decodedToken.role;
  next();
}

