    <div style={containerStyle}>
      <h1>Inventory Management</h1>

      <form onSubmit={editingId ? handleUpdate : handleSubmit} style={formStyle}>
        <h2>{editingId ? 'Edit Product' : 'Add New Product'}</h2>
        <input
          type="text"
          placeholder="Product Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          style={inputStyle}
          required
        />
        <input
          type="number"
          placeholder="Price"
          value={price}
          onChange={(e) => setPrice(e.target.value)}
          style={inputStyle}
          required
        />
        <input
          type="number"
          placeholder="Quantity"
          value={quantity}
          onChange={(e) => setQuantity(e.target.value)}
          style={inputStyle}
          required
        />
        <button type="submit" style={buttonStyle}>
          {editingId ? 'Update Product' : 'Add Product'}
        </button>
      </form>

      <h2>Product List</h2>

      {products.length === 0 ? (
        <p>No products found.</p>
      ) : (
        <table style={tableStyle}>
          <thead>
            <tr>
              <th style={thTdStyle}>Name</th>
              <th style={thTdStyle}>Price</th>
              <th style={thTdStyle}>Quantity</th>
              <th style={thTdStyle}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product) => (
              <tr key={product.id}>
                <td style={thTdStyle}>{product.name}</td>
                <td style={thTdStyle}>${product.price.toFixed(2)}</td>
                <td style={thTdStyle}>{product.quantity}</td>
                <td style={thTdStyle}>
                  <button 
                    onClick={() => handleEdit(product)}
                    style={{ ...buttonStyle, backgroundColor: '#ffc107', marginRight: '5px' }}
                  >
                    Edit
                  </button>
                  <button 
                    onClick={() => handleDelete(product.id)}
                    style={{ ...buttonStyle, backgroundColor: '#dc3545' }}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Product {
  id: number;
  name: string;
  price: number;
}

interface InvoiceItem {
  productId: number;
  quantity: number;
}

interface Invoice {
  id: number;
  customerId: number;
  items: InvoiceItem[];
  total: number;
  status: "pending" | "paid";
}

export function BillingSystem() {
  const [products, setProducts] = useState<Product[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState<number>(1);
  const [invoiceItems, setInvoiceItems] = useState<InvoiceItem[]>([
    { productId: 1, quantity: 1 },
  ]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Simulate fetching products
    const fetchProducts = async () => {
      try {
        // In a real app, this would be an API call
        const mockProducts: Product[] = [
          { id: 1, name: "Pencil", price: 0.5 },
          { id: 2, name: "Notebook", price: 2.0 },
          { id: 3, name: "Eraser", price: 0.3 },
        ];
        setProducts(mockProducts);
        setLoading(false);
      } catch (err) {
        setError("Failed to load products");
        setLoading(false);
      }
    };

    // Simulate fetching invoices
    const fetchInvoices = async () => {
      try {
        // In a real app, this would be an API call
        const mockInvoices: Invoice[] = [
          { id: 1, customerId: 1, items: [{ productId: 1, quantity: 2 }], total: 1.0, status: "paid" },
          { id: 2, customerId: 1, items: [{ productId: 2, quantity: 1 }], total: 2.0, status: "pending" },
        ];
        setInvoices(mockInvoices);
        setLoading(false);
      } catch (err) {
        setError("Failed to load invoices");
        setLoading(false);
      }
    };

    fetchProducts();
    fetchInvoices();
  }, []);

  const handleAddItem = () => {
    setInvoiceItems([...invoiceItems, { productId: 1, quantity: 1 }]);
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...invoiceItems];
    newItems.splice(index, 1);
    setInvoiceItems(newItems);
  };

  const handleQuantityChange = (index: number, value: string) => {
    const newItems = [...invoiceItems];
    newItems[index].quantity = Number(value);
    setInvoiceItems(newItems);
  };

  const handleProductChange = (index: number, value: string) => {
    const newItems = [...invoiceItems];
    newItems[index].productId = Number(value);
    setInvoiceItems(newItems);
  };

  const calculateTotal = (): number => {
    return invoiceItems.reduce((total, item) => {
      const product = products.find(p => p.id === item.productId);
      return total + (product ? product.price * item.quantity : 0);
    }, 0);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      // In a real app, this would be an API call
      const newInvoice: Invoice = {
        id: invoices.length + 1,
        customerId: selectedCustomerId,
        items: invoiceItems,
        total: calculateTotal(),
        status: "pending",
      };

      // Simulate successful creation
      setInvoices([...invoices, newInvoice]);

      // Reset form
      setInvoiceItems([{ productId: 1, quantity: 1 }]);
    } catch (err) {
      setError("Failed to create invoice");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Billing System</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Customer ID:</label>
          <input
            type="number"
            value={selectedCustomerId}
            onChange={(e) => setSelectedCustomerId(Number(e.target.value))}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <h2>Invoice Items</h2>
        {invoiceItems.map((item, index) => (
          <div key={index} style={{ display: "flex", gap: "10px", marginBottom: "10px", alignItems: "flex-end" }}>
            <div style={{ flex: 1 }}>
              <label style={{ display: "block", marginBottom: "5px" }}>Product:</label>
              <select
                value={item.productId}
                onChange={(e) => handleProductChange(index, e.target.value)}
                style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              >
                {products.map(product => (
                  <option key={product.id} value={product.id}>{product.name}</option>
                ))}
              </select>
            </div>

            <div style={{ flex: 1 }}>
              <label style={{ display: "block", marginBottom: "5px" }}>Quantity:</label>
              <input
                type="number"
                min="1"
                value={item.quantity}
                onChange={(e) => handleQuantityChange(index, e.target.value)}
                style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              />
            </div>

            <button
              type="button"
              onClick={() => handleRemoveItem(index)}
              style={{ padding: "8px 12px", backgroundColor: "#ff4d4d", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
            >
              Remove
            </button>
          </div>
        ))}

        <button
          type="button"
          onClick={handleAddItem}
          style={{ padding: "8px 12px", backgroundColor: "#1890ff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer", marginBottom: "15px" }}
        >
          Add Item
        </button>

        <div style={{ marginBottom: "15px", fontWeight: "bold" }}>
          Total: ${calculateTotal().toFixed(2)}
        </div>

        <button
          type="submit"
          style={{ padding: "10px 20px", backgroundColor: "#52c41a", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
        >
          Process Payment
        </button>
      </form>

      <h2>Recent Invoices</h2>
      {invoices.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No invoices found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {invoices.map(invoice => (
            <div key={invoice.id} style={{ padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "5px" }}>
                <span>Invoice #{invoice.id}</span>
                <span style={{ fontWeight: "bold" }}>${invoice.total.toFixed(2)}</span>
              </div>
              <div style={{ marginBottom: "5px" }}>
                Status: <span style={{ color: invoice.status === "paid" ? "green" : "orange" }}>{invoice.status}</span>
              </div>
              <div>
                Items: {invoice.items.map(item => {
                  const product = products.find(p => p.id === item.productId);
                  return product ? `${product.name} x${item.quantity}` : "";
                }).join(", ")}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Customer {
  id: number;
  name: string;
  email: string;
  phone: string;
}

export function CustomerManagement() {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<Omit<Customer, "id">>({ 
    name: "", 
    email: "", 
    phone: ""
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchCustomers();
  }, []);

  const fetchCustomers = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/customers");
      if (!response.ok) throw new Error("Failed to fetch customers");
      const data = await response.json();
      setCustomers(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/customers", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });
      if (!response.ok) throw new Error("Failed to add customer");
      await fetchCustomers();
      setFormData({ name: "", email: "", phone: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId === null) return;
    try {
      const response = await fetch(`/api/customers/${editingId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });
      if (!response.ok) throw new Error("Failed to update customer");
      await fetchCustomers();
      setEditingId(null);
      setFormData({ name: "", email: "", phone: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/customers/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) throw new Error("Failed to delete customer");
      await fetchCustomers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const startEdit = (customer: Customer) => {
    setFormData({ name: customer.name, email: customer.email, phone: customer.phone });
    setEditingId(customer.id);
  };

  const cancelEdit = () => {
    setEditingId(null);
    setFormData({ name: "", email: "", phone: "" });
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Customer Management</h1>

      {error && <div style={{ color: "red", marginBottom: "20px" }}>{error}</div>}

      <form onSubmit={editingId ? handleUpdate : handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>{editingId ? "Edit Customer" : "Add New Customer"}</h2>
        <div style={{ marginBottom: "15px" }}>
          <input
            type="text"
            name="name"
            placeholder="Name"
            value={formData.name}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>
        <div style={{ marginBottom: "15px" }}>
          <input
            type="email"
            name="email"
            placeholder="Email"
            value={formData.email}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>
        <div style={{ marginBottom: "15px" }}>
          <input
            type="tel"
            name="phone"
            placeholder="Phone"
            value={formData.phone}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>
        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          {editingId ? "Update Customer" : "Add Customer"}
        </button>
        {editingId && (
          <button 
            type="button" 
            onClick={cancelEdit}
            style={{ 
              backgroundColor: "#6c757d", 
              color: "white", 
              border: "none", 
              padding: "10px 20px", 
              borderRadius: "4px", 
              cursor: "pointer", 
              marginLeft: "10px" 
            }}
          >
            Cancel
          </button>
        )}
      </form>

      <h2>Customer List</h2>
      {customers.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No customers found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {customers.map(customer => (
            <div 
              key={customer.id} 
              style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}
            >
              <div>
                <strong>{customer.name}</strong><br />
                {customer.email}<br />
                {customer.phone}
              </div>
              <div>
                <button 
                  onClick={() => startEdit(customer)}
                  style={{ 
                    backgroundColor: "#28a745", 
                    color: "white", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: "4px", 
                    cursor: "pointer", 
                    marginRight: "5px" 
                  }}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(customer.id)}
                  style={{ 
                    backgroundColor: "#dc3545", 
                    color: "white", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: "4px", 
                    cursor: "pointer" 
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

