import { useEffect, useState } from "react";

interface Paper {
  id: string;
  title: string;
  authors: string[];
  status: "submitted" | "under-review" | "accepted" | "rejected";
}

export function Dashboard() {
  const [papers, setPapers] = useState<Paper[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchPapers();
  }, []);

  const fetchPapers = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/papers");
      if (!response.ok) {
        throw new Error(`Failed to fetch papers: ${response.status}`);
      }
      const data = await response.json();
      setPapers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (papers.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No papers found.</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Research Paper Dashboard</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {papers.map((paper) => (
          <div 
            key={paper.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              backgroundColor: "#f9f9f9"
            }}
          >
            <h2 style={{ margin: "0 0 10px 0", fontSize: "1.2em" }}>{paper.title}</h2>
            <p style={{ margin: "5px 0" }}><strong>Authors:</strong> {paper.authors.join(", ")}</p>
            <p style={{ margin: "5px 0" }}><strong>Status:</strong> {paper.status}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

interface Paper {
  id: string;
  title: string;
  authors: string[];
  status: "submitted" | "under-review" | "accepted" | "rejected";
  submittedDate: string;
}

export function PaperListPage() {
  const [papers, setPapers] = useState<Paper[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | Paper["status"]>("all");

  useEffect(() => {
    fetchPapers();
  }, []);

  const fetchPapers = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/papers");
      if (!response.ok) {
        throw new Error(`Failed to fetch papers: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setPapers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const filteredPapers = papers.filter(paper => {
    const matchesSearch = paper.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          paper.authors.some(author => author.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesStatus = statusFilter === "all" || paper.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Research Papers</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search papers..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value as "all" | Paper["status"])}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Statuses</option>
          <option value="submitted">Submitted</option>
          <option value="under-review">Under Review</option>
          <option value="accepted">Accepted</option>
          <option value="rejected">Rejected</option>
        </select>
      </div>

      {filteredPapers.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No papers found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredPapers.map(paper => (
            <div 
              key={paper.id}
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: "#f9f9f9"
