export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to the upload endpoint
  if (req.method !== "POST" || req.path !== "/upload") {
    next();
    return;
  }

  // Check if file upload is present
  if (!req.files || Object.keys(req.files).length === 0) {
    res.status(400).json({ error: "No file uploaded" });
    return;
  }

  // Validate file type and size
  const file = Array.isArray(req.files.audio) ? req.files.audio[0] : req.files.audio;

  if (!file) {
    res.status(400).json({ error: "Invalid file format" });
    return;
  }

  // Check file extension
  const allowedExtensions = [".mp3", ".wav", ".aac"];
  const fileExtension = file.name.slice(file.name.lastIndexOf("."));
  if (!allowedExtensions.includes(fileExtension.toLowerCase())) {
    res.status(400).json({ error: "Invalid file type. Only MP3, WAV, and AAC files are allowed." });
    return;
  }

  // Check file size (limit to 50MB)
  const maxSizeInBytes = 50 * 1024 * 1024;
  if (file.size > maxSizeInBytes) {
    res.status(400).json({ error: "File size exceeds 50MB limit" });
    return;
  }

  // Simulate virus scan (placeholder)
  // In a real implementation, integrate with antivirus software
  const isInfected = false;
  if (isInfected) {
    res.status(400).json({ error: "File is infected with malware" });
    return;
  }

  next();
}

import { useEffect, useState } from "react";

interface Exhibit {
  id: number;
  title: string;
  description: string;
  location: string;
  audioContent: string;
}

export function ExhibitManagementPage() {
  const [exhibits, setExhibits] = useState<Exhibit[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [formData, setFormData] = useState<Omit<Exhibit, "id">>({ 
    title: "",
    description: "",
    location: "",
    audioContent: ""
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  // Fetch exhibits
  useEffect(() => {
    const fetchExhibits = async () => {
      try {
        const response = await fetch('/api/exhibits');
        if (!response.ok) throw new Error('Failed to fetch exhibits');
        const data = await response.json();
        setExhibits(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchExhibits();
  }, []);

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/exhibits/${editingId}`
        : '/api/exhibits';

      const method = editingId ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (!response.ok) throw new Error('Failed to save exhibit');

      // Refresh exhibits list
      const updatedResponse = await fetch('/api/exhibits');
      if (!updatedResponse.ok) throw new Error('Failed to refresh exhibits');
      const updatedData = await updatedResponse.json();
      setExhibits(updatedData);

      // Reset form
      setFormData({ title: '', description: '', location: '', audioContent: '' });
      setEditingId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Handle edit
  const handleEdit = (exhibit: Exhibit) => {
    setFormData({ 
      title: exhibit.title,
      description: exhibit.description,
      location: exhibit.location,
      audioContent: exhibit.audioContent
    });
    setEditingId(exhibit.id);
  };

  // Handle delete
  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/exhibits/${id}`, { method: 'DELETE' });
      if (!response.ok) throw new Error('Failed to delete exhibit');

      // Refresh exhibits list
      const updatedResponse = await fetch('/api/exhibits');
      if (!updatedResponse.ok) throw new Error('Failed to refresh exhibits');
      const updatedData = await updatedResponse.json();
      setExhibits(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Filter exhibits based on search term
  const filteredExhibits = exhibits.filter(exhibit => 
    exhibit.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    exhibit.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
    exhibit.location.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Styles
  const containerStyle: React.CSSProperties = {
    maxWidth: '800px',
    margin: '0 auto',
    padding: '20px',
    fontFamily: 'system-ui, sans-serif'
  };

  const formStyle: React.CSSProperties = {
    display: 'flex',
    flexDirection: 'column',
    gap: '10px',
    marginBottom: '20px',
    padding: '20px',
    border: '1px solid #ccc',
    borderRadius: '8px',
    backgroundColor: '#f9f9f9'
  };

  const inputStyle: React.CSSProperties = {
    padding: '10px',
    borderRadius: '4px',
    border: '1px solid #ddd',
    width: '100%',
    boxSizing: 'border-box'
  };

  const buttonStyle: React.CSSProperties = {
    padding: '10px 15px',
    borderRadius: '4px',
    border: 'none',
    backgroundColor: '#007bff',
    color: 'white',
    cursor: 'pointer',
    fontSize: '16px'
  };

  const gridStyle: React.CSSProperties = {
    display: 'flex',
    flexWrap: 'wrap',
    gap: '15px'
  };

  const cardStyle: React.CSSProperties = {
    flex: '1 1 300px',
    border: '1px solid #ddd',
    borderRadius: '8px',
    padding: '15px',
    backgroundColor: '#fff'
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: 'flex',
    gap: '10px',
    marginTop: '10px'
  };

  if (loading) return <div style={containerStyle}>Loading...</div>;
  if (error) return <div style={containerStyle}>Error: {error}</div>;

  return (
    <div style={containerStyle}>
      <h1>Exhibit Management</h1>

      <input
        type="text"
        placeholder="Search exhibits..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        style={inputStyle}
      />

      <form onSubmit={handleSubmit} style={formStyle}>
        <h2>{editingId ? 'Edit Exhibit' : 'Add New Exhibit'}</h2>
        <input
          type="text"
          name="title"
          placeholder="Title"
          value={formData.title}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <textarea
          name="description"
          placeholder="Description"
          value={formData.description}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <input
          type="text"
          name="location"
          placeholder="Location"
          value={formData.location}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <input
          type="text"
          name="audioContent"
          placeholder="Audio Content ID"
          value={formData.audioContent}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <button type="submit" style={buttonStyle}>Save Exhibit</button>
      </form>

      <h2>Exhibits List</h2>
      <div style={gridStyle}>
        {filteredExhibits.length === 0 ? (
          <p>No exhibits found.</p>
        ) : (
          filteredExhibits.map(exhibit => (
            <div key={exhibit.id} style={cardStyle}>
              <h3>{exhibit.title}</h3>
              <p><strong>Description:</strong> {exhibit.description}</p>
              <p><strong>Location:</strong> {exhibit.location}</p>
              <p><strong>Audio Content:</strong> {exhibit.audioContent}</p>
              <div style={buttonGroupStyle}>
                <button onClick={() => handleEdit(exhibit)} style={buttonStyle}>Edit</button>
                <button onClick={() => handleDelete(exhibit.id)} style={buttonStyle}>Delete</button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

