import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data to simulate a database
let bookings = [] as { id: number; customerId: number; date: string; time: string; status: string }[];
let nextId = 1;

// Validate booking data
const validateBooking = (data: any): boolean => {
  return (
    data.customerId !== undefined &&
    data.date !== undefined &&
    data.time !== undefined &&
    typeof data.customerId === 'number' &&
    typeof data.date === 'string' &&
    typeof data.time === 'string'
  );
};

// GET /bookings - List all bookings
router.get('/bookings', (req: Request, res: Response) => {
  res.json(bookings);
});

// GET /bookings/:id - Get a specific booking by ID
router.get('/bookings/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const booking = bookings.find(b => b.id === id);

  if (!booking) {
    return res.status(404).json({ error: 'Booking not found' });
  }

  res.json(booking);
});

// POST /bookings - Create a new booking
router.post('/bookings', (req: Request, res: Response) => {
  const { customerId, date, time } = req.body;

  if (!validateBooking(req.body)) {
    return res.status(400).json({ error: 'Invalid booking data' });
  }

  const newBooking = {
    id: nextId++,
    customerId,
    date,
    time,
    status: 'confirmed'
  };

  bookings.push(newBooking);

  res.status(201).json(newBooking);
});

// PUT /bookings/:id - Update a booking
router.put('/bookings/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const bookingIndex = bookings.findIndex(b => b.id === id);

  if (bookingIndex === -1) {
    return res.status(404).json({ error: 'Booking not found' });
  }

  const { customerId, date, time } = req.body;

  if (!validateBooking(req.body)) {
    return res.status(400).json({ error: 'Invalid booking data' });
  }

  bookings[bookingIndex] = {
    ...bookings[bookingIndex],
    customerId,
    date,
    time
  };

  res.json(bookings[bookingIndex]);
});

// DELETE /bookings/:id - Delete a booking
router.delete('/bookings/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const bookingIndex = bookings.findIndex(b => b.id === id);

  if (bookingIndex === -1) {
    return res.status(404).json({ error: 'Booking not found' });
  }

  bookings.splice(bookingIndex, 1);

  res.json({ message: 'Booking deleted successfully' });
});

