import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to admin routes
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") ||
      !req.path.startsWith("/admin")) {
    return next();
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      return res.status(401).json({ error: "Invalid token format" });
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Invalid token" });
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    return res.status(401).json({ error: "Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Define the session type
interface Session {
  userId: string;
  expiresAt: Date;
}

// Mock session store - in a real app this would be a database
const sessionStore: Map<string, Session> = new Map();

// Helper to check if session has expired
function isSessionExpired(session: Session): boolean {
  return new Date() > session.expiresAt;
}

// Middleware function
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation (in a real app, use a proper JWT library)
  try {
    const [userId, signature] = token.split(":");
    if (!userId || !signature) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Verify signature
    const expectedSignature = createHmac("sha256", secret)
      .update(userId)
      .digest("hex");

    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    if (expectedBuffer.length !== actualBuffer.length || !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Check if session exists and is valid
    const session = sessionStore.get(userId);
    if (!session || isSessionExpired(session)) {
      res.status(401).json({ error: "Unauthorized: Session expired or invalid" });
      return;
    }

    // Attach user to request object
    (req as any).user = { id: session.userId };
    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Token verification failed" });
  }
}

