const mockDb = {
  getAllMachines: async () => [
    { id: 1, name: "Machine A", model: "Model X", serialNumber: "SN001", status: "active" },
    { id: 2, name: "Machine B", model: "Model Y", serialNumber: "SN002", status: "inactive" }
  ],
  getMachineById: async (id: number) => {
    const machines = await mockDb.getAllMachines();
    return machines.find(m => m.id === id) || null;
  },
  createMachine: async (machineData: any) => {
    const machines = await mockDb.getAllMachines();
    const newId = machines.length > 0 ? Math.max(...machines.map(m => m.id)) + 1 : 1;
    return { id: newId, ...machineData };
  },
  updateMachine: async (id: number, machineData: any) => {
    const machines = await mockDb.getAllMachines();
    const index = machines.findIndex(m => m.id === id);
    if (index === -1) return null;
    machines[index] = { ...machines[index], ...machineData };
    return machines[index];
  },
  deleteMachine: async (id: number) => {
    const machines = await mockDb.getAllMachines();
    const index = machines.findIndex(m => m.id === id);
    if (index === -1) return false;
    machines.splice(index, 1);
    return true;
  }
};

