import { useEffect, useState } from "react";

interface Machine {
  id: number;
  name: string;
  model: string;
  status: "active" | "inactive" | "maintenance";
  lastMaintenance: string;
}

export function MachineListPage() {
  const [machines, setMachines] = useState<Machine[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    fetchMachines();
  }, []);

  const fetchMachines = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/machines');
      if (!response.ok) {
        throw new Error('Failed to fetch machines');
      }
      const data = await response.json();
      setMachines(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const filteredMachines = machines.filter(machine =>
    machine.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    machine.model.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Factory Machine List</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search machines..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
      </div>

      {filteredMachines.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No machines found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredMachines.map(machine => (
            <div 
              key={machine.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center",
                backgroundColor: "#f9f9f9"
              }}
            >
              <div>
                <h3 style={{ margin: "0 0 5px 0" }}>{machine.name}</h3>
                <p style={{ margin: "0 0 5px 0", color: "#666" }}>
                  Model: {machine.model}
                </p>
                <p style={{ margin: "0 0 5px 0", color: "#666" }}>
                  Last Maintenance: {machine.lastMaintenance}
                </p>
                <span 
                  style={{ 
                    padding: "3px 8px", 
                    borderRadius: "4px", 
                    fontSize: "0.8em",
                    backgroundColor: machine.status === "active" ? "#d4edda" : 
                                  machine.status === "maintenance" ? "#fff3cd" : "#f8d7da",
                    color: machine.status === "active" ? "#155724" : 
                          machine.status === "maintenance" ? "#856404" : "#721c24"
                  }}
                >
                  {machine.status.charAt(0).toUpperCase() + machine.status.slice(1)}
                </span>
              </div>
              <div style={{ display: "flex", gap: "10px" }}>
                <button 
                  onClick={() => {
                    // In a real app, this would navigate to a detail page
                    alert(`View details for ${machine.name}`);
                  }}
                  style={{ 
                    padding: "8px 12px", 
                    backgroundColor: "#007bff", 
                    color: "white", 
                    border: "none", 
                    borderRadius: "4px", 
                    cursor: "pointer"
                  }}
                >
                  View Details
                </button>
                <button 
                  onClick={() => {
                    // In a real app, this would trigger a maintenance action
                    alert(`Schedule maintenance for ${machine.name}`);
                  }}
                  style={{ 
                    padding: "8px 12px", 
                    backgroundColor: "#28a745", 
                    color: "white", 
                    border: "none", 
                    borderRadius: "4px", 
                    cursor: "pointer"
                  }}
