import { useEffect, useState } from "react";

interface MaintenanceRecord {
  id: number;
  equipmentId: number;
  date: string;
  description: string;
  status: "completed" | "pending" | "in-progress";
}

export function MaintenanceLogPage() {
  const [records, setRecords] = useState<MaintenanceRecord[]>([]);
  const [filteredRecords, setFilteredRecords] = useState<MaintenanceRecord[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchRecords();
  }, []);

  const fetchRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/maintenance-records');
      if (!response.ok) {
        throw new Error('Failed to fetch records');
      }
      const data = await response.json();
      setRecords(data);
      setFilteredRecords(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let result = records;

    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      result = result.filter(record => 
        record.description.toLowerCase().includes(term) ||
        record.id.toString().includes(term)
      );
    }

    if (statusFilter !== "all") {
      result = result.filter(record => record.status === statusFilter);
    }

    setFilteredRecords(result);
  }, [searchTerm, statusFilter, records]);

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/maintenance-records/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error('Failed to delete record');
      }
      fetchRecords(); // Refresh the list
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Maintenance Log</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search by description or ID..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Statuses</option>
          <option value="pending">Pending</option>
          <option value="in-progress">In Progress</option>
          <option value="completed">Completed</option>
        </select>
      </div>

      {filteredRecords.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No maintenance records found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredRecords.map(record => (
            <div 
              key={record.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: "#f9f9f9"
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                <div>
                  <h3 style={{ margin: "0 0 5px 0" }}>Record #{record.id}</h3>
                  <p><strong>Equipment ID:</strong> {record.equipmentId}</p>
                  <p><strong>Date:</strong> {record.date}</p>
                  <p><strong>Description:</strong> {record.description}</p>
                  <p><strong>Status:</strong> {record.status}</p>
                </div>
                <div style={{ display: "flex", flexDirection: "column", gap: "5px" }}>
                  <button 
                    onClick={() => window.location.href = `/maintenance-records/${record.id}`}
                    style={{ 
                      padding: "5px 10px", 
                      backgroundColor: "#007bff", 
                      color: "white", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer"
                    }}
                  >
                    View Details
                  </button>
                  <button 
                    onClick={() => window.location.href = `/maintenance-records/${record.id}/edit`}
                    style={{ 
                      padding: "5px 10px", 
                      backgroundColor: "#28a745", 
                      color: "white", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer"
                    }}
                  >
                    Edit
                  </button>
                  <button 
                    onClick={() => handleDelete(record.id)}
                    style={{ 
                      padding: "5px 10px", 
                      backgroundColor: "#dc3545", 
                      color: "white", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer"
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

