import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockBatches = [
  { id: "1", name: "Advanced Mathematics", startDate: "2023-09-01", endDate: "2023-12-31", maxStudents: 30 },
  { id: "2", name: "Physics Fundamentals", startDate: "2023-10-01", endDate: "2024-01-31", maxStudents: 25 }
];

const findBatchById = (id: string) => {
  return mockBatches.find(batch => batch.id === id);
};

const getAllBatches = () => {
  return mockBatches;
};

const createBatch = (batchData: Omit<Batch, "id">) => {
  const newBatch = {
    id: String(mockBatches.length + 1),
    ...batchData
  };
  mockBatches.push(newBatch);
  return newBatch;
};

const updateBatch = (id: string, updatedData: Partial<Batch>) => {
  const index = mockBatches.findIndex(batch => batch.id === id);
  if (index === -1) return null;

  mockBatches[index] = { ...mockBatches[index], ...updatedData };
  return mockBatches[index];
};

const deleteBatch = (id: string) => {
  const index = mockBatches.findIndex(batch => batch.id === id);
  if (index === -1) return false;

  mockBatches.splice(index, 1);
  return true;
};

// Define the Batch interface
interface Batch {
  id: string;
  name: string;
  startDate: string;
  endDate: string;
  maxStudents: number;
}

// GET /batches - Get all batches
router.get("/batches", (req: Request, res: Response) => {
  try {
    const batches = getAllBatches();
    res.json(batches);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// GET /batches/:id - Get a specific batch by ID
router.get("/batches/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const batch = findBatchById(id);

    if (!batch) {
      return res.status(404).json({ error: "Batch not found" });
    }

    res.json(batch);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// POST /batches - Create a new batch
router.post("/batches", (req: Request, res: Response) => {
  try {
    const { name, startDate, endDate, maxStudents } = req.body;

    // Validate required fields
    if (!name || !startDate || !endDate || maxStudents === undefined) {
      return res.status(400).json({ error: "Name, start date, end date, and max students are required" });
    }

    // Validate maxStudents is a number
    if (typeof maxStudents !== "number") {
      return res.status(400).json({ error: "Max students must be a number" });
    }

    const newBatch = createBatch({ name, startDate, endDate, maxStudents });
    res.status(201).json(newBatch);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// PUT /batches/:id - Update a batch
router.put("/batches/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const { name, startDate, endDate, maxStudents } = req.body;

    const existingBatch = findBatchById(id);
    if (!existingBatch) {
      return res.status(404).json({ error: "Batch not found" });
    }

    const updatedBatch = updateBatch(id, { name, startDate, endDate, maxStudents });

    if (!updatedBatch) {
      return res.status(404).json({ error: "Batch not found" });
    }

    res.json(updatedBatch);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// DELETE /batches/:id - Delete a batch
router.delete("/batches/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const deleted = deleteBatch(id);

    if (!deleted) {
      return res.status(404).json({ error: "Batch not found" });
    }

    res.json({ message: "Batch deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

