  },

  createStudent: (studentData: any): Promise<any> => {
    const newStudent = {
      id: mockDatabase.students.length + 1,
      ...studentData
    };
    mockDatabase.students.push(newStudent);
    return Promise.resolve(newStudent);
  },

  updateStudent: (id: number, studentData: any): Promise<any | null> => {
    const index = mockDatabase.students.findIndex(s => s.id === id);
    if (index === -1) return Promise.resolve(null);

    mockDatabase.students[index] = { ...mockDatabase.students[index], ...studentData };
    return Promise.resolve(mockDatabase.students[index]);
  },

  deleteStudent: (id: number): Promise<boolean> => {
    const initialLength = mockDatabase.students.length;
    mockDatabase.students = mockDatabase.students.filter(s => s.id !== id);
    return Promise.resolve(mockDatabase.students.length < initialLength);
  }
};

