import { useEffect, useState } from "react";

interface Student {
  id: number;
  name: string;
  gradeLevel: string;
  parentContact: string;
  paymentHistory: Payment[];
}

interface Payment {
  id: number;
  amount: number;
  date: string;
  status: "paid" | "pending" | "overdue";
}

export function StudentManagement() {
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [newStudent, setNewStudent] = useState({
    name: "",
    gradeLevel: "",
    parentContact: "",
  });

  useEffect(() => {
    fetchStudents();
  }, []);

  const fetchStudents = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/students");
      if (!response.ok) {
        throw new Error(`Failed to fetch students: ${response.status}`);
      }
      const data = await response.json();
      setStudents(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAddStudent = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/students", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newStudent),
      });
      if (!response.ok) {
        throw new Error(`Failed to add student: ${response.status}`);
      }
      setNewStudent({ name: "", gradeLevel: "", parentContact: "" });
      fetchStudents();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const filteredStudents = students.filter(student =>
    student.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    student.gradeLevel.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Student Management</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search students..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
      </div>

      <form onSubmit={handleAddStudent} style={{ marginBottom: "30px", padding: "20px", backgroundColor: "#f5f5f5", borderRadius: "8px" }}>
        <h2>Add New Student</h2>
        <div style={{ marginBottom: "10px" }}>
          <input
            type="text"
            placeholder="Student Name"
            value={newStudent.name}
            onChange={(e) => setNewStudent({...newStudent, name: e.target.value})}
            style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <input
            type="text"
            placeholder="Grade Level"
            value={newStudent.gradeLevel}
            onChange={(e) => setNewStudent({...newStudent, gradeLevel: e.target.value})}
            style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <input
            type="text"
            placeholder="Parent Contact Info"
            value={newStudent.parentContact}
            onChange={(e) => setNewStudent({...newStudent, parentContact: e.target.value})}
            style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>
        <button type="submit" style={{ padding: "10px 20px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>Add Student</button>
      </form>

      {filteredStudents.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No students found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredStudents.map(student => (
            <div key={student.id} style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "15px", backgroundColor: "#fff" }}>
              <h3>{student.name}</h3>
              <p><strong>Grade:</strong> {student.gradeLevel}</p>
              <p><strong>Parent Contact:</strong> {student.parentContact}</p>
              <h4>Payment History</h4>
              {student.paymentHistory.length === 0 ? (
                <p>No payment history available.</p>
              ) : (
                <ul style={{ paddingLeft: "20px" }}>
                  {student.paymentHistory.map(payment => (
                    <li key={payment.id}>
                      Amount: ${payment.amount}, Date: {payment.date}, Status: {payment.status}
                    </li>
                  ))}
                </ul>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

