export const router = Router();

// Mock user database - in a real app this would be a proper database
const users: Record<string, { email: string; password: string }> = {};

// Register a new user
router.post("/register", (req: Request, res: Response) => {
  const { email, password } = req.body;

  // Validate input
  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Check if user already exists
  if (users[email]) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Store user (in a real app, hash the password)
  users[email] = { email, password };

  // Generate a mock JWT token
  const token = `mock-jwt-token-for-${email}`;

  res.status(201).json({ token });
});

// Login existing user
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  // Validate input
  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Check if user exists and password matches
  const user = users[email];
  if (!user || user.password !== password) {
    return res.status(400).json({ error: "Invalid email or password" });
  }

  // Generate a mock JWT token
  const token = `mock-jwt-token-for-${email}`;

  res.json({ token });
});

// Middleware to verify JWT token (mock implementation)
const authenticateToken = (req: Request, res: Response, next: Function) => {
  // In a real app, this would verify the JWT token
  const authHeader = req.headers["authorization"];
  const token = authHeader && authHeader.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "Access token required" });
  }

  // Mock validation - in a real app, verify the token
  if (token.startsWith("mock-jwt-token-for-")) {
    next();
  } else {
    res.status(403).json({ error: "Invalid token" });
  }
};

// Get user profile (protected route)
router.get("/profile", authenticateToken, (req: Request, res: Response) => {
  // In a real app, extract user info from the token
  const email = req.headers["user-email"] as string;
  const user = users[email];

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  res.json({ email: user.email });
});

