                  <button 
                    onClick={() => handleDelete(post.id)}
                    style={{ 
                      padding: "4px 8px", 
                      backgroundColor: "#dc3545", 
                      color: "white", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer"
                    }}
