import { useEffect, useState } from "react";

interface ClassSchedule {
  id: string;
  className: string;
  instructor: string;
  date: string;
  time: string;
  duration: number;
  maxParticipants: number;
}

export function AdminClassManagement() {
  const [classes, setClasses] = useState<ClassSchedule[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form state
  const [formData, setFormData] = useState<Omit<ClassSchedule, 'id'>>({ 
    className: '',
    instructor: '',
    date: '',
    time: '',
    duration: 60,
    maxParticipants: 10
  });

  const [editingId, setEditingId] = useState<string | null>(null);

  // Fetch classes
  useEffect(() => {
    const fetchClasses = async () => {
      try {
        const response = await fetch('/api/classes');
        if (!response.ok) {
          throw new Error('Failed to fetch classes');
        }
        const data = await response.json();
        setClasses(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchClasses();
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: name === 'duration' || name === 'maxParticipants' ? Number(value) : value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId ? `/api/classes/${editingId}` : '/api/classes';
      const method = editingId ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error('Failed to save class');
      }

      // Refresh the list
      const refreshResponse = await fetch('/api/classes');
      if (!refreshResponse.ok) {
        throw new Error('Failed to refresh classes');
      }

      const refreshedData = await refreshResponse.json();
      setClasses(refreshedData);

      // Reset form
      setFormData({ 
        className: '',
        instructor: '',
        date: '',
        time: '',
        duration: 60,
        maxParticipants: 10
      });
      setEditingId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleEdit = (cls: ClassSchedule) => {
    setFormData({
      className: cls.className,
      instructor: cls.instructor,
      date: cls.date,
      time: cls.time,
      duration: cls.duration,
      maxParticipants: cls.maxParticipants
    });
    setEditingId(cls.id);
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/classes/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error('Failed to delete class');
      }

      // Refresh the list
      const refreshResponse = await fetch('/api/classes');
      if (!refreshResponse.ok) {
        throw new Error('Failed to refresh classes');
      }

      const refreshedData = await refreshResponse.json();
      setClasses(refreshedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Admin Class Management</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>{editingId ? 'Edit Class' : 'Add New Class'}</h2>

        <div style={{ marginBottom: '15px' }}>
          <label>Class Name:</label>
          <input
            type="text"
            name="className"
            value={formData.className}
            onChange={handleInputChange}
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Instructor:</label>
          <input
            type="text"
            name="instructor"
            value={formData.instructor}
            onChange={handleInputChange}
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Date:</label>
          <input
            type="date"
            name="date"
            value={formData.date}
            onChange={handleInputChange}
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Time:</label>
          <input
            type="time"
            name="time"
            value={formData.time}
            onChange={handleInputChange}
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Duration (minutes):</label>
          <input
            type="number"
            name="duration"
            value={formData.duration}
            onChange={handleInputChange}
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            min="15"
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Max Participants:</label>
          <input
            type="number"
            name="maxParticipants"
            value={formData.maxParticipants}
            onChange={handleInputChange}
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            min="1"
            required
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#4CAF50', 
            color: 'white', 
            padding: '10px 15px', 
            border: 'none', 
            borderRadius: '4px', 
            cursor: 'pointer' 
          }}
        >
          {editingId ? 'Update Class' : 'Add Class'}
        </button>

        {editingId && (
          <button 
            type="button" 
            onClick={() => {
              setEditingId(null);
              setFormData({ 
                className: '',
                instructor: '',
                date: '',
                time: '',
                duration: 60,
                maxParticipants: 10
              });
            }}
            style={{ 
              backgroundColor: '#f44336', 
              color: 'white', 
              padding: '10px 15px', 
              border: 'none', 
              borderRadius: '4px', 
              cursor: 'pointer', 
              marginLeft: '10px' 
            }}
          >
            Cancel
          </button>
        )}
      </form>

      <h2>Class Schedule</h2>

      {classes.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No classes scheduled yet.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {classes.map(cls => (
            <div 
              key={cls.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center', 
                flexWrap: 'wrap'
              }}
            >
              <div style={{ flex: '1', minWidth: '200px' }}>
                <strong>{cls.className}</strong><br />
                Instructor: {cls.instructor}<br />
                Date: {new Date(cls.date).toLocaleDateString()}<br />
                Time: {cls.time}<br />
                Duration: {cls.duration} minutes<br />
                Max Participants: {cls.maxParticipants}
              </div>
              <div style={{ display: 'flex', gap: '10px', marginTop: '10px' }}>
                <button 
                  onClick={() => handleEdit(cls)}
                  style={{ 
                    backgroundColor: '#2196F3', 
                    color: 'white', 
                    padding: '8px 12px', 
                    border: 'none', 
                    borderRadius: '4px', 
                    cursor: 'pointer' 
                  }}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(cls.id)}
                  style={{ 
                    backgroundColor: '#f44336', 
                    color: 'white', 
                    padding: '8px 12px', 
                    border: 'none', 
                    borderRadius: '4px', 
                    cursor: 'pointer' 
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

