      </div>

      <div style={{ backgroundColor: "#f9f9f9", padding: "20px", borderRadius: "8px", marginBottom: "20px" }}>
        <h2>Description</h2>
        <p>{homestay.description}</p>
        <p><strong>Host:</strong> {homestay.hostName}</p>
        <p><strong>Price per night:</strong> ${homestay.pricePerNight}</p>
      </div>

      <div style={{ backgroundColor: "#f9f9f9", padding: "20px", borderRadius: "8px" }}>
        <h2>Book This Homestay</h2>
        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>Check-in Date</label>
            <input
              type="date"
