  }
};

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

function sanitizeInput(input: string): string {
  // Remove HTML tags
  let sanitized = input.replace(/<[^>]*>/g, '');

  // Remove script tags and content
  sanitized = sanitized.replace(/<script[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');

  // Remove iframe tags and content
  sanitized = sanitized.replace(/<iframe[^<]*(?:(?!<\/iframe>)<[^<]*)*<\/iframe>/gi, '');

  // Remove object tags and content
  sanitized = sanitized.replace(/<object[^<]*(?:(?!<\/object>)<[^<]*)*<\/object>/gi, '');

  // Remove embed tags and content
  sanitized = sanitized.replace(/<embed[^<]*(?:(?!<\/embed>)<[^<]*)*<\/embed>/gi, '');

  return sanitized;
}

function validateAndSanitizeBody(req: Request): void {
  if (req.body && typeof req.body === 'object') {
    Object.keys(req.body).forEach(key => {
      const value = req.body[key];
      if (typeof value === 'string') {
        req.body[key] = sanitizeInput(value);
      } else if (Array.isArray(value)) {
        req.body[key] = value.map(item => 
          typeof item === 'string' ? sanitizeInput(item) : item
        );
      }
    });
  }
}

function validateAndSanitizeQuery(req: Request): void {
  if (req.query && typeof req.query === 'object') {
    Object.keys(req.query).forEach(key => {
      const value = req.query[key];
      if (typeof value === 'string') {
        req.query[key] = sanitizeInput(value);
      } else if (Array.isArray(value)) {
        req.query[key] = value.map(item => 
          typeof item === 'string' ? sanitizeInput(item) : item
        );
      }
    });
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, PATCH, DELETE requests
  if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method)) {
    return next();
  }

  // Validate and sanitize body
  validateAndSanitizeBody(req);

  // Validate and sanitize query parameters
  validateAndSanitizeQuery(req);

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import jwt from "jsonwebtoken";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
  }

  try {
    // Verify token signature
    const payload = jwt.verify(token, secret);

    // If verification succeeds, attach user info to request
    (req as any).user = payload;

    next();
  } catch (err) {
    if (err instanceof Error && err.message.includes("invalid signature")) {
      return res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    }

    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

