    if (!deleted) {
      return res.status(404).json({ error: "Subject not found" });
    }

    res.json({ message: "Subject deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockTeachers = [
  { id: 1, name: "John Smith", subject: "Mathematics" },
  { id: 2, name: "Jane Doe", subject: "Physics" },
];

const findTeacherIndexById = (id: number): number => {
  return mockTeachers.findIndex(teacher => teacher.id === id);
};

const findTeacherById = (id: number): typeof mockTeachers[0] | undefined => {
  return mockTeachers.find(teacher => teacher.id === id);
};

// GET /teachers - List all teachers
router.get("/teachers", (req: Request, res: Response) => {
  res.json(mockTeachers);
});

// GET /teachers/:id - Get a specific teacher by ID
router.get("/teachers/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid teacher ID" });
  }

  const teacher = findTeacherById(id);

  if (!teacher) {
    return res.status(404).json({ error: "Teacher not found" });
  }

  res.json(teacher);
});

// POST /teachers - Create a new teacher
router.post("/teachers", (req: Request, res: Response) => {
  const { name, subject } = req.body;

  if (!name || !subject) {
    return res.status(400).json({ error: "Name and subject are required" });
  }

  const newId = mockTeachers.length > 0 ? Math.max(...mockTeachers.map(t => t.id)) + 1 : 1;
  const newTeacher = { id: newId, name, subject };

  mockTeachers.push(newTeacher);

  res.status(201).json(newTeacher);
});

// PUT /teachers/:id - Update a teacher
router.put("/teachers/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, subject } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid teacher ID" });
  }

  const index = findTeacherIndexById(id);

  if (index === -1) {
    return res.status(404).json({ error: "Teacher not found" });
  }

  if (!name || !subject) {
    return res.status(400).json({ error: "Name and subject are required" });
  }

  mockTeachers[index] = { id, name, subject };

  res.json(mockTeachers[index]);
});

// DELETE /teachers/:id - Delete a teacher
router.delete("/teachers/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid teacher ID" });
  }

  const index = findTeacherIndexById(id);

  if (index === -1) {
    return res.status(404).json({ error: "Teacher not found" });
  }

  const deletedTeacher = mockTeachers.splice(index, 1)[0];

  res.json(deletedTeacher);
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SECRET = process.env.JWT_SECRET;

function getRoleFromToken(token: string): string | null {
  try {
    const payload = token.split('.')[1];
    const decoded = Buffer.from(payload, 'base64').toString('utf-8');
    const { role } = JSON.parse(decoded);
    return role;
  } catch {
    return null;
  }
}

function verifyTokenSignature(token: string): boolean {
  if (!SECRET) return false;

  try {
    const [header, payload, signature] = token.split('.');
    const expectedSignature = createHmac('sha256', SECRET)
      .update(`${header}.${payload}`)
      .digest('base64url');

    const expectedBuffer = Buffer.from(expectedSignature, 'base64url');
    const actualBuffer = Buffer.from(signature, 'base64url');

    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check permissions for timetable-related routes
  if (!req.path.startsWith('/timetable')) {
    next();
    return;
  }

  // Only check permissions for POST, PUT, DELETE methods
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  const token = authHeader.substring(7);

  if (!verifyTokenSignature(token)) {
    res.status(401).json({ error: 'Invalid token signature' });
    return;
  }

  const role = getRoleFromToken(token);
  if (!role) {
    res.status(401).json({ error: 'Invalid token' });
    return;
  }

  // Allow only admin and editor roles to modify timetable data
  if (role !== 'admin' && role !== 'editor') {
    res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // In a real implementation, we would verify the JWT token here
  // For now, we just check that the secret exists
  // This is a placeholder for actual JWT verification logic

  // Simulate token verification
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    res.status(401).json({ error: "No token provided" });
    return;
  }

  try {
    // This is a simplified example - in reality, you'd decode and verify the JWT
    // using proper JWT libraries or manual verification with HMAC-SHA256

    // Example verification logic (simplified):
    const [header, payload, signature] = token.split(".");

    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (signatureBuffer.length !== expectedSignatureBuffer.length) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    const isValid = timingSafeEqual(signatureBuffer, expectedSignatureBuffer);

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // If we get here, token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

