import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users: { id: number; username: string; password: string }[] = [];
let nextId = 1;

// Mock JWT implementation - in a real app this would use a proper JWT library
const generateToken = (userId: number): string => {
  return `token_${userId}_${Date.now()}`;
};

const verifyToken = (token: string): number | null => {
  const match = token.match(/^token_(\d+)_\d+$/);
  if (match) {
    return parseInt(match[1], 10);
  }
  return null;
};

// Registration endpoint
router.post('/register', (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password are required' });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: 'User already exists' });
  }

  // Create new user
  const newUser = {
    id: nextId++,
    username,
    password
  };

  users.push(newUser);

  // Generate token
  const token = generateToken(newUser.id);

  res.status(201).json({
    id: newUser.id,
    username: newUser.username,
    token
  });
});

// Login endpoint
router.post('/login', (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password are required' });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Generate token
  const token = generateToken(user.id);

  res.json({
    id: user.id,
    username: user.username,
    token
  });
});

// Middleware to verify JWT token
const authenticateToken = (req: Request, res: Response, next: Function) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  const userId = verifyToken(token);
  if (!userId) {
    return res.status(403).json({ error: 'Invalid token' });
  }

  // Attach user to request
  (req as any).user = { id: userId };
  next();
};

// Get current user info (protected route)
router.get('/me', authenticateToken, (req: Request, res: Response) => {
  const userId = (req as any).user.id;
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  res.json({
    id: user.id,
    username: user.username
  });
});

