// GET /goals - List all goals
router.get("/goals", (req: Request, res: Response) => {
  res.json(goals);
});

// GET /goals/:id - Get a specific goal by ID
router.get("/goals/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const goal = goals.find(g => g.id === id);

  if (!goal) {
    return res.status(404).json({ error: "Goal not found" });
  }

  res.json(goal);
});

// POST /goals - Create a new goal
router.post("/goals", (req: Request, res: Response) => {
  const { name, targetAmount, currentAmount, deadline } = req.body;

  // Validate required fields
  if (!name || !targetAmount || !deadline) {
    return res.status(400).json({ error: "Name, target amount, and deadline are required" });
  }

  // Validate numeric fields
  const parsedTargetAmount = Number(targetAmount);
  const parsedCurrentAmount = Number(currentAmount) || 0;

  if (isNaN(parsedTargetAmount)) {
    return res.status(400).json({ error: "Target amount must be a number" });
  }

  if (isNaN(parsedCurrentAmount)) {
    return res.status(400).json({ error: "Current amount must be a number" });
  }

  const newGoal = {
    id: nextId++,
    name,
    targetAmount: parsedTargetAmount,
    currentAmount: parsedCurrentAmount,
    deadline
  };

  goals.push(newGoal);

  res.status(201).json(newGoal);
});

// PUT /goals/:id - Update a goal
router.put("/goals/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, targetAmount, currentAmount, deadline } = req.body;

  const goalIndex = goals.findIndex(g => g.id === id);

  if (goalIndex === -1) {
    return res.status(404).json({ error: "Goal not found" });
  }

  // Validate required fields
  if (!name || !targetAmount || !deadline) {
    return res.status(400).json({ error: "Name, target amount, and deadline are required" });
  }

  // Validate numeric fields
  const parsedTargetAmount = Number(targetAmount);
  const parsedCurrentAmount = Number(currentAmount) || 0;

  if (isNaN(parsedTargetAmount)) {
    return res.status(400).json({ error: "Target amount must be a number" });
  }

  if (isNaN(parsedCurrentAmount)) {
    return res.status(400).json({ error: "Current amount must be a number" });
  }

  goals[goalIndex] = {
    id,
    name,
    targetAmount: parsedTargetAmount,
    currentAmount: parsedCurrentAmount,
    deadline
  };

  res.json(goals[goalIndex]);
});

// DELETE /goals/:id - Delete a goal
router.delete("/goals/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const goalIndex = goals.findIndex(g => g.id === id);

  if (goalIndex === -1) {
    return res.status(404).json({ error: "Goal not found" });
  }

