import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// In-memory storage for rate limits
const rateLimits = new Map<string, { count: number; windowStart: number }>();

// Configuration
const MAX_REQUESTS = 100;
const TIME_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply rate limiting to POST requests
  if (req.method !== "POST") {
    next();
    return;
  }

  // Get client IP address
  const clientIP = req.ip || "unknown";
  const now = Date.now();

  // Initialize or update rate limit tracking
  const key = clientIP;
  const entry = rateLimits.get(key);

  if (!entry) {
    rateLimits.set(key, { count: 1, windowStart: now });
  } else {
    // Check if we're still within the time window
    if (now - entry.windowStart < TIME_WINDOW_MS) {
      entry.count += 1;

      // If too many requests, reject
      if (entry.count > MAX_REQUESTS) {
        res.status(429).json({ error: "Too Many Requests" });
        return;
      }
    } else {
      // Reset counter and window start
      entry.count = 1;
      entry.windowStart = now;
    }
  }

  next();
}

import { useEffect, useState } from "react";

interface SavingsGoal {
  id: string;
  title: string;
  targetAmount: number;
  currentAmount: number;
  deadline: string;
}

export function Dashboard() {
  const [goals, setGoals] = useState<SavingsGoal[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchGoals = async () => {
      try {
        const response = await fetch('/api/savings-goals');
        if (!response.ok) {
          throw new Error('Failed to fetch goals');
        }
        const data = await response.json();
        setGoals(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchGoals();
  }, []);

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (goals.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No savings goals found.</div>;
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
