import { useEffect, useState } from "react";

interface Goal {
  id: number;
  title: string;
  targetAmount: number;
  currentAmount: number;
  deadline: string;
}

export function GoalsList() {
  const [goals, setGoals] = useState<Goal[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchGoals = async () => {
      try {
        const response = await fetch('/api/goals');
        if (!response.ok) {
          throw new Error('Failed to fetch goals');
        }
        const data = await response.json();
        setGoals(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchGoals();
  }, []);

  const filteredGoals = goals.filter(goal => 
    goal.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusColor = (current: number, target: number) => {
    if (current >= target) return 'green';
    if (current >= target * 0.7) return 'orange';
    return 'red';
  };

  const getStatusText = (current: number, target: number) => {
    if (current >= target) return 'Completed';
    if (current >= target * 0.7) return 'On track';
    return 'Behind schedule';
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Savings Goals</h1>

      <input
        type="text"
        placeholder="Search goals..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        style={{
          width: '100%',
          padding: '10px',
          marginBottom: '20px',
          borderRadius: '4px',
          border: '1px solid #ccc'
        }}
      />

      {filteredGoals.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No goals found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {filteredGoals.map(goal => (
            <div 
              key={goal.id} 
              style={{
                border: '1px solid #ddd',
                borderRadius: '8px',
                padding: '15px',
                backgroundColor: '#f9f9f9'
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <h3 style={{ margin: '0' }}>{goal.title}</h3>
                <span 
                  style={{
                    padding: '4px 8px',
                    borderRadius: '4px',
                    color: 'white',
                    fontWeight: 'bold',
                    backgroundColor: getStatusColor(goal.currentAmount, goal.targetAmount)
                  }}
                >
                  {getStatusText(goal.currentAmount, goal.targetAmount)}
                </span>
              </div>

              <div style={{ marginTop: '10px' }}>
                <p style={{ margin: '5px 0' }}>
                  Target: ${goal.targetAmount.toFixed(2)}
                </p>
                <p style={{ margin: '5px 0' }}>
                  Current: ${goal.currentAmount.toFixed(2)}
                </p>
                <p style={{ margin: '5px 0' }}>
                  Deadline: {new Date(goal.deadline).toLocaleDateString()}
                </p>
                <div style={{ marginTop: '10px' }}>
                  <div style={{ height: '8px', backgroundColor: '#eee', borderRadius: '4px', overflow: 'hidden' }}>
                    <div 
                      style={{
                        width: `${Math.min(100, (goal.currentAmount / goal.targetAmount) * 100)}%`,
                        height: '100%',
                        backgroundColor: getStatusColor(goal.currentAmount, goal.targetAmount),
                        borderRadius: '4px'
                      }}
                    />
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { FC, useState } from "react";

interface GoalFormData {
  name: string;
  targetAmount: string;
  currentAmount: string;
  deadline: string;
  category: string;
}

interface GoalFormProps {
  initialData?: GoalFormData;
  onSubmit: (data: GoalFormData) => void;
  onCancel: () => void;
}

export function GoalForm({ initialData, onSubmit, onCancel }: GoalFormProps) {
  const [formData, setFormData] = useState<GoalFormData>(
    initialData || {
      name: "",
      targetAmount: "",
      currentAmount: "",
      deadline: "",
      category: "",
