            Target Amount ($)
          </label>
          <input
            type="number"
            id="targetAmount"
            name="targetAmount"
            value={formData.targetAmount}
            onChange={handleChange}
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc",
            }}
            required
            min="0"
            step="0.01"
          />
        </div>

        <div>
          <label htmlFor="currentAmount" style={{ display: "block", marginBottom: "5px" }}>
            Current Amount ($)
          </label>
          <input
            type="number"
            id="currentAmount"
            name="currentAmount"
            value={formData.currentAmount}
            onChange={handleChange}
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc",
            }}
            required
            min="0"
            step="0.01"
          />
        </div>

        <div>
          <label htmlFor="deadline" style={{ display: "block", marginBottom: "5px" }}>
            Deadline
          </label>
          <input
            type="date"
            id="deadline"
            name="deadline"
            value={formData.deadline}
            onChange={handleChange}
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc",
            }}
            required
          />
        </div>

        <div>
          <label htmlFor="category" style={{ display: "block", marginBottom: "5px" }}>
            Category
          </label>
          <select
            id="category"
            name="category"
            value={formData.category}
            onChange={handleChange}
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc",
            }}
            required
          >
            <option value="">Select a category</option>
            <option value="vacation">Vacation</option>
            <option value="emergency">Emergency Fund</option>
            <option value="home">Home Improvement</option>
            <option value="education">Education</option>
            <option value="other">Other</option>
          </select>
        </div>

        <div style={{ display: "flex", gap: "10px", marginTop: "10px" }}>
