import { useEffect, useState } from "react";

interface MeetingRoom {
  id: number;
  name: string;
  capacity: number;
  equipment: string[];
}

interface Booking {
  id: number;
  roomId: number;
  roomName: string;
  title: string;
  startDate: string;
  endDate: string;
  startTime: string;
  endTime: string;
  organizer: string;
}

export function AdminPanel() {
  const [meetingRooms, setMeetingRooms] = useState<MeetingRoom[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Fetch meeting rooms
        const roomsResponse = await fetch('/api/rooms');
        if (!roomsResponse.ok) throw new Error('Failed to fetch rooms');
        const roomsData = await roomsResponse.json();
        setMeetingRooms(roomsData);

        // Fetch bookings
        const bookingsResponse = await fetch('/api/bookings');
        if (!bookingsResponse.ok) throw new Error('Failed to fetch bookings');
        const bookingsData = await bookingsResponse.json();
        setBookings(bookingsData);

        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Admin Panel</h1>

      <section style={{ marginBottom: '40px' }}>
        <h2>Meeting Rooms</h2>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '20px' }}>
          {meetingRooms.length > 0 ? (
            meetingRooms.map(room => (
              <div key={room.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px', width: '250px' }}>
                <h3>{room.name}</h3>
                <p>Capacity: {room.capacity}</p>
                <p>Equipment: {room.equipment.join(', ')}</p>
              </div>
            ))
          ) : (
            <p>No meeting rooms found.</p>
          )}
        </div>
      </section>

      <section style={{ marginBottom: '40px' }}>
        <h2>All Bookings</h2>
        {bookings.length > 0 ? (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '1px solid #ccc' }}>
                <th style={{ padding: '10px', textAlign: 'left' }}>Title</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>Room</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>Date</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>Time</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>Organizer</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map(booking => (
                <tr key={booking.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '10px' }}>{booking.title}</td>
                  <td style={{ padding: '10px' }}>{booking.roomName}</td>
                  <td style={{ padding: '10px' }}>{new Date(booking.startDate).toLocaleDateString()}</td>
                  <td style={{ padding: '10px' }}>{booking.startTime} - {booking.endTime}</td>
                  <td style={{ padding: '10px' }}>{booking.organizer}</td>
                </tr>
              ))}
            </tbody>
