import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "JWT secret not configured" });
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Simple JWT structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Token verification failed" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce authorization on POST, PUT, DELETE requests
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7);

  if (!process.env.JWT_SECRET) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  try {
    // Simple token validation - in a real app, you'd decode and verify JWT properly
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      return res.status(401).json({ error: "Invalid token format" });
    }

    const expectedSignature = createHmac("sha256", process.env.JWT_SECRET)
      .update(payload)
      .digest("base64");

    const expectedBuffer = Buffer.from(expectedSignature, "base64");
    const actualBuffer = Buffer.from(signature, "base64");

    if (actualBuffer.length !== expectedBuffer.length || !timingSafeEqual(actualBuffer, expectedBuffer)) {
      return res.status(401).json({ error: "Invalid token" });
    }

    // In a real implementation, we would decode the payload to get user info
    // For now, we'll just assume valid token and proceed
    next();
  } catch (err) {
    return res.status(401).json({ error: "Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, PATCH requests that contain a body
  if (!['POST', 'PUT', 'PATCH'].includes(req.method) || !req.body) {
    return next();
  }

  // Sanitize and validate input fields
  const sanitizedBody = sanitizeAndValidateInput(req.body);

  // Replace original body with sanitized version
  req.body = sanitizedBody;

  next();
}

function sanitizeAndValidateInput(input: Record<string, any>): Record<string, any> {
  const sanitized: Record<string, any> = {};

  for (const [key, value] of Object.entries(input)) {
    if (typeof value === 'string') {
      // Remove potential XSS attack vectors
      const sanitizedValue = value
        .replace(/<script[^>]*>.*?<\/script>/gi, '')
        .replace(/<iframe[^>]*>.*?<\/iframe>/gi, '')
        .replace(/<object[^>]*>.*?<\/object>/gi, '')
        .replace(/<embed[^>]*>.*?<\/embed>/gi, '')
        .replace(/<applet[^>]*>.*?<\/applet>/gi, '')
        .replace(/on\w+\s*=\s*[^\s>]+/gi, '')
        .replace(/javascript:/gi, '')
        .replace(/vbscript:/gi, '');

      // Check for SQL injection patterns
      if (/ (union|select|insert|update|delete|drop|create|alter|exec|execute) /i.test(sanitizedValue)) {
        throw new Error('Invalid input: potential SQL injection detected');
      }

      sanitized[key] = sanitizedValue;
    } else if (Array.isArray(value)) {
      sanitized[key] = value.map(item => {
        if (typeof item === 'string') {
          return item
            .replace(/<script[^>]*>.*?<\/script>/gi, '')
            .replace(/<iframe[^>]*>.*?<\/iframe>/gi, '')
            .replace(/<object[^>]*>.*?<\/object>/gi, '')
            .replace(/<embed[^>]*>.*?<\/embed>/gi, '')
            .replace(/<applet[^>]*>.*?<\/applet>/gi, '')
            .replace(/on\w+\s*=\s*[^\s>]+/gi, '')
            .replace(/javascript:/gi, '')
            .replace(/vbscript:/gi, '');
        }
        return item;
      });
    } else {
      sanitized[key] = value;
    }
  }

  return sanitized;
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const MAX_REQUESTS = 100;
const TIME_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

interface RateLimitStore {
  [key: string]: {
    count: number;
    resetTime: number;
  };
}

const store: RateLimitStore = {};

function getRateLimitKey(req: Request): string {
  const ip = req.ip || req.connection.remoteAddress || "unknown";
  return `rate_limit:${ip}`;
}

function isRateLimited(key: string): { limited: boolean; resetTime?: number } {
  const now = Date.now();
  const entry = store[key];

  if (!entry) {
    return { limited: false };
  }

  if (now > entry.resetTime) {
    delete store[key];
    return { limited: false };
  }

  return { 
    limited: entry.count >= MAX_REQUESTS, 
    resetTime: entry.resetTime 
  };
}

function incrementRateLimit(key: string): void {
  const now = Date.now();
  const entry = store[key] || { count: 0, resetTime: now + TIME_WINDOW_MS };
  entry.count += 1;
  store[key] = entry;
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply rate limiting to API routes
  if (!req.path.startsWith("/api/")) {
    return next();
  }

  const key = getRateLimitKey(req);
  const { limited, resetTime } = isRateLimited(key);

  if (limited) {
    res.status(429).json({
      error: "Too Many Requests",
      message: "You have exceeded the rate limit. Please try again later."
    });
    return;
  }

  incrementRateLimit(key);
  next();
}

