        </div>
      </div>

      <h2 style={{ marginBottom: "20px" }}>Answers ({question.answers.length})</h2>

      {question.answers.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px", color: "#666" }}>No answers yet. Be the first to answer!</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
