  const index = mockPets.findIndex(pet => pet.id === id);
  if (index === -1) return null;
  mockPets[index] = { ...mockPets[index], ...petData };
  return mockPets[index];
};

const deletePet = (id: number) => {
  const index = mockPets.findIndex(pet => pet.id === id);
  if (index === -1) return false;
  mockPets.splice(index, 1);
  return true;
};

