import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "JWT secret not configured" });
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Token verification failed" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC logic to protected routes
  const protectedPaths = [/^\/pets\/.+$/, /^\/reminders\/.+$/];
  const isProtectedPath = protectedPaths.some(path => path.test(req.path));

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role
  const userRole = req.headers["x-user-role"] as string | undefined;
  const userId = req.headers["x-user-id"] as string | undefined;

  if (!userRole || !userId) {
    res.status(401).json({ error: "Unauthorized: Missing role or user ID" });
    return;
  }

  // Extract petId or reminderId from URL params
  const petId = req.params.petId;
  const reminderId = req.params.reminderId;

  // Validate that the user owns the resource they're trying to access
  if (petId && userRole !== "admin") {
    // For non-admins, ensure petId matches user's pets
    // This is a simplified check - in reality, you'd query the database
    // to verify ownership
    const expectedPetId = `user-${userId}-pet`;
    if (petId !== expectedPetId) {
      res.status(403).json({ error: "Forbidden: Access denied to pet" });
      return;
    }
  }

  if (reminderId && userRole !== "admin") {
    // For non-admins, ensure reminderId matches user's reminders
    const expectedReminderId = `user-${userId}-reminder`;
    if (reminderId !== expectedReminderId) {
      res.status(403).json({ error: "Forbidden: Access denied to reminder" });
      return;
    }
  }

  // If we reach here, the user has proper permissions
  next();
}

