// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Find user
  const user = users.find(u => u.email === email && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  const token = generateToken();
  return res.json({ token, user: { id: user.id, email, role: user.role } });
});

// Middleware to verify token (mock implementation)
const authenticate = (req: Request, res: Response, next: Function) => {
  // In a real app, verify JWT token here
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  // Mock user ID assignment
  (req as any).userId = "1"; // Mock user ID
  next();
};

// Middleware to check role (mock implementation)
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    const user = users.find(u => u.id === (req as any).userId);
    if (!user || !roles.includes(user.role)) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }
    next();
  };
};

