  const userId = (req as any).userId;
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({ id: user.id, email: user.email, role: user.role });
});

// Update user profile endpoint
