import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  getAllEntries: async () => {
    // Simulate DB fetch
    return [
      { id: 1, title: "My First Day", content: "Today was great!", date: "2023-01-01" },
      { id: 2, title: "Another Entry", content: "More thoughts here.", date: "2023-01-02" }
    ];
  },
  getEntryById: async (id: number) => {
    // Simulate DB fetch
    const entries = await mockDatabase.getAllEntries();
    return entries.find(entry => entry.id === id) || null;
  },
  createEntry: async (entry: { title: string; content: string; date: string }) => {
    // Simulate DB insert
    const entries = await mockDatabase.getAllEntries();
    const newId = Math.max(...entries.map(e => e.id), 0) + 1;
    const newEntry = { id: newId, ...entry };
    return newEntry;
  },
  updateEntry: async (id: number, updates: Partial<{ title: string; content: string; date: string }>) => {
    // Simulate DB update
    const entries = await mockDatabase.getAllEntries();
    const index = entries.findIndex(entry => entry.id === id);
    if (index === -1) return null;
    entries[index] = { ...entries[index], ...updates };
    return entries[index];
  },
  deleteEntry: async (id: number) => {
    // Simulate DB delete
    const entries = await mockDatabase.getAllEntries();
    const index = entries.findIndex(entry => entry.id === id);
    if (index === -1) return false;
    entries.splice(index, 1);
    return true;
  },
  searchEntries: async (query: string) => {
    // Simulate DB search
    const entries = await mockDatabase.getAllEntries();
    return entries.filter(entry => 
      entry.title.toLowerCase().includes(query.toLowerCase()) ||
      entry.content.toLowerCase().includes(query.toLowerCase())
    );
  }
};

