  createCustomer(customerData: Omit<Customer, 'id'>) {
    const newCustomer = {
      id: this.customers.length > 0 ? Math.max(...this.customers.map(c => c.id)) + 1 : 1,
      ...customerData
    };
    this.customers.push(newCustomer);
    return newCustomer;
  },

  updateCustomer(id: number, customerData: Partial<Customer>) {
    const index = this.customers.findIndex(customer => customer.id === id);
    if (index === -1) return null;
    this.customers[index] = { ...this.customers[index], ...customerData };
    return this.customers[index];
  },

  deleteCustomer(id: number) {
    const index = this.customers.findIndex(customer => customer.id === id);
    if (index === -1) return false;
    this.customers.splice(index, 1);
    return true;
  }
};

