import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to POST, PUT, DELETE requests
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Check if the request path requires role-based access control
  const protectedPaths = ["/orders", "/staff", "/inventory"];
  const isProtectedPath = protectedPaths.some(path => req.path.startsWith(path));

  if (!isProtectedPath) {
    next();
    return;
  }

  // Get authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  try {
    // For demonstration purposes, we'll just check if it has the right format
    // In a real implementation, you'd decode the JWT and verify its signature
    const [header, payload, signature] = token.split('.');

    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac('sha256', secret)
      .update(`${header}.${payload}`)
      .digest('base64url');

    const signatureBuffer = Buffer.from(signature, 'base64url');
    const expectedSignatureBuffer = Buffer.from(expectedSignature, 'base64url');

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Decode payload to get user role
    const payloadStr = Buffer.from(payload, 'base64url').toString('utf-8');
    const payloadObj = JSON.parse(payloadStr);

    const userRole = payloadObj.role;
    if (!userRole) {
      res.status(403).json({ error: "Forbidden: User role not specified" });
      return;
    }

    // Define required roles for different actions
    const requiredRoles = {
      "/orders": ["admin", "manager"],
      "/staff": ["admin"],
      "/inventory": ["admin", "manager"]
    };

    let requiredRole = "user"; // default role
    for (const [path, roles] of Object.entries(requiredRoles)) {
      if (req.path.startsWith(path)) {
        requiredRole = roles[0]; // Use first role as example
        break;
      }
    }

    // Check if user has sufficient role
    const allowedRoles = ["admin", "manager", "user"];
    const userRoleIndex = allowedRoles.indexOf(userRole);
    const requiredRoleIndex = allowedRoles.indexOf(requiredRole);

    if (userRoleIndex < requiredRoleIndex) {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

