import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  {
    id: 1,
    username: "admin",
    password: "password123",
    role: "admin"
  },
  {
    id: 2,
    username: "member",
    password: "memberpass",
    role: "member"
  }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string }>();

// User registration
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role: role || "member"
  };

  users.push(newUser);

  return res.status(201).json(newUser);
});

// User login
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = Math.random().toString(36).substring(2, 15);
  sessions.set(token, { userId: user.id, role: user.role });

  return res.json({ token, role: user.role });
});

// Session validation middleware
const authenticate = (req: Request, res: Response, next: Function) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "No authorization token provided" });
  }

  const session = sessions.get(token);
  if (!session) {
    return res.status(401).json({ error: "Invalid or expired session" });
  }

  (req as any).userId = session.userId;
  (req as any).role = session.role;
  next();
};

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    const role = (req as any).role;
    if (!roles.includes(role)) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }
    next();
  };
};

// Get user profile (protected route)
router.get("/profile", authenticate, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({
    id: user.id,
    username: user.username,
    role: user.role
  });
});

// Logout (clear session)
router.post("/logout", authenticate, (req: Request, res: Response) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (token) {
    sessions.delete(token);
  }

  return res.json({ message: "Logged out successfully" });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would be actual database calls
const mockDatabase = {
  getAllTools: async () => [
    { id: 1, name: "Drill", category: "Power Tools", available: true },
    { id: 2, name: "Hammer", category: "Hand Tools", available: false }
  ],
  getToolById: async (id: number) => {
    const tools = await mockDatabase.getAllTools();
    return tools.find(tool => tool.id === id) || null;
  },
  createTool: async (toolData: { name: string; category: string; available: boolean }) => {
    const tools = await mockDatabase.getAllTools();
    const newId = tools.length > 0 ? Math.max(...tools.map(t => t.id)) + 1 : 1;
    const newTool = { id: newId, ...toolData };
    return newTool;
  },
  updateTool: async (id: number, toolData: Partial<{ name: string; category: string; available: boolean }>) => {
    const tools = await mockDatabase.getAllTools();
    const index = tools.findIndex(tool => tool.id === id);
    if (index === -1) return null;
    tools[index] = { ...tools[index], ...toolData };
    return tools[index];
  },
  deleteTool: async (id: number) => {
    const tools = await mockDatabase.getAllTools();
    const index = tools.findIndex(tool => tool.id === id);
    if (index === -1) return false;
    tools.splice(index, 1);
    return true;
  }
};

// GET /tools - List all tools
