// Mock data structures to simulate database operations
const loans = [] as Array<{
  id: number;
  toolId: number;
  borrowerId: number;
  borrowDate: Date;
  dueDate: Date;
  returnDate?: Date;
  fineAmount?: number;
}>;

const tools = [] as Array<{
  id: number;
  name: string;
  description: string;
  isAvailable: boolean;
}>;

const borrowers = [] as Array<{
  id: number;
  name: string;
  email: string;
}>;

// Helper function to calculate fines
const calculateFine = (dueDate: Date, returnDate: Date): number => {
  const due = new Date(dueDate);
  const returned = new Date(returnDate);
  const diffTime = returned.getTime() - due.getTime();
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  return diffDays > 0 ? diffDays * 0.5 : 0;
};

// GET /loans - List all loans
router.get("/loans", (req: Request, res: Response) => {
  res.json(loans);
});

// GET /loans/:id - Get a specific loan by ID
router.get("/loans/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const loan = loans.find(l => l.id === id);

  if (!loan) {
    return res.status(404).json({ error: "Loan not found" });
  }

  res.json(loan);
});

// POST /loans - Create a new loan
router.post("/loans", (req: Request, res: Response) => {
  const { toolId, borrowerId } = req.body;

  if (!toolId || !borrowerId) {
    return res.status(400).json({ error: "Tool ID and Borrower ID are required" });
  }

  const tool = tools.find(t => t.id === toolId);
  const borrower = borrowers.find(b => b.id === borrowerId);

  if (!tool || !borrower) {
    return res.status(400).json({ error: "Invalid tool or borrower" });
  }

  if (!tool.isAvailable) {
    return res.status(400).json({ error: "Tool is not available" });
  }

  const borrowDate = new Date();
  const dueDate = new Date(borrowDate);
  dueDate.setDate(dueDate.getDate() + 14); // 2 weeks

  const newLoan = {
    id: loans.length + 1,
    toolId,
    borrowerId,
    borrowDate,
    dueDate
  };

  loans.push(newLoan);
  tool.isAvailable = false;

  res.status(201).json(newLoan);
});

// PUT /loans/:id/return - Return a loan
router.put("/loans/:id/return", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const loan = loans.find(l => l.id === id);

  if (!loan) {
    return res.status(404).json({ error: "Loan not found" });
  }

  const returnDate = new Date();
  const fineAmount = calculateFine(loan.dueDate, returnDate);

  loan.returnDate = returnDate;
  loan.fineAmount = fineAmount;

  const tool = tools.find(t => t.id === loan.toolId);
  if (tool) {
    tool.isAvailable = true;
  }

  res.json(loan);
});

// GET /loans/:id/fine - Calculate fine for a loan
router.get("/loans/:id/fine", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const loan = loans.find(l => l.id === id);

  if (!loan) {
    return res.status(404).json({ error: "Loan not found" });
  }

  if (!loan.returnDate) {
    return res.status(400).json({ error: "Loan has not been returned yet" });
  }

  const fine = calculateFine(loan.dueDate, loan.returnDate);

  res.json({ fine });
});

