import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-POST requests and non-borrow routes
  if (req.method !== "POST" || !req.path.startsWith("/borrow")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token structure: base64(userRole|timestamp)
  try {
    const [userRole, timestamp] = Buffer.from(token, "base64").toString().split("|");

    // Verify role is valid
    if (userRole !== "member" && userRole !== "staff") {
      res.status(403).json({ error: "Forbidden" });
      return;
    }

    // Check if user has proper access
    if (userRole === "member" && req.path.startsWith("/borrow")) {
      // Members can only borrow tools
      next();
      return;
    } else if (userRole === "staff" && req.path.startsWith("/inventory")) {
      // Staff can manage inventory
      next();
      return;
    }

    res.status(403).json({ error: "Forbidden" });
  } catch (err) {
    res.status(401).json({ error: "Unauthorized" });
  }
}

