  const [categoryFilter, setCategoryFilter] = useState("all");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchTools = async () => {
      try {
        const response = await fetch("/api/tools");
        if (!response.ok) {
          throw new Error(`Failed to fetch tools: ${response.status}`);
        }
        const data = await response.json();
        setTools(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchTools();
  }, []);

  const filteredTools = tools.filter(tool => {
    const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          tool.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = categoryFilter === "all" || tool.category === categoryFilter;
    return matchesSearch && matchesCategory;
  });

  const categories = [...new Set(tools.map(tool => tool.category))];

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Available Tools</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search tools..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={categoryFilter}
          onChange={(e) => setCategoryFilter(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Categories</option>
          {categories.map(category => (
            <option key={category} value={category}>{category}</option>
          ))}
        </select>
      </div>

      {filteredTools.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No tools found.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
          {filteredTools.map(tool => (
            <div 
              key={tool.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                width: "100%", 
                maxWidth: "300px",
                backgroundColor: tool.available ? "#f8f9fa" : "#e9ecef"
              }}
            >
              <h3 style={{ margin: "0 0 10px 0" }}>{tool.name}</h3>
              <p style={{ margin: "0 0 10px 0", color: "#666" }}>{tool.description}</p>
              <p style={{ margin: "0 0 10px 0", color: "#666" }}>Category: {tool.category}</p>
              <p style={{ margin: "0", color: tool.available ? "green" : "red" }}>
                {tool.available ? "Available" : "Not Available"}
              </p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

