  const [history, setHistory] = useState<BorrowingHistory[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchToolDetails = async () => {
      try {
        const response = await fetch(`/api/tools/${toolId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch tool details: ${response.status}`);
        }
        const toolData: Tool = await response.json();
        setTool(toolData);

        const historyResponse = await fetch(`/api/tools/${toolId}/borrowing-history`);
        if (!historyResponse.ok) {
          throw new Error(`Failed to fetch borrowing history: ${historyResponse.status}`);
        }
        const historyData: BorrowingHistory[] = await historyResponse.json();
        setHistory(historyData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchToolDetails();
  }, [toolId]);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
