export function PrayerTimesPage() {
  const [prayerTimes, setPrayerTimes] = useState<PrayerTime[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchPrayerTimes = async () => {
      try {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mock data for demonstration
        const mockPrayerTimes: PrayerTime[] = [
          { id: "1", name: "Fajr", time: "05:30 AM", countdown: 120 },
          { id: "2", name: "Dhuhr", time: "01:15 PM", countdown: 90 },
          { id: "3", name: "Asr", time: "04:45 PM", countdown: 60 },
          { id: "4", name: "Maghrib", time: "07:00 PM", countdown: 30 },
          { id: "5", name: "Isha", time: "08:30 PM", countdown: 0 },
        ];

        setPrayerTimes(mockPrayerTimes);
        setLoading(false);
      } catch (err) {
        setError("Failed to load prayer times");
        setLoading(false);
      }
    };

    fetchPrayerTimes();
  }, []);

  // Update countdowns every minute
  useEffect(() => {
    const interval = setInterval(() => {
      setPrayerTimes(prev => 
        prev.map(prayer => ({
          ...prayer,
          countdown: Math.max(0, prayer.countdown - 1)
        }))
      );
    }, 60000); // 60 seconds

    return () => clearInterval(interval);
  }, []);

  const formatCountdown = (minutes: number): string => {
    if (minutes === 0) return "Now";

    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;

    if (hours > 0) {
      return `${hours}h ${mins}m`;
    }
    return `${mins}m`;
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: "600px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
    }}>
      <h1 style={{ textAlign: "center", marginBottom: "30px" }}>Prayer Times</h1>

