        <p style={{ textAlign: "center", color: "#666" }}>No prayer times available</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {prayerTimes.map(prayer => (
            <div 
              key={prayer.id}
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                backgroundColor: "#f9f9f9"
              }}
            >
              <div>
                <h3 style={{ margin: "0 0 5px 0", fontSize: "1.2em" }}>{prayer.name}</h3>
                <p style={{ margin: "0", color: "#666" }}>{prayer.time}</p>
              </div>
              <div style={{ textAlign: "right" }}>
                <div style={{ fontSize: "1.1em", fontWeight: "bold" }}>
