                  <div>
                    <strong>{app.patientName}</strong> - {app.testName}
                    <br />
                    <small>{app.appointmentDate}</small>
                  </div>
                  <select 
                    value={app.status}
                    onChange={(e) => handleStatusChange(app.id, e.target.value as any)}
                    style={{ padding: "5px", borderRadius: "4px" }}
                  >
                    <option value="scheduled">Scheduled</option>
                    <option value="completed">Completed</option>
                    <option value="cancelled">Cancelled</option>
                  </select>
                </div>

                {app.status === "scheduled" && (
                  <div style={{ marginTop: "10px" }}>
                    <input 
                      type="text" 
                      placeholder="Enter test result"
                      style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          handleAddResult(app.id, (e.target as HTMLInputElement).value);
                          (e.target as HTMLInputElement).value = "";
                        }
                      }}
                    />
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </section>

      <section>
        <h2>Test Results</h2>
        {testResults.length === 0 ? (
          <p>No test results found.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {testResults.map(result => (
              <div key={result.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
                <div style={{ display: "flex", justifyContent: "space-between" }}>
                  <div>
                    <strong>{result.patientName}</strong> - {result.testName}
                    <br />
                    <small>{result.reportDate}</small>
                  </div>
                  <span style={{ backgroundColor: "#e0e0e0", padding: "4px 8px", borderRadius: "4px" }}>
                    {result.result}
                  </span>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected routes
  if (req.method === "GET" && req.path === "/") {
    return next();
  }

  // Check if the request has an authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  // Basic token format validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    return res.status(401).json({ error: "Invalid token format" });
  }

  try {
    // Decode the payload (base64url)
    const payload = Buffer.from(parts[1], "base64").toString("utf-8");
    const decodedPayload = JSON.parse(payload);

    // Verify the signature
    const signature = parts[2];
    const expectedSignature = createHmac("sha256", secret)
      .update(`${parts[0]}.${parts[1]}`)
      .digest("base64url");

    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");

    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      return res.status(401).json({ error: "Invalid token" });
    }

    // Check role and permissions
    const userRole = decodedPayload.role;
    const userId = decodedPayload.userId;

    if (!userRole) {
      return res.status(401).json({ error: "Invalid token" });
    }

    // For staff, allow access to all resources
    if (userRole === "staff") {
      req.user = { role: "staff" };
      return next();
    }

    // For patients, check if they're accessing their own data
    if (userRole === "patient") {
      // Allow access to patient's own reports and bookings
      if (
        req.path.includes(`/patients/${userId}/`) ||
        req.path.includes(`/reports/${userId}/`) ||
        req.path.includes(`/bookings/${userId}/`)
      ) {
        req.user = { role: "patient", id: userId };
        return next();
      }

      // Deny access to other patients' data
      return res.status(403).json({ error: "Access denied" });
    }

    // Unknown role
    return res.status(401).json({ error: "Invalid token" });
  } catch (err) {
    return res.status(401).json({ error: "Invalid token" });
  }
}

