import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes and methods
  const allowedPaths = ["/api/stock", "/api/distribution"];
  const allowedMethods = ["POST", "PUT", "DELETE"];

  if (!allowedPaths.some(path => req.path.startsWith(path)) || !allowedMethods.includes(req.method)) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Simple token validation - in a real app, you'd decode and verify the JWT properly
    const [payload, signature] = token.split(".");

    if (!payload || !signature) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Recreate the signature for verification
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // For demo purposes, we'll assume valid tokens have a role in payload
    // In a real implementation, you'd parse the JWT payload
    const decodedPayload = Buffer.from(payload, "base64url").toString();
    const payloadObj = JSON.parse(decodedPayload);

    const userRole = payloadObj.role;

    if (!userRole) {
      res.status(403).json({ error: "Forbidden: Role not specified in token" });
      return;
    }

    // Admin can access everything, staff can only access certain endpoints
    if (userRole === "admin") {
      next();
      return;
    }

    if (userRole === "staff") {
      // Staff can only access POST and PUT requests to stock and distribution
      if (req.method === "POST" || req.method === "PUT") {
        next();
        return;
      }

      // Staff cannot DELETE or access other restricted endpoints
      res.status(403).json({ error: "Forbidden: Staff members cannot perform this action" });
      return;
    }

    // Unknown role
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

interface Session {
  userId: string;
  createdAt: number;
}

function isValidToken(token: string): boolean {
  if (!process.env.JWT_SECRET) {
    return false;
  }

  const parts = token.split(".");
  if (parts.length !== 3) {
    return false;
  }

  const [header, payload, signature] = parts;

  try {
    const expectedSignature = createHmac("sha256", process.env.JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");

    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

function parsePayload(payload: string): { userId: string; iat: number } | null {
  try {
    const decoded = Buffer.from(payload, "base64url").toString("utf-8");
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  const payload = parsePayload(token.split(".")[1]);
  if (!payload) {
    res.status(401).json({ error: "Invalid token payload" });
    return;
  }

  if (!payload.userId) {
    res.status(401).json({ error: "Invalid token payload" });
    return;
  }

  // Simulate session storage lookup
  const session: Session = {
    userId: payload.userId,
    createdAt: payload.iat * 1000,
  };

  if (Date.now() - session.createdAt > SESSION_TIMEOUT) {
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // Store session data in request object for downstream middleware/routes
  (req as any).session = session;
  next();
}

