    date: "",
    recipientName: "",
    recipientAddress: "",
    items: [{ itemId: 0, quantity: 0 }] as { itemId: number; quantity: number }[],
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [distributionsRes, itemsRes] = await Promise.all([
          fetch("/api/distributions"),
          fetch("/api/items"),
        ]);

        if (!distributionsRes.ok || !itemsRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const distributionsData = await distributionsRes.json();
        const itemsData = await itemsRes.json();

        setDistributions(distributionsData);
        setItems(itemsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleItemChange = (index: number, field: string, value: string | number) => {
    const updatedItems = [...formData.items];
    updatedItems[index] = { ...updatedItems[index], [field]: value };
    setFormData({
      ...formData,
      items: updatedItems,
    });
  };

  const addItemField = () => {
    setFormData({
      ...formData,
      items: [...formData.items, { itemId: 0, quantity: 0 }],
    });
  };

  const removeItemField = (index: number) => {
    const updatedItems = formData.items.filter((_, i) => i !== index);
    setFormData({
      ...formData,
      items: updatedItems,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const res = await fetch("/api/distributions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (!res.ok) {
        throw new Error("Failed to add distribution");
      }

      // Refresh data
      const distributionsRes = await fetch("/api/distributions");
      const distributionsData = await distributionsRes.json();
      setDistributions(distributionsData);

      // Reset form
      setFormData({
        date: "",
        recipientName: "",
        recipientAddress: "",
        items: [{ itemId: 0, quantity: 0 }],
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Distribution Register</h1>

      <h2>Add New Distribution</h2>
      <form onSubmit={handleSubmit} style={{ marginBottom: "40px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label>Date:</label>
          <input
            type="date"
            name="date"
            value={formData.date}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label>Recipient Name:</label>
          <input
            type="text"
            name="recipientName"
            value={formData.recipientName}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label>Recipient Address:</label>
          <textarea
            name="recipientAddress"
            value={formData.recipientAddress}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <h3>Distributed Items</h3>
        {formData.items.map((item, index) => (
          <div key={index} style={{ display: "flex", gap: "10px", marginBottom: "15px", flexWrap: "wrap" }}>
            <select
              value={item.itemId}
              onChange={(e) => handleItemChange(index, "itemId", Number(e.target.value))}
              style={{ flex: 1, minWidth: "120px", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              required
            >
              <option value={0}>Select Item</option>
              {items.map((i) => (
                <option key={i.id} value={i.id}>
                  {i.name}
                </option>
              ))}
            </select>
            <input
              type="number"
              min="0"
              value={item.quantity}
              onChange={(e) => handleItemChange(index, "quantity", Number(e.target.value))}
              style={{ flex: 1, minWidth: "120px", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              required
            />
            <button
              type="button"
              onClick={() => removeItemField(index)}
              style={{ padding: "8px 12px", backgroundColor: "#ff4d4d", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
            >
              Remove
            </button>
          </div>
        ))}
        <button
          type="button"
          onClick={addItemField}
          style={{ padding: "8px 12px", backgroundColor: "#4CAF50", color: "white", border: "none", borderRadius: "4px", cursor: "pointer", marginBottom: "15px" }}
        >
          Add Item
        </button>
        <br />
        <button
          type="submit"
          style={{ padding: "10px 20px", backgroundColor: "#2196F3", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
        >
          Record Distribution
        </button>
      </form>

      <h2>Recent Distributions</h2>
      {distributions.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No distributions recorded yet.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {distributions.map((dist) => (
            <div
              key={dist.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "15px",
                backgroundColor: "#f9f9f9",
              }}
            >
              <h3>{dist.recipientName}</h3>
              <p><strong>Date:</strong> {new Date(dist.date).toLocaleDateString()}</p>
              <p><strong>Address:</strong> {dist.recipientAddress}</p>
              <h4>Items Distributed:</h4>
              <ul>
                {dist.items.map((item, idx) => (
                  <li key={idx}>{item.itemName}: {item.quantity}</li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

interface Session {
  userId: string;
  createdAt: number;
}

function isValidToken(token: string): boolean {
  if (!process.env.JWT_SECRET) {
    return false;
  }

  const parts = token.split(".");
  if (parts.length !== 3) {
    return false;
  }

  const [header, payload, signature] = parts;

  try {
    const expectedSignature = createHmac("sha256", process.env.JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");

    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

function parsePayload(payload: string): { userId: string; iat: number } | null {
  try {
    const decoded = Buffer.from(payload, "base64url").toString("utf-8");
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  const payload = parsePayload(token.split(".")[1]);
  if (!payload) {
    res.status(401).json({ error: "Invalid token payload" });
    return;
  }

  if (!payload.userId) {
    res.status(401).json({ error: "Invalid token payload" });
    return;
  }

  // Simulate session storage lookup
  const session: Session = {
    userId: payload.userId,
    createdAt: payload.iat * 1000,
  };

  if (Date.now() - session.createdAt > SESSION_TIMEOUT) {
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // Store session data in request object for downstream middleware/routes
  (req as any).session = session;
  next();
}

