export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce RBAC on protected routes
  const protectedPaths = ["/orders", "/customers"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // Define role requirements for different paths
  const roleRequirements: Record<string, string[]> = {
    "/orders": ["admin", "manager", "staff"],
    "/customers": ["admin", "manager"]
  };

  const pathRoleRequirements = roleRequirements[req.path] || 
    Object.entries(roleRequirements).find(([path]) => 
      req.path.startsWith(path)
    )?.[1] || [];

  if (!pathRoleRequirements.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

