    display: 'flex',
    flexDirection: 'column',
    gap: '10px'
  };

  const orderCardStyle: React.CSSProperties = {
    border: '1px solid #ddd',
    borderRadius: '8px',
    padding: '15px',
    backgroundColor: '#f9f9f9'
  };

  const orderHeaderStyle: React.CSSProperties = {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center'
  };

  const statusBadgeStyle: React.CSSProperties = {
    padding: '4px 8px',
    borderRadius: '4px',
    fontSize: '0.8em'
  };

  const deleteButtonStyle: React.CSSProperties = {
    padding: '4px 8px',
    backgroundColor: '#dc3545',
    color: 'white',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer'
  };

  if (loading) return <div style={containerStyle}>Loading...</div>;
  if (error) return <div style={containerStyle}>Error: {error}</div>;

  return (
    <div style={containerStyle}>
      <h1>Order Tracking</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '20px' }}>
        <h2>Add New Order</h2>
        <input
          type="text"
          name="customerName"
          placeholder="Customer Name"
          value={newOrder.customerName}
          onChange={handleInputChange}
          style={inputStyle}
          required
        />
        <select
          name="status"
          value={newOrder.status}
          onChange={handleInputChange}
          style={selectStyle}
        >
          <option value="pending">Pending</option>
          <option value="in-progress">In Progress</option>
          <option value="completed">Completed</option>
          <option value="cancelled">Cancelled</option>
        </select>

        <h3>Measurements</h3>
        <input
          type="number"
          placeholder="Chest"
          value={newOrder.measurements.chest}
          onChange={(e) => handleMeasurementChange('chest', e.target.value)}
          style={inputStyle}
        />
        <input
          type="number"
          placeholder="Waist"
          value={newOrder.measurements.waist}
          onChange={(e) => handleMeasurementChange('waist', e.target.value)}
          style={inputStyle}
        />
        <input
          type="number"
          placeholder="Hips"
          value={newOrder.measurements.hips}
          onChange={(e) => handleMeasurementChange('hips', e.target.value)}
          style={inputStyle}
        />
        <input
          type="number"
          placeholder="Sleeve Length"
          value={newOrder.measurements.sleeveLength}
          onChange={(e) => handleMeasurementChange('sleeveLength', e.target.value)}
          style={inputStyle}
        />
        <input
          type="number"
          placeholder="Length"
          value={newOrder.measurements.length}
          onChange={(e) => handleMeasurementChange('length', e.target.value)}
          style={inputStyle}
        />

        <button type="submit" style={buttonStyle}>Add Order</button>
      </form>

      <div style={controlsStyle}>
        <input
          type="text"
          placeholder="Search by customer name"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={inputStyle}
        />
        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value as any)}
          style={selectStyle}
        >
          <option value="all">All Statuses</option>
          <option value="pending">Pending</option>
          <option value="in-progress">In Progress</option>
          <option value="completed">Completed</option>
          <option value="cancelled">Cancelled</option>
        </select>
      </div>

      <div style={ordersListStyle}>
        {filteredOrders.length === 0 ? (
          <p>No orders found.</p>
        ) : (
          filteredOrders.map(order => (
            <div key={order.id} style={orderCardStyle}>
              <div style={orderHeaderStyle}>
                <h3>{order.customerName}</h3>
                <span style={{
                  ...statusBadgeStyle,
                  backgroundColor: order.status === 'completed' ? '#28a745' : 
                                order.status === 'in-progress' ? '#ffc107' : 
                                order.status === 'cancelled' ? '#dc3545' : '#17a2b8'
                }}>
                  {order.status}
                </span>
              </div>
              <p><strong>Measurements:</strong></p>
              <ul>
                <li>Chest: {order.measurements.chest}</li>
                <li>Waist: {order.measurements.waist}</li>
                <li>Hips: {order.measurements.hips}</li>
                <li>Sleeve Length: {order.measurements.sleeveLength}</li>
                <li>Length: {order.measurements.length}</li>
              </ul>
              <button 
                onClick={() => handleDelete(order.id)}
                style={deleteButtonStyle}
              >
                Delete
              </button>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

