import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = ["/admin", "/faculty", "/student"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role access
  const userRole = req.headers["x-user-role"] as string | undefined;
  const requiredRole = getRequiredRole(req.path);

  if (!userRole || !hasAccess(userRole, requiredRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

function getRequiredRole(path: string): string {
  if (path.startsWith("/admin")) return "administrator";
  if (path.startsWith("/faculty")) return "faculty";
  if (path.startsWith("/student")) return "student";
  return "guest";
}

function hasAccess(userRole: string, requiredRole: string): boolean {
  const roles = ["student", "faculty", "administrator"];
  const userIndex = roles.indexOf(userRole);
  const requiredIndex = roles.indexOf(requiredRole);

  return userIndex >= requiredIndex;
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to the /upload endpoint
  if (req.method !== "POST" || req.path !== "/upload") {
    next();
    return;
  }

  // Check if file exists in the request
  if (!req.file) {
    res.status(400).json({ error: "No file uploaded" });
    return;
  }

  const allowedTypes = [
    "image/jpeg",
    "image/jpg",
    "image/png",
    "image/gif"
  ];

  const maxSize = 5 * 1024 * 1024; // 5MB in bytes

  // Validate file type
  if (!allowedTypes.includes(req.file.mimetype)) {
    res.status(400).json({ error: "Invalid file type" });
    return;
  }

  // Validate file size
  if (req.file.size > maxSize) {
    res.status(400).json({ error: "File too large" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Extract token from Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7);

  // Verify token signature
  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    // Compare signatures safely
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Token verification failed" });
  }
}

