  const { userId, name } = req.body;

  if (!userId || !name) {
    return res.status(400).json({ error: "User ID and name are required" });
  }

  const newParticipant = {
    id: nextParticipantId++,
    competitionId,
    userId,
    name,
    steps: 0,
    createdAt: new Date().toISOString(),
  };

  participants.set(newParticipant.id, newParticipant);
  return res.status(201).json(newParticipant);
});

// Get participants for a competition
router.get("/competitions/:id/participants", (req: Request, res: Response) => {
  const competitionId = Number(req.params.id);

  if (isNaN(competitionId)) {
    return res.status(400).json({ error: "Invalid competition ID" });
  }

  const competition = competitions.get(competitionId);

  if (!competition) {
    return res.status(404).json({ error: "Competition not found" });
  }

  const competitionParticipants = Array.from(participants.values()).filter(
    (p) => p.competitionId === competitionId
  );

  return res.json(competitionParticipants);
});

// Update participant steps
router.put("/participants/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid participant ID" });
  }

  const participant = participants.get(id);

  if (!participant) {
    return res.status(404).json({ error: "Participant not found" });
  }

  const { steps } = req.body;

  if (typeof steps !== "number" || steps < 0) {
    return res.status(400).json({ error: "Steps must be a non-negative number" });
  }

  participant.steps = steps;
  participants.set(id, participant);
  return res.json(participant);
});

