const mockRefillRecords = [
  { id: "1", productId: "123", quantity: 50, timestamp: "2023-05-01T10:00:00Z" },
  { id: "2", productId: "456", quantity: 30, timestamp: "2023-05-02T14:30:00Z" }
];

const findRecordById = (id: string) => {
  return mockRefillRecords.find(record => record.id === id);
};

const createRecord = (record: any) => {
  const newRecord = {
    id: String(mockRefillRecords.length + 1),
    ...record
  };
  mockRefillRecords.push(newRecord);
  return newRecord;
};

const updateRecord = (id: string, updates: any) => {
  const index = mockRefillRecords.findIndex(record => record.id === id);
  if (index === -1) return null;
  mockRefillRecords[index] = { ...mockRefillRecords[index], ...updates };
  return mockRefillRecords[index];
};

const deleteRecord = (id: string) => {
  const index = mockRefillRecords.findIndex(record => record.id === id);
  if (index === -1) return false;
  mockRefillRecords.splice(index, 1);
  return true;
};

