import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect specific routes related to refill records and machine data
  const protectedPaths = [
    /^\/api\/refill-records(\/|$)/,
    /^\/api\/machines(\/|$)/
  ];

  const isProtectedPath = protectedPaths.some(path => path.test(req.path));

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Validate JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Recreate the signature
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Decode payload to get role
  try {
    const payloadStr = Buffer.from(payload, "base64url").toString("utf-8");
    const payloadObj = JSON.parse(payloadStr);

    if (!payloadObj.role) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    const userRole = payloadObj.role;

    // Define allowed roles based on endpoint
    let allowedRoles: string[] = [];

    if (req.path.startsWith("/api/refill-records") && req.method === "GET") {
      // Allow both admin and staff to view refill records
      allowedRoles = ["admin", "staff"];
    } else if (req.path.startsWith("/api/refill-records") && req.method === "POST") {
      // Only allow admin to create refill records
      allowedRoles = ["admin"];
    } else if (req.path.startsWith("/api/machines") && req.method === "GET") {
      // Allow both admin and staff to view machines
      allowedRoles = ["admin", "staff"];
    } else if (req.path.startsWith("/api/machines") && req.method === "PUT") {
      // Only allow admin to update machines
      allowedRoles = ["admin"];
    } else if (req.path.startsWith("/api/machines") && req.method === "DELETE") {
      // Only allow admin to delete machines
      allowedRoles = ["admin"];
    } else {
      // For any other protected path/method combination, deny access
      res.status(403).json({ error: "Forbidden" });
      return;
    }

    if (!allowedRoles.includes(userRole)) {
      res.status(403).json({ error: "Forbidden" });
      return;
    }

    // If we reach here, the user has proper authorization
    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // Check if request has body with credentials
  if (!req.body || !req.body.username || !req.body.password) {
    res.status(400).json({ error: "Username and password required" });
    return;
  }

  // In a real implementation, we would verify credentials against a database
  // For now, we'll just simulate a successful login
  const expectedUsername = "admin";
  const expectedPassword = "password123";

  const { username, password } = req.body;

  // Create HMAC for comparison
  const expectedHmac = createHmac("sha256", jwtSecret)
    .update(`${expectedUsername}:${expectedPassword}`)
    .digest();

  const actualHmac = createHmac("sha256", jwtSecret)
    .update(`${username}:${password}`)
    .digest();

  // Use timingSafeEqual to prevent timing attacks
  try {
    if (timingSafeEqual(expectedHmac, actualHmac)) {
      // Successful authentication - in a real app, we would generate a JWT here
      next();
    } else {
      res.status(401).json({ error: "Invalid credentials" });
    }
  } catch (error) {
    res.status(401).json({ error: "Invalid credentials" });
  }
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests without body
  if (req.method === 'GET' && !req.body) {
    return next();
  }

  // Only validate POST, PUT, PATCH requests
  if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
    return next();
  }

  // Check for potentially dangerous keys in request body
  const dangerousKeys = ['__proto__', 'constructor', 'prototype'];
  const hasDangerousKeys = Object.keys(req.body || {}).some(key => 
    dangerousKeys.includes(key)
  );

  if (hasDangerousKeys) {
    return res.status(400).json({ error: 'Invalid input data: unsafe keys detected' });
  }

  // If we reach here, validation passed
  next();
}

