import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect specific routes related to refill records and machine data
  const protectedPaths = [
    /^\/api\/refill-records(\/|$)/,
    /^\/api\/machines(\/|$)/
  ];

  const isProtectedPath = protectedPaths.some(path => path.test(req.path));

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Validate JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Recreate the signature
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Decode payload to get role
  try {
    const payloadStr = Buffer.from(payload, "base64url").toString("utf-8");
    const payloadObj = JSON.parse(payloadStr);

    if (!payloadObj.role) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    const userRole = payloadObj.role;

    // Define allowed roles based on endpoint
    let allowedRoles: string[] = [];

    if (req.path.startsWith("/api/refill-records") && req.method === "GET") {
      // Allow both admin and staff to view refill records
      allowedRoles = ["admin", "staff"];
    } else if (req.path.startsWith("/api/refill-records") && req.method === "POST") {
      // Only allow admin to create refill records
      allowedRoles = ["admin"];
    } else if (req.path.startsWith("/api/machines") && req.method === "GET") {
      // Allow both admin and staff to view machines
      allowedRoles = ["admin", "staff"];
    } else if (req.path.startsWith("/api/machines") && req.method === "PUT") {
      // Only allow admin to update machines
      allowedRoles = ["admin"];
    } else if (req.path.startsWith("/api/machines") && req.method === "DELETE") {
      // Only allow admin to delete machines
      allowedRoles = ["admin"];
    } else {
      // For any other protected path/method combination, deny access
      res.status(403).json({ error: "Forbidden" });
      return;
    }

    if (!allowedRoles.includes(userRole)) {
      res.status(403).json({ error: "Forbidden" });
      return;
    }

    // If we reach here, the user has proper authorization
    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }
}

