export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests without body
  if (req.method === 'GET' && !req.body) {
    return next();
  }

  // Only validate POST, PUT, PATCH requests
  if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
    return next();
  }

  // Check for potentially dangerous keys in request body
  const dangerousKeys = ['__proto__', 'constructor', 'prototype'];
  const hasDangerousKeys = Object.keys(req.body || {}).some(key => 
    dangerousKeys.includes(key)
  );

  if (hasDangerousKeys) {
    return res.status(400).json({ error: 'Invalid input data: unsafe keys detected' });
  }

  // If we reach here, validation passed
  next();
}

