import { useEffect, useState } from "react";

interface Order {
  id: number;
  customerName: string;
  items: string[];
  status: "pending" | "completed" | "cancelled";
  total: number;
}

export function OrdersPage() {
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | Order["status"]>("all");

  useEffect(() => {
    fetchOrders();
  }, []);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/orders");
      if (!response.ok) {
        throw new Error(`Failed to fetch orders: ${response.status}`);
      }
      const data = await response.json();
      setOrders(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const filteredOrders = orders.filter(order => {
    const matchesSearch = order.customerName.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          order.items.some(item => item.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesStatus = statusFilter === "all" || order.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  const handleStatusChange = async (orderId: number, newStatus: Order["status"]) => {
    try {
      const response = await fetch(`/api/orders/${orderId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update order: ${response.status}`);
      }

      // Refresh the orders list
      await fetchOrders();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const getStatusColor = (status: Order["status"]) => {
    switch (status) {
      case "completed":
        return "#4caf50";
      case "cancelled":
        return "#f44336";
      default:
        return "#ff9800";
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Orders</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search by customer or item..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value as "all" | Order["status"])}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Statuses</option>
          <option value="pending">Pending</option>
          <option value="completed">Completed</option>
          <option value="cancelled">Cancelled</option>
        </select>
      </div>

      {filteredOrders.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No orders found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredOrders.map((order) => (
            <div 
              key={order.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: "#f9f9f9"
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <h3 style={{ margin: "0 0 10px 0" }}>
                  {order.customerName}
                </h3>
                <span 
                  style={{ 
                    backgroundColor: getStatusColor(order.status), 
                    color: "white", 
                    padding: "4px 8px", 
                    borderRadius: "4px", 
                    fontSize: "0.9em"
                  }}
                >
                  {order.status.charAt(0).toUpperCase() + order.status.slice(1)}
                </span>
              </div>

              <p style={{ margin: "5px 0" }}>
                Items: {order.items.join(", ")}
              </p>

              <p style={{ margin: "5px 0" }}>
                Total: ${order.total.toFixed(2)}
              </p>

              <div style={{ marginTop: "10px", display: "flex", gap: "10px", flexWrap: "wrap" }}>
                <button 
                  onClick={() => handleStatusChange(order.id, "completed")}
                  disabled={order.status === "completed"}
                  style={{ 
                    backgroundColor: order.status === "completed" ? "#ccc" : "#4caf50", 
                    color: "white", 
                    border: "none", 
                    padding: "6px 12px", 
                    borderRadius: "4px", 
                    cursor: order.status === "completed" ? "default" : "pointer"
                  }}
                >
                  Complete
                </button>

                <button 
                  onClick={() => handleStatusChange(order.id, "cancelled")}
                  disabled={order.status === "cancelled"}
                  style={{ 
                    backgroundColor: order.status === "cancelled" ? "#ccc" : "#f44336", 
                    color: "white", 
                    border: "none", 
                    padding: "6px 12px", 
                    borderRadius: "4px", 
                    cursor: order.status === "cancelled" ? "default" : "pointer"
                  }}
                >
                  Cancel
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

