  { id: 3, username: "manager", password: "manager123", role: "manager" }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string; expires: Date }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate a mock session ID
  const sessionId = Math.random().toString(36).substring(2, 15);

  // Set session to expire in 1 hour
  const expires = new Date();
  expires.setHours(expires.getHours() + 1);

  sessions.set(sessionId, {
    userId: user.id,
    role: user.role,
    expires
  });

  res.status(200).json({
    sessionId,
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    }
  });
});

// Session validation middleware
const validateSession = (req: Request, res: Response, next: () => void) => {
  const sessionId = req.headers.authorization?.split(" ")[1];

  if (!sessionId) {
    return res.status(401).json({ error: "No session provided" });
  }

  const session = sessions.get(sessionId);

  if (!session) {
    return res.status(401).json({ error: "Invalid session" });
  }

  // Check if session has expired
  if (new Date() > session.expires) {
    sessions.delete(sessionId);
    return res.status(401).json({ error: "Session expired" });
  }

  // Attach user info to request
  (req as any).user = {
    id: session.userId,
    role: session.role
  };

  next();
};

// Role-based authorization middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: () => void) => {
    const user = (req as any).user;

    if (!user) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    if (user.role !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Get current user info
router.get("/me", validateSession, (req: Request, res: Response) => {
  const user = (req as any).user;

  const userData = users.find(u => u.id === user.id);

  if (!userData) {
    return res.status(404).json({ error: "User not found" });
  }

  res.status(200).json({
    id: userData.id,
    username: userData.username,
    role: userData.role
  });
});

// Logout endpoint
router.post("/logout", validateSession, (req: Request, res: Response) => {
  const sessionId = req.headers.authorization?.split(" ")[1];

  if (sessionId) {
    sessions.delete(sessionId);
  }

  res.status(200).json({ message: "Logged out successfully" });
});

