import { useEffect, useState } from "react";

interface Repair {
  id: number;
  customerName: string;
  deviceType: string;
  status: string;
  createdAt: string;
}

export function RepairsList() {
  const [repairs, setRepairs] = useState<Repair[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    fetchRepairs();
  }, []);

  const fetchRepairs = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/repairs');
      if (!response.ok) {
        throw new Error('Failed to fetch repairs');
      }
      const data = await response.json();
      setRepairs(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/repairs/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error('Failed to delete repair');
      }
      // Refresh the list after deletion
      fetchRepairs();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const filteredRepairs = repairs.filter(repair => 
    repair.customerName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    repair.deviceType.toLowerCase().includes(searchTerm.toLowerCase()) ||
    repair.status.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1 style={{ textAlign: 'center' }}>Repairs List</h1>

      <input
        type="text"
        placeholder="Search by customer name, device type, or status..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        style={{
          width: '100%',
          padding: '10px',
          marginBottom: '20px',
          borderRadius: '4px',
          border: '1px solid #ccc'
        }}
      />

      {filteredRepairs.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No repairs found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {filteredRepairs.map(repair => (
            <div 
              key={repair.id} 
              style={{
                border: '1px solid #ddd',
                borderRadius: '8px',
                padding: '15px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                flexWrap: 'wrap'
              }}
            >
              <div style={{ flex: 1, minWidth: '200px' }}>
                <h3>{repair.customerName}</h3>
                <p><strong>Device:</strong> {repair.deviceType}</p>
                <p><strong>Status:</strong> {repair.status}</p>
                <p><strong>Created:</strong> {new Date(repair.createdAt).toLocaleDateString()}</p>
              </div>
              <div style={{ display: 'flex', gap: '10px', flexShrink: 0 }}>
                <button 
                  onClick={() => window.location.href = `/repairs/${repair.id}/edit`}
                  style={{
                    backgroundColor: '#007bff',
                    color: 'white',
                    border: 'none',
                    padding: '8px 12px',
                    borderRadius: '4px',
                    cursor: 'pointer'
                  }}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(repair.id)}
                  style={{
                    backgroundColor: '#dc3545',
