import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: 1, username: "student1", password: "pass123", role: "student" },
  { id: 2, username: "admin1", password: "admin123", role: "admin" }
];

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, we would generate a JWT token here
  res.json({
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    },
    token: "mock-jwt-token"
  });
});

// Session check endpoint
router.get("/session", (req: Request, res: Response) => {
  // In a real app, we would verify the JWT token here
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "No authorization token provided" });
  }

  const token = authHeader.split(" ")[1];

  // Mock validation - in reality, this would decode and validate the token
  if (token !== "mock-jwt-token") {
    return res.status(401).json({ error: "Invalid token" });
  }

  // For demo purposes, we'll just return a mock user
  res.json({
    user: {
      id: 1,
      username: "student1",
      role: "student"
    }
