];

const findCourseById = (id: string) => courses.find(course => course.id === id);

const createCourse = (course: Omit<typeof courses[0], "id" | "enrolled">) => {
  const newCourse = {
    id: (courses.length + 1).toString(),
    ...course,
    enrolled: 0
  };
  courses.push(newCourse);
