      {submitSuccess ? (
        <div style={{
          backgroundColor: '#d4edda',
          borderColor: '#c3e6cb',
          color: '#155724',
          padding: '15px',
          borderRadius: '5px',
          border: '1px solid transparent',
          marginBottom: '20px',
