      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
        <div>
          <h2>Available Courses</h2>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
            {courses.map(course => (
              <div 
                key={course.id}
                style={{
                  border: selectedCourses.includes(course.id) ? '2px solid #007bff' : '1px solid #ccc',
                  borderRadius: '5px',
                  padding: '10px',
                  flex: '1 1 200px',
                  minWidth: '200px',
                }}
              >
                <label style={{ display: 'flex', alignItems: 'center', cursor: 'pointer' }}>
                  <input
                    type="checkbox"
                    checked={selectedCourses.includes(course.id)}
                    onChange={() => handleCourseToggle(course.id)}
                    style={{ marginRight: '8px' }}
                  />
                  <div>
                    <strong>{course.id}</strong>: {course.name}
                    <br />
                    <small>{course.credits} credits</small>
                  </div>
                </label>
              </div>
            ))}
          </div>
        </div>

        {error && (
          <div style={{
            backgroundColor: '#f8d7da',
            borderColor: '#f5c6cb',
            color: '#721c24',
            padding: '15px',
            borderRadius: '5px',
            border: '1px solid transparent',
          }}>
            {error}
          </div>
        )}

        <button 
          type="submit" 
          disabled={isSubmitting}
          style={{
            backgroundColor: '#007bff',
            color: 'white',
            border: 'none',
            padding: '12px 20px',
            borderRadius: '5px',
            cursor: isSubmitting ? 'not-allowed' : 'pointer',
            fontSize: '16px',
            fontWeight: 'bold',
          }}
        >
          {isSubmitting ? 'Registering...' : 'Register for Selected Courses'}
        </button>
      </form>

      <div style={{ marginTop: '20px', paddingTop: '20px', borderTop: '1px solid #eee' }}>
        <h3>Registration Information</h3>
        <p>
          Please select the courses you wish to register for from the list above. 
          You must select at least one course to complete registration. 
          Once registered, you will receive a confirmation email with your schedule.
        </p>
      </div>
    </div>
  );
}

