import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-POST/PUT/PATCH requests
  if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
    return next();
  }

  // Skip validation for specific paths that don't need it
  const skipPaths = ["/login", "/register"];
  if (skipPaths.includes(req.path)) {
    return next();
  }

  // Validate request body for required fields
  if (req.body && typeof req.body === 'object') {
    // Example validation: ensure required fields exist
    if (req.path.startsWith('/courses')) {
      if (!req.body.courseCode || !req.body.courseName) {
        return res.status(400).json({ error: "Missing required course fields" });
      }
    }

    // Example validation: sanitize input
    if (req.body.description) {
      req.body.description = sanitizeInput(req.body.description);
    }
  }

  // Validate JWT token if present
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith('Bearer ')) {
    const token = authHeader.substring(7);
    try {
      // Check if JWT secret is set
      if (!process.env.JWT_SECRET) {
        return res.status(500).json({ error: "Server configuration error" });
      }

      // Basic token format check
      const parts = token.split('.');
      if (parts.length !== 3) {
        return res.status(401).json({ error: "Invalid token format" });
      }

      // Verify token signature
      const [header, payload, signature] = parts;
      const expectedSignature = createHmac('sha256', process.env.JWT_SECRET)
        .update(`${header}.${payload}`)
        .digest('base64url');

      const expectedBuffer = Buffer.from(expectedSignature, 'base64url');
      const actualBuffer = Buffer.from(signature, 'base64url');

      if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
        return res.status(401).json({ error: "Invalid token signature" });
      }

      // Token is valid, proceed
      next();
    } catch (err) {
      return res.status(401).json({ error: "Invalid token" });
    }
  } else {
    // No token provided, but we're not enforcing auth here
    next();
  }
}

function sanitizeInput(input: string): string {
  // Remove potentially dangerous characters
  return input.replace(/[<>'"&]/g, '');
}

