import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: "1", username: "admin", password: "admin123", role: "admin" },
  { id: "2", username: "user", password: "user123", role: "user" }
];

// Helper to generate mock JWT token
const generateToken = (userId: string): string => {
  return `token_${userId}`;
};

// Registration route
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role = "user" } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const existingUser = users.find(u => u.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "Username already exists" });
  }

  const newUser = {
    id: `${users.length + 1}`,
    username,
    password,
    role
  };

  users.push(newUser);
  const token = generateToken(newUser.id);

  return res.status(201).json({ token, user: { id: newUser.id, username, role } });
});

// Login route
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  const token = generateToken(user.id);
  return res.json({ token, user: { id: user.id, username, role: user.role } });
});

// Middleware to verify token (mock implementation)
const authenticateToken = (req: Request, res: Response, next: Function) => {
  // In a real app, we'd decode the JWT and verify it
  const authHeader = req.headers["authorization"];
  const token = authHeader && authHeader.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "Access token required" });
  }

  // Mock verification - in reality, this would decode and validate the token
  const userId = token.replace("token_", "");
  (req as any).userId = userId;
  next();
};

// Get user profile
router.get("/profile", authenticateToken, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({ id: user.id, username: user.username, role: user.role });
});

// Update user profile
router.put("/profile", authenticateToken, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  const { username, password } = req.body;

  if (username) user.username = username;
  if (password) user.password = password;

  return res.json({ id: user.id, username: user.username, role: user.role });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    const userId = (req as any).userId;
    const user = users.find(u => u.id === userId);

    if (!user || user.role !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Admin-only route example
router.get("/admin", authenticateToken, requireRole("admin"), (req: Request, res: Response) => {
  return res.json({ message: "Admin access granted" });
});

