export const router = Router();

// Mock transaction data storage
let transactions: any[] = [];
let nextId = 1;

// Helper to find transaction by ID
const findTransactionIndex = (id: number): number => {
  return transactions.findIndex(t => t.id === id);
};

// GET /transactions - List all transactions
router.get("/transactions", (req: Request, res: Response) => {
  res.json(transactions);
});

// GET /transactions/:id - Get one transaction by ID
router.get("/transactions/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = findTransactionIndex(id);

  if (index === -1) {
    return res.status(404).json({ error: "Transaction not found" });
  }

  res.json(transactions[index]);
});

// POST /transactions - Create a new transaction
router.post("/transactions", (req: Request, res: Response) => {
  const { symbol, quantity, price, type } = req.body;

  // Validate required fields
  if (!symbol || !quantity || !price || !type) {
    return res.status(400).json({ error: "Missing required fields: symbol, quantity, price, type" });
  }

  // Validate numeric fields
  const quantityNum = Number(quantity);
  const priceNum = Number(price);

  if (isNaN(quantityNum) || isNaN(priceNum)) {
    return res.status(400).json({ error: "Quantity and price must be numbers" });
  }

  // Create new transaction
  const newTransaction = {
    id: nextId++,
    symbol,
    quantity: quantityNum,
    price: priceNum,
    type,
    date: new Date().toISOString()
  };

  transactions.push(newTransaction);

  res.status(201).json(newTransaction);
});

// PUT /transactions/:id - Update a transaction
router.put("/transactions/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = findTransactionIndex(id);

  if (index === -1) {
    return res.status(404).json({ error: "Transaction not found" });
  }

  const { symbol, quantity, price, type } = req.body;

  // Validate required fields
  if (!symbol || !quantity || !price || !type) {
    return res.status(400).json({ error: "Missing required fields: symbol, quantity, price, type" });
  }

  // Validate numeric fields
  const quantityNum = Number(quantity);
  const priceNum = Number(price);

  if (isNaN(quantityNum) || isNaN(priceNum)) {
    return res.status(400).json({ error: "Quantity and price must be numbers" });
  }

  // Update transaction
  transactions[index] = {
    ...transactions[index],
    symbol,
    quantity: quantityNum,
    price: priceNum,
    type,
    date: new Date().toISOString()
  };

  res.json(transactions[index]);
});

// DELETE /transactions/:id - Delete a transaction
router.delete("/transactions/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = findTransactionIndex(id);

  if (index === -1) {
    return res.status(404).json({ error: "Transaction not found" });
  }

  const deletedTransaction = transactions.splice(index, 1)[0];

  res.json(deletedTransaction);
});

// GET /transactions/portfolio - Calculate portfolio impact
router.get("/transactions/portfolio", (req: Request, res: Response) => {
  // Simple portfolio calculation
  let totalValue = 0;
  let totalCost = 0;

  transactions.forEach(transaction => {
    const value = transaction.quantity * transaction.price;
    totalValue += value;

    // For simplicity, assume cost is same as value
    totalCost += value;
  });

  const profitLoss = totalValue - totalCost;

  res.json({
    totalValue,
    totalCost,
    profitLoss
  });
});

