import { useEffect, useState } from "react";

interface Stock {
  symbol: string;
  name: string;
  price: number;
}

export function StockSearch() {
  const [searchTerm, setSearchTerm] = useState("");
  const [stocks, setStocks] = useState<Stock[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (searchTerm.trim() === "") {
      setStocks([]);
      return;
    }

    setLoading(true);
    setError("");

    // Simulate API call
    const timer = setTimeout(() => {
      try {
        // In a real app, this would be fetch(`/api/stocks/search?query=${searchTerm}`)
        // Mock data based on search term
        const mockStocks: Stock[] = [
          { symbol: "AAPL", name: "Apple Inc.", price: 175.43 },
          { symbol: "MSFT", name: "Microsoft Corporation", price: 338.11 },
          { symbol: "GOOGL", name: "Alphabet Inc.", price: 139.21 },
          { symbol: "AMZN", name: "Amazon.com Inc.", price: 145.83 },
          { symbol: "TSLA", name: "Tesla Inc.", price: 248.50 },
        ];

        const filteredStocks = mockStocks.filter(stock => 
          stock.symbol.toLowerCase().includes(searchTerm.toLowerCase()) ||
          stock.name.toLowerCase().includes(searchTerm.toLowerCase())
        );

        setStocks(filteredStocks);
        setLoading(false);
      } catch (err) {
        setError("Failed to fetch stocks. Please try again later.");
        setLoading(false);
      }
    }, 500);

    return () => clearTimeout(timer);
  }, [searchTerm]);

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Search is handled by useEffect when searchTerm changes
  };

  return (
    <div style={{
      fontFamily: 'system-ui, sans-serif',
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
    }}>
      <h1>Stock Search</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '20px' }}>
        <input
          type="text"
          value={searchTerm}
          onChange={handleSearchChange}
          placeholder="Search for stocks by symbol or name..."
          style={{
            width: '100%',
            padding: '10px',
            borderRadius: '4px',
            border: '1px solid #ccc',
            fontSize: '16px',
          }}
        />
      </form>

      {loading && <p>Loading...</p>}

      {error && <p style={{ color: 'red' }}>{error}</p>}

      {!loading && !error && (
        <>
          {stocks.length === 0 && searchTerm.trim() !== "" ? (
            <p>No stocks found matching "{searchTerm}"</p>
          ) : null}

          <div style={{
            display: 'flex',
            flexDirection: 'column',
            gap: '10px',
          }}>
            {stocks.map((stock) => (
              <div 
                key={stock.symbol}
                style={{
                  border: '1px solid #ddd',
                  borderRadius: '8px',
                  padding: '15px',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                }}
              >
                <div>
                  <h3 style={{ margin: '0 0 5px 0' }}>{stock.name}</h3>
                  <p style={{ margin: '0', color: '#666' }}>
                    Symbol: {stock.symbol}
                  </p>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <p style={{ margin: '0', fontWeight: 'bold' }}>
                    ${stock.price.toFixed(2)}
                  </p>
                  <button 
                    style={{
                      backgroundColor: '#007bff',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      padding: '8px 12px',
                      marginTop: '5px',
                      cursor: 'pointer',
                    }}
                    onClick={() => {
                      // In a real app, this would add the stock to a portfolio
                      alert(`Added ${stock.symbol} to your portfolio!`);
