import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const MAX_REQUESTS = 100;
const TIME_WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const RATE_LIMITS: Map<string, { count: number; windowStart: number }> = new Map();

function getRateLimitKey(req: Request): string {
  const ip = req.ip || req.connection.remoteAddress || "unknown";
  const userAgent = req.get("User-Agent") || "unknown";
  return `${ip}:${userAgent}`;
}

function isTokenValid(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) return false;

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) return false;

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const actualSignature = signature;
    return timingSafeEqual(
      Buffer.from(expectedSignature),
      Buffer.from(actualSignature)
    );
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply rate limiting to POST requests with a token in Authorization header
  if (req.method !== "POST" || !req.header("Authorization")) {
    return next();
  }

  const token = req.header("Authorization").split(" ")[1];
  if (!token || !isTokenValid(token)) {
    return next();
  }

  const key = getRateLimitKey(req);
  const now = Date.now();
  const limitInfo = RATE_LIMITS.get(key);

  if (!limitInfo) {
    RATE_LIMITS.set(key, { count: 1, windowStart: now });
    return next();
  }

  const { count, windowStart } = limitInfo;

  if (now - windowStart > TIME_WINDOW_MS) {
    RATE_LIMITS.set(key, { count: 1, windowStart: now });
    return next();
  }

  if (count >= MAX_REQUESTS) {
    return res.status(429).json({
      error: "Too many requests",
    });
  }

  RATE_LIMITS.set(key, { count: count + 1, windowStart });
  return next();
}

