import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./dev.sqlite");

interface UserRow {
  id: number;
  email: string;
  password_hash: string;
  full_name: string;
  hourly_rate: number;
  timezone: string;
  created_at: string;
  updated_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    full_name TEXT NOT NULL,
    hourly_rate REAL NOT NULL,
    timezone TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllUsers(): UserRow[] {
  const stmt = db.prepare(`SELECT * FROM users`);
  return stmt.all() as unknown as UserRow[];
}

export function getUserById(id: number): UserRow | undefined {
  const stmt = db.prepare(`SELECT * FROM users WHERE id = ?`);
  return stmt.get(id) as unknown as UserRow | undefined;
}

export function insertUser(
  email: string,
  passwordHash: string,
  fullName: string,
  hourlyRate: number,
  timezone: string
): number {
  const stmt = db.prepare(
    `INSERT INTO users (email, password_hash, full_name, hourly_rate, timezone, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, datetime('now'), datetime('now'))`
  );
  const result = stmt.run(email, passwordHash, fullName, hourlyRate, timezone);
  return Number(result.lastInsertRowid);
}

export function updateUser(
  id: number,
  email: string,
  passwordHash: string,
  fullName: string,
  hourlyRate: number,
  timezone: string
): void {
  const stmt = db.prepare(
    `UPDATE users 
     SET email = ?, password_hash = ?, full_name = ?, hourly_rate = ?, timezone = ?, updated_at = datetime('now')
     WHERE id = ?`
  );
  stmt.run(email, passwordHash, fullName, hourlyRate, timezone, id);
}

export function deleteUser(id: number): void {
  const stmt = db.prepare(`DELETE FROM users WHERE id = ?`);
  stmt.run(id);
}

