  const stmt = db.prepare("SELECT * FROM projects WHERE id = ?");
  return stmt.get(id) as unknown as ProjectRow | undefined;
}

export function insertProject(project: Omit<ProjectRow, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO projects (name, description, client_name, client_email, hourly_rate) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(
    project.name,
    project.description,
    project.client_name,
    project.client_email,
    project.hourly_rate
  );
  return Number(result.lastInsertRowid);
}

