import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./time-tracker.db");

interface TimeEntry {
  id: number;
  projectId: number;
  startTime: string;
  endTime: string;
  duration: number;
  notes: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS time_entries (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    projectId INTEGER NOT NULL,
    startTime TEXT NOT NULL,
    endTime TEXT NOT NULL,
    duration INTEGER NOT NULL,
    notes TEXT
  )
`;

db.exec(createTableSql);

export function getAllTimeEntries(): TimeEntry[] {
  const stmt = db.prepare("SELECT * FROM time_entries");
  return stmt.all() as unknown as TimeEntry[];
}

export function getTimeEntryById(id: number): TimeEntry | undefined {
  const stmt = db.prepare("SELECT * FROM time_entries WHERE id = ?");
  return stmt.get(id) as unknown as TimeEntry | undefined;
}

export function insertTimeEntry(
  projectId: number,
  startTime: string,
  endTime: string,
  duration: number,
  notes: string
): number {
  const stmt = db.prepare(
    "INSERT INTO time_entries (projectId, startTime, endTime, duration, notes) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(projectId, startTime, endTime, duration, notes);
  return Number(result.lastInsertRowid);
}

export function updateTimeEntry(
  id: number,
  projectId: number,
  startTime: string,
  endTime: string,
  duration: number,
  notes: string
): void {
  const stmt = db.prepare(
    "UPDATE time_entries SET projectId = ?, startTime = ?, endTime = ?, duration = ?, notes = ? WHERE id = ?"
  );
  stmt.run(projectId, startTime, endTime, duration, notes, id);
}

export function deleteTimeEntry(id: number): void {
  const stmt = db.prepare("DELETE FROM time_entries WHERE id = ?");
  stmt.run(id);
}

