import { Router, type Request, type Response } from "express";
import { getAllTimeEntries } from "../db/time-entries-table";
import { getAllProjects } from "../db/projects-table";
import { getAllUsers } from "../db/users-table";

export const router = Router();

router.get("/earnings", (req: Request, res: Response) => {
  const { startDate, endDate } = req.query;

  if (!startDate || !endDate) {
    return res.status(400).json({ error: "Start date and end date are required" });
  }

  const timeEntries = getAllTimeEntries();
  const projects = getAllProjects();
  const users = getAllUsers();

  // Filter entries by date range
  const filteredEntries = timeEntries.filter(entry => {
    const entryDate = new Date(entry.startTime);
    const start = new Date(startDate as string);
    const end = new Date(endDate as string);
    return entryDate >= start && entryDate <= end;
  });

  // Group entries by user and calculate earnings
  const earningsByUser: Record<number, { totalHours: number; totalEarnings: number }> = {};

  filteredEntries.forEach(entry => {
    const project = projects.find(p => p.id === entry.projectId);
    if (!project) return;

    const user = users.find(u => u.id === project.userId);
    if (!user) return;

    const userId = project.userId;
    const hours = entry.duration / 3600; // Convert seconds to hours
    const earnings = hours * user.hourlyRate;

    if (!earningsByUser[userId]) {
      earningsByUser[userId] = { totalHours: 0, totalEarnings: 0 };
    }

    earningsByUser[userId].totalHours += hours;
    earningsByUser[userId].totalEarnings += earnings;
  });

  // Format response
  const result = Object.entries(earningsByUser).map(([userId, data]) => ({
    userId: Number(userId),
    totalHours: data.totalHours,
    totalEarnings: data.totalEarnings
  }));

  res.json(result);
});

router.get("/time", (req: Request, res: Response) => {
  const { startDate, endDate } = req.query;

  if (!startDate || !endDate) {
    return res.status(400).json({ error: "Start date and end date are required" });
  }

  const timeEntries = getAllTimeEntries();
  const projects = getAllProjects();

  // Filter entries by date range
  const filteredEntries = timeEntries.filter(entry => {
    const entryDate = new Date(entry.startTime);
    const start = new Date(startDate as string);
    const end = new Date(endDate as string);
    return entryDate >= start && entryDate <= end;
  });

  // Group entries by project and calculate total time
  const timeByProject: Record<number, number> = {};

  filteredEntries.forEach(entry => {
    const project = projects.find(p => p.id === entry.projectId);
    if (!project) return;

    const projectId = project.id;
    if (!timeByProject[projectId]) {
      timeByProject[projectId] = 0;
    }

    timeByProject[projectId] += entry.duration;
  });

  // Format response
  const result = Object.entries(timeByProject).map(([projectId, totalTime]) => ({
    projectId: Number(projectId),
    totalTime
  }));

  res.json(result);
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST /login and GET /profile routes
  if (!(req.method === "POST" && req.path === "/login") && !(req.method === "GET" && req.path === "/profile")) {
    return next();
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
  }

  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      return res.status(401).json({ error: "Unauthorized: Invalid token" });
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Unauthorized: Invalid token" });
    }

    // If we get here, the token is valid
    next();
  } catch (err) {
    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

