import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const MAX_REQUESTS = 100;
const TIME_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

// In-memory storage for rate limiting
const requestCounts: Map<string, { count: number; windowStart: number }> = new Map();

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply rate limiting to POST requests with a body
  if (req.method !== "POST" || !req.body) {
    return next();
  }

  const clientIP = getClientIP(req);
  const now = Date.now();

  // Initialize or update request count for this IP
  const stored = requestCounts.get(clientIP);
  let count = 0;
  let windowStart = now;

  if (stored) {
    const { count: storedCount, windowStart: storedWindowStart } = stored;

    // Reset window if it's been longer than TIME_WINDOW_MS
    if (now - storedWindowStart > TIME_WINDOW_MS) {
      count = 0;
      windowStart = now;
    } else {
      count = storedCount;
      windowStart = storedWindowStart;
    }
  }

  // Increment count
  count++;

  // Check if we've exceeded the limit
  if (count > MAX_REQUESTS) {
    res.status(429).json({ error: "Too many requests" });
    return;
  }

  // Update the stored data
  requestCounts.set(clientIP, { count, windowStart });

  // Continue to next middleware/route handler
  next();
}

function getClientIP(req: Request): string {
  // Try to get IP from X-Forwarded-For header (common with proxies)
  const forwarded = req.header("X-Forwarded-For");
  if (forwarded) {
    return forwarded.split(",")[0].trim();
  }

  // Fallback to X-Real-IP header
  const realIP = req.header("X-Real-IP");
  if (realIP) {
    return realIP;
  }

  // Fallback to req.connection.remoteAddress or req.socket.remoteAddress
  return (
    req.connection?.remoteAddress ||
    req.socket?.remoteAddress ||
    "127.0.0.1"
  );
}

