import { useEffect, useState } from "react";

interface Project {
  id: string;
  name: string;
}

interface TimeEntry {
  id: string;
  projectId: string;
  startTime: string;
  endTime: string | null;
  duration: number | null;
}

export function TimeTrackingInterface() {
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [selectedProjectId, setSelectedProjectId] = useState<string>("");
  const [projects, setProjects] = useState<Project[]>([]);
  const [timeEntries, setTimeEntries] = useState<TimeEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Load projects and time entries
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [projectsResponse, entriesResponse] = await Promise.all([
          fetch("/api/projects-api/"),
          fetch("/api/time-entries-api/")
        ]);

        if (!projectsResponse.ok || !entriesResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const [projectsData, entriesData] = await Promise.all([
          projectsResponse.json(),
          entriesResponse.json()
        ]);

        setProjects(projectsData);
        setTimeEntries(entriesData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  // Timer effect
  useEffect(() => {
    let interval: NodeJS.Timeout | null = null;

    if (isTimerRunning) {
      interval = setInterval(() => {
        setElapsedTime(prev => prev + 1);
      }, 1000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isTimerRunning]);

  const formatTime = (seconds: number): string => {
    const hrs = Math.floor(seconds / 3600);
    const mins = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;

    return `${hrs.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleStartTimer = async () => {
    if (!selectedProjectId) {
      setError("Please select a project first");
      return;
    }

    try {
      const response = await fetch("/api/timer-service/start", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ projectId: selectedProjectId })
      });

      if (!response.ok) {
        throw new Error("Failed to start timer");
      }

      setIsTimerRunning(true);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleStopTimer = async () => {
    try {
      const response = await fetch("/api/timer-service/stop", {
        method: "POST",
        headers: { "Content-Type": "application/json" }
      });

      if (!response.ok) {
        throw new Error("Failed to stop timer");
      }

      setIsTimerRunning(false);
      setElapsedTime(0);
      setError(null);

      // Refresh time entries
      const entriesResponse = await fetch("/api/time-entries-api/");
      if (entriesResponse.ok) {
        const entriesData = await entriesResponse.json();
        setTimeEntries(entriesData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleManualEntry = async () => {
    if (!selectedProjectId) {
      setError("Please select a project first");
      return;
    }

    try {
      const response = await fetch("/api/time-entries-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          projectId: selectedProjectId,
          duration: elapsedTime
        })
      });

      if (!response.ok) {
        throw new Error("Failed to create manual entry");
      }

      setElapsedTime(0);
      setSelectedProjectId("");
      setError(null);

      // Refresh time entries
      const entriesResponse = await fetch("/api/time-entries-api/");
      if (entriesResponse.ok) {
        const entriesData = await entriesResponse.json();
        setTimeEntries(entriesData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Time Tracking</h1>

      <div style={{ marginBottom: "20px", padding: "15px", backgroundColor: "#f5f5f5", borderRadius: "8px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "10px" }}>
          <span style={{ fontSize: "24px", fontWeight: "bold" }}>{formatTime(elapsedTime)}</span>
          <div style={{ display: "flex", gap: "10px" }}>
            {!isTimerRunning ? (
              <button 
                onClick={handleStartTimer}
                style={{ padding: "8px 16px", backgroundColor: "#4CAF50", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
              >
                Start Timer
              </button>
            ) : (
              <button 
                onClick={handleStopTimer}
                style={{ padding: "8px 16px", backgroundColor: "#f44336", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
              >
                Stop Timer
              </button>
            )}
          </div>
        </div>

        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Select Project:</label>
          <select 
            value={selectedProjectId}
            onChange={(e) => setSelectedProjectId(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">-- Select Project --</option>
            {projects.map(project => (
              <option key={project.id} value={project.id}>{project.name}</option>
            ))}
          </select>
        </div>

        <button 
          onClick={handleManualEntry}
          style={{ width: "100%", padding: "10px", backgroundColor: "#2196F3", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
        >
          Save Manual Entry
        </button>
      </div>

      <h2>Recent Time Entries</h2>

      {timeEntries.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No time entries found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {timeEntries.map(entry => (
            <div 
              key={entry.id} 
              style={{ 
                padding: "10px", 
                border: "1px solid #ddd", 
                borderRadius: "4px",
                display: "flex",
                justifyContent: "space-between"
              }}
            >
              <div>
                <strong>{projects.find(p => p.id === entry.projectId)?.name || "Unknown Project"}</strong>
                <br />
                {entry.startTime} - {entry.endTime || "Ongoing"}
              </div>
              <div>
                {entry.duration ? `${Math.floor(entry.duration / 60)}m ${entry.duration % 60}s` : "N/A"}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

