import { getUserById } from "../db/users-table";

export const router = Router();

// Get all projects
router.get("/", jwtAuth, (req: Request, res: Response) => {
  try {
    const projects = getAllProjects();
    res.json(projects);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch projects" });
  }
});

// Get a project by ID
router.get("/:id", jwtAuth, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid project ID" });
    }

    const project = getProjectById(id);
    if (!project) {
      return res.status(404).json({ error: "Project not found" });
    }

    res.json(project);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch project" });
  }
});

// Create a new project
router.post("/", [jwtAuth, dataEncryption, rateLimiting], (req: Request, res: Response) => {
  try {
    const { name, description, client_id, hourly_rate } = req.body;

    // Validate required fields
    if (!name || !client_id) {
      return res.status(400).json({ error: "Name and client_id are required" });
    }

    // Validate numeric fields
    if (hourly_rate !== undefined && isNaN(hourly_rate)) {
      return res.status(400).json({ error: "Hourly rate must be a number" });
    }

    const newProject = {
      name,
      description: description || null,
      client_id,
      hourly_rate: hourly_rate || null
    };

    const projectId = insertProject(newProject);

    // Fetch the created project to send back
    const createdProject = getProjectById(projectId);

    if (!createdProject) {
      return res.status(500).json({ error: "Failed to retrieve created project" });
    }

    res.status(201).json(createdProject);
  } catch (error) {
    res.status(500).json({ error: "Failed to create project" });
  }
});

// Update a project
router.put("/:id", [jwtAuth, dataEncryption, rateLimiting], (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid project ID" });
    }

    const project = getProjectById(id);
    if (!project) {
      return res.status(404).json({ error: "Project not found" });
    }

    const { name, description, client_id, hourly_rate } = req.body;

    const updates: Partial<Omit<ProjectRow, "id">> = {};
    if (name !== undefined) updates.name = name;
    if (description !== undefined) updates.description = description;
    if (client_id !== undefined) updates.client_id = client_id;
    if (hourly_rate !== undefined) updates.hourly_rate = hourly_rate;

    const updated = updateProject(id, updates);

    if (!updated) {
      return res.status(500).json({ error: "Failed to update project" });
    }

    const updatedProject = getProjectById(id);

    if (!updatedProject) {
      return res.status(500).json({ error: "Failed to retrieve updated project" });
    }

    res.json(updatedProject);
  } catch (error) {
    res.status(500).json({ error: "Failed to update project" });
  }
});

