export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // Simulate token verification (in a real implementation, this would verify the actual JWT signature)
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  // Create expected HMAC for demonstration purposes
  const expectedHmac = createHmac("sha256", jwtSecret).update(token).digest();

  // In a real implementation, we would decode the token and verify its signature
  // For now, we'll just simulate a timing-safe comparison
  try {
    const tokenHmac = createHmac("sha256", jwtSecret).update(token).digest();
    const isEqual = timingSafeEqual(expectedHmac, tokenHmac);

    if (!isEqual) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
