import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to admin routes
  if (!req.path.startsWith('/admin')) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  try {
    const [payload, signature] = token.split('.');
    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const expectedSignature = createHmac('sha256', secret)
      .update(payload)
      .digest('base64url');

    const signatureBuffer = Buffer.from(signature, 'base64url');
    const expectedSignatureBuffer = Buffer.from(expectedSignature, 'base64url');

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // Token is valid, proceed to next middleware
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  {
    id: 1,
    username: "admin",
    password: "admin123",
    role: "admin"
  },
  {
    id: 2,
    username: "contractor",
    password: "contractor123",
    role: "contractor"
  }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string }>();

// User registration
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);

  return res.status(201).json({ message: "User registered successfully" });
});

// User login
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = Math.random().toString(36).substring(2, 15);
  sessions.set(token, { userId: user.id, role: user.role });

  return res.json({ token, role: user.role });
});

// Session validation middleware
const authenticate = (req: Request, res: Response, next: Function) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "No authorization token provided" });
  }

  const session = sessions.get(token);
  if (!session) {
    return res.status(401).json({ error: "Invalid or expired session" });
  }

  (req as any).userId = session.userId;
  (req as any).role = session.role;
  next();
};

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    const userRole = (req as any).role;
    if (!roles.includes(userRole)) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }
    next();
  };
};

// Get user profile (protected route)
router.get("/profile", authenticate, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({
    id: user.id,
    username: user.username,
    role: user.role
  });
});

// Logout (clear session)
router.post("/logout", authenticate, (req: Request, res: Response) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (token) {
    sessions.delete(token);
  }

  return res.json({ message: "Logged out successfully" });
});

