import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/projects", "/tasks"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check HTTP method
  const allowedMethods = ["GET", "POST", "PUT", "DELETE"];
  if (!allowedMethods.includes(req.method)) {
    next();
    return;
  }

  // For demonstration purposes, we'll simulate role checking
  // In a real implementation, this would extract roles from a token or session
  const userRole = req.headers["x-user-role"] as string || "client";

  // Define role permissions
  const permissions: Record<string, string[]> = {
    admin: ["GET", "POST", "PUT", "DELETE"],
    staff: ["GET", "POST", "PUT"],
    client: ["GET"]
  };

  // Check if the user's role has permission for the requested method
  const hasPermission = permissions[userRole]?.includes(req.method);

  if (!hasPermission) {
    res.status(403).json({
      error: "Forbidden: Insufficient permissions"
    });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to hash passwords during user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using scrypt
  const salt = randomBytes(16).toString("hex");
  const key = scryptSync(req.body.password, salt, 32);
  const hashedPassword = key.toString("hex");

  // Replace the plain text password with the hashed one
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

