import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to the /submit-paper route
  if (req.method !== "POST" || req.path !== "/submit-paper") {
    next();
    return;
  }

  // Check if file upload is present
  if (!req.files || Object.keys(req.files).length === 0) {
    return res.status(400).json({ error: "No file uploaded" });
  }

  // Get the file from the request
  const file = Array.isArray(req.files.file) ? req.files.file[0] : req.files.file;

  // Validate file type - only allow PDF files
  if (file.mimetype !== "application/pdf") {
    return res.status(400).json({ error: "Only PDF files are allowed" });
  }

  // Validate file size - max 10MB
  const maxSize = 10 * 1024 * 1024; // 10MB in bytes
  if (file.size > maxSize) {
    return res.status(400).json({ error: "File size exceeds 10MB limit" });
  }

  // If all validations pass, continue to next middleware/route handler
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST requests to /submit-paper
  if (req.method !== "POST" || req.path !== "/submit-paper") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT properly
  // For this example, we'll just check if it matches expected format
  const [userId, userRole] = token.split(":");

  if (!userId || !userRole) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // Check if user has required role
  if (userRole !== "author" && userRole !== "admin") {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  // Attach user info to request for downstream middleware/routes
  (req as any).user = { id: userId, role: userRole };

  next();
}

