import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to the /submit-paper route
  if (req.method !== "POST" || req.path !== "/submit-paper") {
    next();
    return;
  }

  // Check if file upload is present
  if (!req.files || Object.keys(req.files).length === 0) {
    return res.status(400).json({ error: "No file uploaded" });
  }

  // Get the file from the request
  const file = Array.isArray(req.files.file) ? req.files.file[0] : req.files.file;

  // Validate file type - only allow PDF files
  if (file.mimetype !== "application/pdf") {
    return res.status(400).json({ error: "Only PDF files are allowed" });
  }

  // Validate file size - max 10MB
  const maxSize = 10 * 1024 * 1024; // 10MB in bytes
  if (file.size > maxSize) {
    return res.status(400).json({ error: "File size exceeds 10MB limit" });
  }

  // If all validations pass, continue to next middleware/route handler
  next();
}

