import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users = [
  { id: 1, username: "admin", password: "admin123", role: "administrator" },
  { id: 2, username: "accountant", password: "pass456", role: "accountant" },
  { id: 3, username: "manager", password: "mgr789", role: "manager" }
];

// Mock session store - in a real app this would be a proper session store
const sessions = new Map<string, { userId: number; role: string; expires: Date }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate a mock session ID
  const sessionId = Math.random().toString(36).substring(2, 15);
  const expires = new Date();
  expires.setHours(expires.getHours() + 1); // Session expires in 1 hour

  sessions.set(sessionId, {
    userId: user.id,
    role: user.role,
    expires
  });

  res.json({
    sessionId,
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    }
  });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const sessionId = req.header("Authorization")?.replace("Bearer ", "");

  if (!sessionId) {
    return res.status(400).json({ error: "Session ID is required" });
  }

  if (!sessions.has(sessionId)) {
    return res.status(401).json({ error: "Invalid session" });
  }

  sessions.delete(sessionId);
  res.json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: () => void) => {
  const sessionId = req.header("Authorization")?.replace("Bearer ", "");

  if (!sessionId) {
    return res.status(401).json({ error: "Session ID is required" });
  }

  const session = sessions.get(sessionId);

  if (!session) {
    return res.status(401).json({ error: "Invalid session" });
  }

  // Check if session has expired
  if (new Date() > session.expires) {
    sessions.delete(sessionId);
    return res.status(401).json({ error: "Session expired" });
  }

  // Attach user info to request
  (req as any).user = {
    id: session.userId,
    role: session.role
  };

  next();
};

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: () => void) => {
    const user = (req as any).user;

    if (!user) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    if (!roles.includes(user.role)) {
      return res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    }

    next();
  };
};

// Protected route example - GET user profile
router.get("/profile", authenticate, (req: Request, res: Response) => {
  const user = (req as any).user;
  res.json({
    id: user.id,
    username: users.find(u => u.id === user.id)?.username,
    role: user.role
  });
});

// Protected route example - GET all users (only admins)
router.get("/users", authenticate, authorize(["administrator"]), (req: Request, res: Response) => {
  res.json(users.map(u => ({ id: u.id, username: u.username, role: u.role })));
});

