import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to financial data routes
  const isFinancialRoute = req.path.startsWith('/api/financial') || 
                          req.path.startsWith('/api/accounts') ||
                          req.path.startsWith('/api/transactions');

  if ((req.method !== 'POST' && req.method !== 'PUT' && req.method !== 'DELETE') || !isFinancialRoute) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify JWT signature if secret is set
  if (!JWT_SECRET) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  try {
    // Simple verification - in a real app, use a proper JWT library
    const [header, payload, signature] = token.split('.');

    if (!header || !payload || !signature) {
      res.status(401).json({ error: 'Invalid token format' });
      return;
    }

    // Reconstruct signature for verification
    const expectedSignature = createHmac('sha256', JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest('base64url');

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, 'base64url');
    const expectedBuffer = Buffer.from(expectedSignature, 'base64url');

    if (!timingSafeEqual(signatureBuffer, expectedBuffer)) {
      res.status(401).json({ error: 'Invalid token signature' });
      return;
    }

    // Decode payload to get user role
    const decodedPayload = Buffer.from(payload, 'base64url').toString('utf8');
    const payloadObj = JSON.parse(decodedPayload);

    // Check if user has required role
    const requiredRoles = ['accountant', 'manager', 'admin'];
    if (!requiredRoles.includes(payloadObj.role)) {
      res.status(403).json({ error: 'Insufficient permissions' });
      return;
    }

    // If we get here, user is authorized
    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBytes = Buffer.from(expectedSignature, "base64url");
    const actualBytes = Buffer.from(signature, "base64url");

    return timingSafeEqual(expectedBytes, actualBytes);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /logout
  if (req.method !== "POST" || req.path !== "/logout") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  next();
}

