              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc"
            }}
          />
        </div>

        <div>
          <label htmlFor="brand" style={{ display: "block", marginBottom: "5px" }}>
            Brand
          </label>
          <input
            id="brand"
            type="text"
            value={brand}
            onChange={(e) => setBrand(e.target.value)}
            required
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc"
            }}
          />
        </div>

        <div>
          <label htmlFor="initialStock" style={{ display: "block", marginBottom: "5px" }}>
            Initial Stock
          </label>
          <input
            id="initialStock"
            type="number"
            value={initialStock}
            onChange={(e) => setInitialStock(e.target.value)}
            required
            min="0"
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc"
            }}
          />
        </div>

        <button
          type="submit"
          disabled={isSubmitting}
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            padding: "10px 15px",
            borderRadius: "4px",
            cursor: isSubmitting ? "not-allowed" : "pointer",
            fontSize: "16px"
          }}
        >
          {isSubmitting ? "Adding..." : "Add Shoe"}
        </button>
      </form>
    </div>
  );
}

import { useEffect, useState } from "react";

interface InventoryItem {
  id: number;
  name: string;
  currentStock: number;
  lowStockThreshold: number;
}

export function InventoryManagementDashboard() {
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchInventory();
  }, []);

  const fetchInventory = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/inventory');
      if (!response.ok) {
        throw new Error('Failed to fetch inventory');
      }
      const data = await response.json();
      setInventory(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateStock = async (id: number, newStock: number) => {
    try {
      const response = await fetch(`/api/inventory/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ currentStock: newStock }),
      });

      if (!response.ok) {
        throw new Error('Failed to update stock');
      }

      // Refresh the inventory list
      await fetchInventory();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (inventory.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No inventory items found.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Inventory Management Dashboard</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {inventory.map(item => (
          <div 
            key={item.id} 
            style={{ 
              border: '1px solid #ccc', 
              borderRadius: '8px', 
              padding: '15px', 
              backgroundColor: item.currentStock <= item.lowStockThreshold ? '#fff3cd' : 'white'
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <h3>{item.name}</h3>
                <p>Current Stock: {item.currentStock}</p>
                <p>Low Stock Threshold: {item.lowStockThreshold}</p>
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end' }}>
                <input
                  type="number"
                  defaultValue={item.currentStock}
                  min="0"
                  style={{ width: '100px', marginBottom: '10px' }}
                  id={`stock-${item.id}`}
                />
                <button 
                  onClick={() => {
                    const input = document.getElementById(`stock-${item.id}`) as HTMLInputElement;
                    handleUpdateStock(item.id, Number(input.value));
                  }}
                  style={{ 
                    backgroundColor: '#007bff', 
                    color: 'white', 
                    border: 'none', 
                    borderRadius: '4px', 
                    padding: '5px 10px', 
                    cursor: 'pointer'
                  }}
                >
                  Update Stock
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

