import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected routes
  const protectedPaths = ["/events", "/memberships"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // In a real implementation, we would decode the payload here
    // For now, we'll assume the token contains role info
    const decodedPayload = JSON.parse(
      Buffer.from(payload, "base64url").toString()
    );

    const userRole = decodedPayload.role;
    const allowedRoles = ["staff", "admin"];

    // Allow access based on role
    if (allowedRoles.includes(userRole)) {
      next();
      return;
    }

    // If user is not authorized
    res.status(403).json({ error: "Forbidden" });
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // In a real implementation, we would verify the JWT token here
  // For now, we'll just simulate the verification process
  // This is a placeholder for actual JWT validation logic

  // Simulate token verification
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Mock verification - in reality, this would verify HMAC-SHA256 signature
  try {
    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest("hex");

    const actualSignature = token.split(".")[2];

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(expectedSignature),
      Buffer.from(actualSignature)
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  next();
}

