import { FC, useState } from "react";

interface FormData {
  name: string;
  email: string;
  studentId: string;
  joinDate: string;
}

interface FormErrors {
  name?: string;
  email?: string;
  studentId?: string;
  joinDate?: string;
}

export function MembershipRegistrationForm() {
  const [formData, setFormData] = useState<FormData>({
    name: "",
    email: "",
    studentId: "",
    joinDate: "",
  });

  const [errors, setErrors] = useState<FormErrors>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);

  const validate = (): boolean => {
    const newErrors: FormErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = "Name is required";
    }

    if (!formData.email.trim()) {
      newErrors.email = "Email is required";
    } else if (!/^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/.test(formData.email)) {
      newErrors.email = "Invalid email format";
    }

    if (!formData.studentId.trim()) {
      newErrors.studentId = "Student ID is required";
    } else if (!/^[A-Za-z0-9]{6,12}$/.test(formData.studentId)) {
      newErrors.studentId = "Student ID must be 6-12 alphanumeric characters";
    }

    if (!formData.joinDate) {
      newErrors.joinDate = "Join date is required";
    } else {
      const selectedDate = new Date(formData.joinDate);
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      if (selectedDate > today) {
        newErrors.joinDate = "Join date cannot be in the future";
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });

    // Clear error when user starts typing
    if (errors[name as keyof FormErrors]) {
      setErrors({
        ...errors,
        [name]: undefined,
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) {
      return;
    }

    setIsSubmitting(true);
    setSubmitSuccess(false);

    try {
      // In a real app, this would be an API call
      // await fetch('/api/membership', {
      //   method: 'POST',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify(formData)
      // });

      // Simulate API delay
      await new Promise(resolve => setTimeout(resolve, 500));

      setSubmitSuccess(true);

      // Reset form after successful submission
      setFormData({
        name: "",
        email: "",
        studentId: "",
        joinDate: "",
      });
    } catch (error) {
      console.error("Failed to register membership:", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div style={containerStyle}>
      <div style={cardStyle}>
        <h2 style={headingStyle}>Club Membership Registration</h2>

        {submitSuccess ? (
          <div style={successMessageStyle}>
            Thank you! Your membership has been registered successfully.
          </div>
        ) : (
          <form onSubmit={handleSubmit} style={formStyle}>
            <div style={inputGroupStyle}>
              <label htmlFor="name" style={labelStyle}>Full Name *</label>
              <input
                type="text"
                id="name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                style={inputStyle}
                placeholder="Enter your full name"
              />
              {errors.name && <span style={errorStyle}>{errors.name}</span>}
            </div>

            <div style={inputGroupStyle}>
              <label htmlFor="email" style={labelStyle}>Email Address *</label>
              <input
                type="email"
                id="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                style={inputStyle}
                placeholder="Enter your email address"
              />
              {errors.email && <span style={errorStyle}>{errors.email}</span>}
            </div>

            <div style={inputGroupStyle}>
              <label htmlFor="studentId" style={labelStyle}>Student ID *</label>
              <input
                type="text"
                id="studentId"
                name="studentId"
                value={formData.studentId}
                onChange={handleChange}
                style={inputStyle}
                placeholder="Enter your student ID"
              />
              {errors.studentId && <span style={errorStyle}>{errors.studentId}</span>}
            </div>

            <div style={inputGroupStyle}>
              <label htmlFor="joinDate" style={labelStyle}>Join Date *</label>
              <input
                type="date"
                id="joinDate"
                name="joinDate"
                value={formData.joinDate}
                onChange={handleChange}
                style={inputStyle}
              />
              {errors.joinDate && <span style={errorStyle}>{errors.joinDate}</span>}
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              style={submitButtonStyle}
            >
              {isSubmitting ? "Registering..." : "Register Membership"}
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

