import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Define the required roles for each endpoint
const PERMISSIONS: Record<string, string[]> = {
  "/api/maintenance-records": ["admin", "technician"],
};

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST, PUT, DELETE requests to maintenance records
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") || !req.path.startsWith("/api/maintenance-records")) {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // Extract token from Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  // Verify token signature
  const secretBuffer = Buffer.from(jwtSecret);
  const tokenParts = token.split(".");
  if (tokenParts.length !== 3) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const payload = tokenParts[0] + "." + tokenParts[1];
  const signature = tokenParts[2];

  const expectedSignature = createHmac("sha256", secretBuffer)
    .update(payload)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Decode token to get user role (simplified for example)
  const decodedPayload = Buffer.from(tokenParts[1], "base64url").toString();
  let payloadObj: { role?: string } = {};
  try {
    payloadObj = JSON.parse(decodedPayload);
  } catch {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const userRole = payloadObj.role;
  if (!userRole) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Check if user has permission for the requested path
  const allowedRoles = PERMISSIONS[req.path] || [];
  if (!allowedRoles.includes(userRole)) {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Check if request has body with credentials
  if (!req.body || !req.body.username || !req.body.password) {
    res.status(400).json({ error: "Username and password required" });
    return;
  }

  // In a real implementation, we would:
  // 1. Hash the provided password with the stored salt
  // 2. Compare with stored hash
  // 3. Generate a JWT token if valid
  // 4. Set session cookie

  // For now, simulate successful authentication
  // This is a placeholder - actual implementation would involve database lookups
  const storedHash = createHmac("sha256", secret)
    .update("hashed-password")
    .digest();

  const providedHash = createHmac("sha256", secret)
    .update(req.body.password)
    .digest();

  try {
    const isValid = timingSafeEqual(storedHash, providedHash);

    if (!isValid) {
      res.status(401).json({ error: "Invalid credentials" });
      return;
    }

    // Simulate setting a session cookie
    res.cookie("session", "mock-session-token", { httpOnly: true });
    next();
  } catch (error) {
    res.status(500).json({ error: "Authentication failed" });
  }
}

